local config = {
  ui_story_5088_50880100_1_dialog_content = "<color=#e8d9bb>Por favor, lembre-se daquela história há muito esquecida.</color>",
  ui_story_5088_50880100_2_dialog_content = "<color=#e8d9bb>A história de um antigo reino à beira do desastre, e a chegada de um grupo de heróis—</color>",
  ui_story_5088_50880100_3_dialog_content = "<color=#e8d9bb>Para salvar seu reino de uma presença vil, eles voluntariamente se submeteram a perigosas melhorias.</color>",
  ui_story_5088_50880100_4_dialog_content = "<color=#e8d9bb>Mas quando a paz foi restaurada mais uma vez, os heróis foram amaldiçoados e vilipendiados como monstros, tanto em corpo quanto em mente.</color>",
  ui_story_5088_50880100_5_dialog_content = "<color=#e8d9bb>Acusados pelos sacerdotes, abandonados pelo rei e temidos pelas massas ignorantes que juraram proteger.</color>",
  ui_story_5088_50880100_6_dialog_content = "<color=#e8d9bb>Em seu desespero insondável, os heróis procuravam uns nos outros por calor e consolo, mas não havia como resistir à corrupção de sua maldição.</color>",
  ui_story_5088_50880100_7_dialog_content = "<color=#e8d9bb>Para conceder-lhes uma última chance de felicidade, seu líder e um querido amigo se sacrificaram.</color>",
  ui_story_5088_50880100_8_dialog_content = "<color=#e8d9bb>Selados além do fluxo do tempo, eles esperaram em silêncio—</color>",
  ui_story_5088_50880100_9_dialog_content = "Arf, arf...",
  ui_story_5088_50880100_10_dialog_content = "Graaaaah!",
  ui_story_5088_50880100_11_dialog_content = "<color=#e8d9bb>Primeiro dia: É chegada uma grande calamidade.</color>",
  ui_story_5088_50880100_12_dialog_content = "Isso é ruim! Eles estão alcançando—",
  ui_story_5088_50880100_13_dialog_content = "Não no meu turno!",
  ui_story_5088_50880100_14_dialog_content = "É você... O do festejo da capital real...",
  ui_story_5088_50880100_15_dialog_content = "Você consegue andar? Aqui, pegue a minha mão.",
  ui_story_5088_50880100_16_dialog_content = "... Esse herói.",
  ui_story_5088_50880100_17_dialog_content = "Eu não sou um herói, você pode me chamar de Adras.",
  ui_story_5088_50880100_18_dialog_content = "<color=#e8d9bb>Segundo dia: Heróis do destino.</color>",
  ui_story_5088_50880100_19_dialog_content = "O que houve?",
  ui_story_5088_50880100_20_dialog_content = "Nada, eu só estava ajudando este viajante.",
  ui_story_5088_50880100_21_dialog_content = "Você está bem?",
  ui_story_5088_50880100_22_dialog_content = "A cidade está segura e não foram relatadas baixas. Podemos descansar lá por enquanto.",
  ui_story_5088_50880100_23_dialog_content = "<color=#e8d9bb>Terceiro dia: Louvando as estrelas</color>",
  ui_story_5088_50880100_24_dialog_content = "Perdoe-me, mas...",
  ui_story_5088_50880100_25_dialog_content = "Ah! Ainda nem me apresentei.",
  ui_story_5088_50880100_26_dialog_content = "Meu nome é—",
  ui_story_5088_50880100_27_dialog_content = "<color=#e8d9bb>Quarto dia: Paz, mudança e tensão.</color>",
  ui_story_5088_50880100_28_dialog_content = "Aquiles... Minha cabeça está girando...",
  ui_story_5088_50880100_29_dialog_content = "Sinto muito, meu amigo... Mas tenho que te manter aqui...",
  ui_story_5088_50880100_30_dialog_content = "Economize sua força. Eu vou te levar a um médico imediatamente.",
  ui_story_5088_50880100_31_dialog_content = "N-Não, isso não será necessário. Estou tão cansado... E sinto tanta falta de casa...",
  ui_story_5088_50880100_32_dialog_content = "Então, deixe-me levá-lo para casa.",
  ui_story_5088_50880100_33_dialog_content = "Nem mais um passo, Claymore! Não foi suficiente assassinar o Senhor Lúcio e se rebelar contra o Conselho Ancião?! Renda-se, seu monstro!",
  ui_story_5088_50880100_34_dialog_content = "... Afaste-se. Não levantarei minha lâmina contra os inocentes.",
  ui_story_5088_50880100_35_dialog_content = "Então você vai pagar com o sangue que deve ao Sumo Sacerdote!",
  ui_story_5088_50880100_36_dialog_content = "<size=45>Eu disse dê o lado!</size>",
  ui_story_5088_50880100_37_dialog_content = "Urgh... Eu-Eu não consigo mover minhas pernas... O que é isso...?!",
  ui_story_5088_50880100_38_dialog_content = "O que está acontecendo, Aquiles...? Eu não consigo mais ver a cor da sua luz...",
  ui_story_5088_50880100_39_dialog_content = "Não é nada, Ludweiss. Aqui, me dê sua mão. É hora de voltar.",
  ui_story_5088_50880100_40_dialog_content = "Não, espere, eu me lembro agora... Nossos amigos são muito mais importantes. Eles ainda estão selados, então por favor, leve-os e vá...",
  ui_story_5088_50880100_41_dialog_content = "Estamos aqui, Senhor Aquiles!",
  ui_story_5088_50880100_42_dialog_content = "O que... O que diabos aconteceu aqui...?",
  ui_story_5088_50880100_43_dialog_content = "Anthony... Por que você insiste em se envolver com monstros como nós?",
  ui_story_5088_50880100_44_dialog_content = "Não faço ideia do que você está falando, Lord Aquiles. Tudo o que sei é que você precisa da minha ajuda.",
  ui_story_5088_50880100_45_dialog_content = "... Cuide bem de Adras e dos outros.",
  ui_story_5088_50880100_46_dialog_content = "Vou criar uma abertura para escapar.",
  ui_story_5088_50880100_47_dialog_content = "Vamos, Ludweiss.",
  ui_story_5088_50880100_48_dialog_content = "Acabou? O Conselho Ancião encerrou sua revolta? Eu me pergunto... As crianças vão sofrer por causa disso...?",
  ui_story_5088_50880100_49_dialog_content = "Tudo vai acabar em breve, Ludweiss. Só continue falando comigo.",
  ui_story_5088_50880100_50_dialog_content = "Conte-me mais sobre sua casa. Lembro que você uma vez a descreveu como um tipo de paraíso.",
  ui_story_5088_50880100_51_dialog_content = "Não, meu povo nunca pisou naquele lugar... Somos todos apenas exilados perdidos... Tentando desesperadamente retornar ao paraíso de nossos ancestrais...",
  ui_story_5088_50880100_52_dialog_content = "No passado, eu só conseguia lembrar da beleza de Eraveil através das memórias dos meus ancestrais... Mas agora... Eu finalmente a encontrei...",
  ui_story_5088_50880100_53_dialog_content = "A voz nos meus sonhos... Ela pertence a um garoto de Eraveil.",
  ui_story_5088_50880100_54_dialog_content = "Como eu gostaria de ver o lugar por mim mesmo.",
  ui_story_5088_50880100_55_dialog_content = "Então iremos para Eraveil juntos. Você, eu e o resto de nós.",
  ui_story_5088_50880100_56_dialog_content = "Sinto muito... Eu queria te salvar também, mas agora é tarde demais...",
  ui_story_5088_50880100_57_dialog_content = "A sua luz foi devorada. Você não pode continuar assim...",
  ui_story_5088_50880100_58_dialog_content = "Não se preocupe por minha causa.",
  ui_story_5088_50880100_59_dialog_content = "Juro que vou cumprir sua profecia e te levar para ver a beleza da sua casa pessoalmente.",
  ui_story_5088_50880100_60_dialog_content = "Se é assim que você se sente... Então estou colocando toda a minha confiança em você.",
  ui_story_5088_50880100_61_dialog_content = "Com apenas o poder da Estrela Caída restante, cabe a você tornar esse milagre realidade.",
  ui_story_5088_50880100_62_dialog_content = "Nunca perca sua fé na esperança, pois ela te guiará para fora dessa escuridão algum dia.",
  ui_story_5088_50880100_63_dialog_content = "Agora é tudo com você... Aquiles...",
  ui_story_5088_50880100_64_dialog_content = "...",
  ui_story_5088_50880100_65_dialog_content = "...",
  ui_story_5088_50880100_66_dialog_content = "<color=#e8d9bb>E este é o fim desta história condenada e trágica. Sozinho no mundo, o herói começa sua jornada sem fim...</color>",
  ui_story_5088_50880100_67_dialog_content = "Não, não essa... Essa também não é...",
  ui_story_5088_50880100_68_dialog_content = "Sei que você está com pressa, minha querida, mas por favor seja um pouco mais cuidadosa ao manusear a mercadoria. Afinal, são antiguidades.",
  ui_story_5088_50880100_69_dialog_content = "Sério? Porque eu me lembro de você usando aquele diário para forrar um baú de tesouro antes de vendê-lo para mim.",
  ui_story_5088_50880100_70_dialog_content = "Isso é apenas porque já era um item defeituoso. A escrita nele era basicamente incompreensível.",
  ui_story_5088_50880100_71_dialog_content = "E ainda assim ainda tem valor para você, não é?",
  ui_story_5088_50880100_72_dialog_content = "Mais uma remessa para você, chefe.",
  ui_story_5088_50880100_73_dialog_content = "Excelente trabalho, Casta. Qualquer lugar serve, obrigado.",
  ui_story_5088_50880100_74_dialog_content = "...",
  ui_story_5088_50880100_75_dialog_content = "PlayerName? Você está procurando algo?",
  ui_story_5088_50880100_76_dialog_content = "É uma longa história... Você vê, eu deixei Sheol me convencer a vasculhar antiguidades porque ela disse que eu poderia fazer uma fortuna se tivesse sorte.",
  ui_story_5088_50880100_77_dialog_content = "Mas quando comecei a sentir alguns deles, tropecei em um antigo caderno deixado por um dos meus.",
  ui_story_5088_50880100_78_dialog_content = "Estou realmente interessado em aprender mais sobre isso... E mesmo que seja quase ilegível, quero continuar procurando coisas assim.",
  ui_story_5088_50880100_79_dialog_content = "Eu tenho que ajudá-los... Eu tenho que encontrar ainda mais memórias para meus amigos.",
  ui_story_5088_50880100_80_dialog_content = "Então você veio até a Senhora Sheol pedir ajuda?",
  ui_story_5088_50880100_81_dialog_content = "Sim, ele fez, mas tempo é dinheiro, então por favor continue procurando.",
  ui_story_5088_50880100_82_dialog_content = "Há tantas coisas espalhadas por aqui. Você tem certeza de que não está apenas dificultando as coisas para ele?",
  ui_story_5088_50880100_83_dialog_content = "Posso definitivamente sentir algo semelhante vindo de uma dessas antiguidades... Mas são apenas muitas delas.",
  ui_story_5088_50880100_84_dialog_content = "*Tosse* Meu, só olha toda essa poeira... Não é que eu não queira te ajudar, minha querida. Esses itens são simplesmente muito antigos, e rastrear suas origens é quase impossível.",
  ui_story_5088_50880100_85_dialog_content = "Se eu não os tivesse trazido para guardar em segurança, provavelmente alguém em Umbraton já os teria quebrado.",
  ui_story_5088_50880100_86_dialog_content = "Então novamente, não sou especialista nessas coisas. Ah, se apenas Vergil estivesse aqui para resolver isso.",
  ui_story_5088_50880100_87_dialog_content = "Aqui, deixe-me ajudar—Ai está.",
  ui_story_5088_50880100_88_dialog_content = "Uh... Você não está apenas pegando coisas aleatoriamente?",
  ui_story_5088_50880100_89_dialog_content = "Quando o trabalho duro não consegue concluir a tarefa, você precisa confiar na sua sorte e intuição.",
  ui_story_5088_50880100_90_dialog_content = "Confie em mim.",
  ui_story_5088_50880100_91_dialog_content = "É... É um...",
  ui_story_5088_50880100_92_dialog_content = "Hã? Nossa, deu certo mesmo.",
  ui_story_5088_50880100_93_dialog_content = "Não há como errar. Este é um Brasão de Estrela!",
  ui_story_5088_50880100_94_dialog_content = "É exatamente o que eu estava procurando!",
  ui_story_5088_50880100_95_dialog_content = "Bom de se ouvir.",
  ui_story_5088_50880100_96_dialog_content = "Já que parece ter muito valor para você, vou deixar que fique com ele sem nenhum custo.",
  ui_story_5088_50880100_97_dialog_content = "Eu não tenho utilidade para isso aqui, então considere isso um presente para meu cliente número um.",
  ui_story_5088_50880100_98_dialog_content = "Muito obrigado, Senhora Sheol!",
  ui_story_5088_50880100_99_dialog_content = "Eu tenho que ir agora. Vê você!",
  ui_story_5088_50880100_100_dialog_content = "Já está escuro lá fora. Deixe-me te acompanhar de volta.",
  ui_story_5088_50880100_101_dialog_content = "Ai—",
  ui_story_5088_50880100_102_dialog_content = "Ah! E-eu sinto muito, eu não quis dizer... Tweety?",
  ui_story_5088_50880100_103_dialog_content = "Ei! É você, Sr. Navegador!",
  ui_story_5088_50880100_104_dialog_content = "Desculpe por isso, eu estava com muita pressa agora.",
  ui_story_5088_50880100_105_dialog_content = "Você está bem, senhora?",
  ui_story_5088_50880100_106_dialog_content = "Ah bom, nenhuma das cartas desapareceu.",
  ui_story_5088_50880100_107_dialog_content = "\"Senhora\"?",
  ui_story_5088_50880100_108_dialog_content = "Deixe-me apresentar nosso mais novo Mensageiro! Ela é bastante talentosa, você sabe!",
  ui_story_5088_50880100_109_dialog_content = "Prazer em conhecer todos vocês. Meu nome é Mithra e fui designado para a Senhorita Tweety como seu assistente.",
  ui_story_5088_50880100_110_dialog_content = "Isso parece completamente errado... Você é muito mais alto que ela.",
  ui_story_5088_50880100_111_dialog_content = "Heehee...",
  ui_story_5088_50880100_112_dialog_content = "Desculpe a todos, mas eu realmente preciso ir! Vou me certificar de pedir desculpas a você adequadamente mais tarde, Tweety!",
  ui_story_5088_50880100_113_dialog_content = "Vejo você por aí, Sr. Navegador!",
  ui_story_5088_50880100_114_dialog_content = "Tem certeza de que não há mais nada?",
  ui_story_5088_50880100_115_dialog_content = "É tudo isso que você consegue se lembrar?",
  ui_story_5088_50880100_116_dialog_content = "Por um certo motivo, você passou a maior parte do seu tempo vivendo na cidade onde estava estacionado.",
  ui_story_5088_50880100_117_dialog_content = "Apenas esqueça isso. Lembrar dessas coisas não vai te fazer bem agora.",
  ui_story_5088_50880100_118_dialog_content = "Não me importo se dói. Eu tenho que recuperar minhas memórias.",
  ui_story_5088_50880100_119_dialog_content = "Ainda consigo me lembrar dela... Meu amor... Mas por algum motivo, não consigo me lembrar do rosto dela...",
  ui_story_5088_50880100_120_dialog_content = "Foi apenas por causa dela que jurei proteger os justos com minha lâmina.",
  ui_story_5088_50880100_121_dialog_content = "Então, por favor, pelo menos me diga o nome dela!",
  ui_story_5088_50880100_122_dialog_content = "Tchã-rããã! E então? Minha entrada graciosa te surpreendeu?",
  ui_story_5088_50880100_123_dialog_content = "Ei! Vocês caras começaram sem mim!",
  ui_story_5088_50880100_124_dialog_content = "É sua culpa por ser tão lento.",
  ui_story_5088_50880100_125_dialog_content = "Não perdi nada, perdi?",
  ui_story_5088_50880100_126_dialog_content = "...",
  ui_story_5088_50880100_127_dialog_content = "Desculpe, mas também não me lembro de nada.",
  ui_story_5088_50880100_128_dialog_content = "Entendo...",
  ui_story_5088_50880100_129_dialog_content = "E quanto aquele outro nome? \"Claymore\"?",
  ui_story_5088_50880100_130_dialog_content = "?!",
  ui_story_5088_50880100_131_dialog_content = "Como você ousa mencionar o nome dessa pessoa novamente!",
  ui_story_5088_50880100_132_dialog_content = "Ei, se acalme já!",
  ui_story_5088_50880100_133_dialog_content = "Solte-me—! Concordamos em nunca mais mencioná-lo!",
  ui_story_5088_50880100_134_dialog_content = "Você desmembrou aquela pessoa você mesmo naquele dia.",
  ui_story_5088_50880100_135_dialog_content = "É por isso que você nos reuniu aqui hoje? Para nos fazer lembrar da dor novamente?!",
  ui_story_5088_50880100_136_dialog_content = "Eu... Eu odiava aquela pessoa. De alguma forma eu apenas odiava, e eu não sei por quê...",
  ui_story_5088_50880100_137_dialog_content = "Mas quando PlayerName me mostrou, só me convenceu ainda mais... Aquela pessoa...",
  ui_story_5088_50880100_138_dialog_content = "Seu nome era Aquiles, e ele era nosso líder.",
  ui_story_5088_50880100_139_dialog_content = "Sim? E daí?",
  ui_story_5088_50880100_140_dialog_content = "Ele era o seu general e o líder do nosso grupo.",
  ui_story_5088_50880100_141_dialog_content = "Mas ele nos traiu.",
  ui_story_5088_50880100_142_dialog_content = "A verdade é, todos nós concordamos com isso - em nos deixar ser destruídos.",
  ui_story_5088_50880100_143_dialog_content = "Mas quando sua lâmina perfurou meu coração, eu senti... ressentimento.",
  ui_story_5088_50880100_144_dialog_content = "Fiquei tão aliviada por poder sentir algo afinal... Mas logo percebi... A dor não estava passando.",
  ui_story_5088_50880100_145_dialog_content = "O capitão já foi um grande herói e um bom amigo para todos nós. Acabar com o sofrimento dele é o mínimo que podemos fazer.",
  ui_story_5088_50880100_146_dialog_content = "Isso mesmo. Ele era um herói... E eu devia a ele minha vida.",
  ui_story_5088_50880100_147_dialog_content = "É por isso... Sentiu ainda mais ódio quando ele atacou de repente.",
  ui_story_5088_50880100_148_dialog_content = "Não deveria ser assim... Eu sei que não deveria odiá-lo...",
  ui_story_5088_50880100_149_dialog_content = "Talvez estejamos esquecendo de algo importante?",
  ui_story_5088_50880100_150_dialog_content = "Por exemplo... Realmente éramos apenas cinco naquela época?",
  ui_story_5088_50880100_151_dialog_content = "Eu quero lembrar de tudo.",
  ui_story_5088_50880100_152_dialog_content = "O que nos aconteceu no passado? E o que aconteceu quando finalmente despertamos?",
  ui_story_5088_50880100_153_dialog_content = "O que exatamente esquecemos? Vamos nos lembrar de tudo algum dia?",
  ui_story_5088_50880100_154_dialog_content = "<size=30>A pessoa que não conseguimos lembrar é a que registrou tudo sobre nós. Perdoe-nos... Nosso amigo há muito esquecido.</size>",
  ui_story_5088_50880100_155_dialog_content = "Posso sentir a presença de Aurorianos bem no fundo desta caverna congelada... Mas como? É por isso que a rainha me pediu para investigar?",
  ui_story_5088_50880100_156_dialog_content = "Apenas aguente! Vou tirar vocês de lá...",
  ui_story_5088_50880100_157_dialog_content = "Tudo está no lugar agora. O selo só será quebrado quando um Celestita decidir libertá-los deste lugar.",
  ui_story_5088_50880100_158_dialog_content = "Em troca, vai me prender aqui e drenar lentamente minha força. Mas mesmo que eu me torne um Eclipsite, continuarei a vigiá-los.",
  ui_story_5088_50880100_159_dialog_content = "Foi aquilo...?",
  ui_story_5088_50880100_160_dialog_content = "Capitão... Por que...",
  ui_story_5088_50880100_161_dialog_content = "Eu...?",
  ui_story_5088_50880100_162_dialog_content = "Huh? Ainda estou vivo?",
  ui_story_5088_50880100_163_dialog_content = "Ei... O que é aquela luz vindo lá de baixo? O selo já foi ativado?",
  ui_story_5088_50880100_164_dialog_content = "Essa formação... É o lugar de antes? A caverna onde aquele cara...",
  ui_story_5088_50880100_165_dialog_content = "Um... Um Celestita?",
  ui_story_5088_50880100_166_dialog_content = "Grah!!!",
  ui_story_5088_50880100_167_dialog_content = "Argh... Minha cabeça... O que está acontecendo? Por que de repente ouço tantas vozes?!",
  ui_story_5088_50880100_168_dialog_content = "Não—Vá embora! Deixe-me em paz!",
  ui_story_5088_50880100_169_dialog_content = "A-você está bem?",
  ui_story_5088_50880100_170_dialog_content = "Essa voz... ele ainda está vivo!",
  ui_story_5088_50880100_171_dialog_content = "Claymore... O defensor do reino vai nos destruir a todos!",
  ui_story_5088_50880100_172_dialog_content = "Ei! Agora não é hora de pensar nisso!",
  ui_story_5088_50880100_173_dialog_content = "Esse garoto nos salvou, mas parece que ele está realmente muito machucado.",
  ui_story_5088_50880100_174_dialog_content = "Salvar pessoas vem em primeiro lugar, como sempre. Vamos descobrir o resto depois.",
  ui_story_5088_50880100_175_dialog_content = "... Então vamos.",
  ui_story_5088_50880100_176_dialog_content = "Ele está vindo atrás de nós.",
  ui_story_5088_50880100_177_dialog_content = "Magia da floresta, esconda-nos dos olhos de nosso perseguidor—Vá!",
  ui_story_5088_50880100_178_dialog_content = "Th-Th-Não há escapatória!",
  ui_story_5088_50880100_179_dialog_content = "<size=45>Morte a todos os inimigos!!!</size>",
  ui_story_5088_50880100_180_dialog_content = "<color=#e8d9bb>Uma onda de poder bruto irrompe, rasgando através dos densos galhos mágicos.</color>",
  ui_story_5088_50880100_181_dialog_content = "Tá doendo...",
  ui_story_5088_50880100_182_dialog_content = "Um Celestita... Eu devo poupá-lo...",
  ui_story_5088_50880100_183_dialog_content = "<color=#e8d9bb>A energia da espada massiva fende o chão enquanto avança em direção ao grupo.</color>",
  ui_story_5088_50880100_184_dialog_content = "<color=#e8d9bb>Mas no último segundo, o Eclipsite desvia seu poder avassalador deles.</color>",
  ui_story_5088_50880100_185_dialog_content = "<color=#e8d9bb>Silenciosamente, ele observa enquanto sua presa escapa.</color>",
  ui_story_5088_50880100_186_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50880201_1_dialog_content = "(Este emblema é diferente dos que Adras e os outros carregam. Tem uma imagem única gravada nele.)",
  ui_story_5088_50880201_2_dialog_content = "Poderia ser de Claymore...?",
  ui_story_5088_50880201_3_dialog_content = "(Com certeza posso sentir o poder dele vindo disso.)",
  ui_story_5088_50880201_4_option_content = "Varredura Psíquica",
  ui_story_5088_50880201_5_dialog_content = "<color=#e8d9bb>Quinto dia: E o traidor disse: \"Os heróis devem morrer.\"</color>",
  ui_story_5088_50880201_6_dialog_content = "Sai do meu caminho!",
  ui_story_5088_50880201_7_dialog_content = "Ranger—Ranger—",
  ui_story_5088_50880201_8_dialog_content = "... Entendo.",
  ui_story_5088_50880201_9_dialog_content = "Eles são Eclipsitas agora...",
  ui_story_5088_50880201_10_dialog_content = "Eles eram soldados bravos e leais, mas você os transformou em monstros.",
  ui_story_5088_50880201_11_dialog_content = "E agora, apenas outro monstro como eu pode acabar com o sofrimento deles.",
  ui_story_5088_50880201_12_dialog_content = "Não havia outra escolha.",
  ui_story_5088_50880201_13_dialog_content = "Ainda pode se chamar de \"rei\" agora?",
  ui_story_5088_50880201_14_dialog_content = "Ou uma pessoa, nesse caso?",
  ui_story_5088_50880201_15_dialog_content = "<size=45>Gaius Agamemnon!!!</size>",
  ui_story_5088_50880201_16_dialog_content = "Desça do seu trono podre e me enfrente!",
  ui_story_5088_50880202_1_dialog_content = "O que... O que no mundo...",
  ui_story_5088_50880202_2_dialog_content = "Senhor Aquiles... Não me diga que você também perdeu a cabeça?",
  ui_story_5088_50880202_3_dialog_content = "...",
  ui_story_5088_50880202_4_dialog_content = "Além de nós está o rei. Não podemos permitir que você passe.",
  ui_story_5088_50880202_5_dialog_content = "Se algum de vocês ainda me vê como Aquiles, então, por favor, afaste-se.",
  ui_story_5088_50880202_6_dialog_content = "Tenho algo a dizer para aquele cara.",
  ui_story_5088_50880202_7_dialog_content = "Mas...",
  ui_story_5088_50880202_8_dialog_content = "Deixe-o passar.",
  ui_story_5088_50880202_9_dialog_content = "Você não poderia detê-lo mesmo que tentasse. Não há necessidade de se sacrificar tão inutilmente.",
  ui_story_5088_50880202_10_dialog_content = "Muito bem, Vossa Majestade!",
  ui_story_5088_50880202_11_dialog_content = "Por aqui, Senhor Aquiles...",
  ui_story_5088_50880202_12_dialog_content = "... Nenhum dos meus camaradas jamais perdeu a razão. Lembre-se disso.",
  ui_story_5088_50880202_13_dialog_content = "Você sofreu tanto apenas para sobreviver até agora, Aquiles. Por que não deixar as coisas terminarem como deveriam?",
  ui_story_5088_50880202_14_dialog_content = "Meus camaradas e eu... não nos importamos em nos tornar mártires.",
  ui_story_5088_50880202_15_dialog_content = "Mas eu sei que eles merecem um final muito melhor, e estou disposto a dar minha vida para dar isso a eles.",
  ui_story_5088_50880202_16_dialog_content = "Mas desde o momento em que seus guardas sacaram suas espadas contra mim... Eu percebi que você nunca teve a intenção de nos deixar viver.",
  ui_story_5088_50880202_17_dialog_content = "Minha lealdade a você termina hoje.",
  ui_story_5088_50880202_18_dialog_content = "O que te faz dizer isso? Será que é... por causa do Celestita Morto que você está carregando nas costas?",
  ui_story_5088_50880202_19_dialog_content = "Bem, você pode ficar com ela. Além disso, eu sabia que este dia eventualmente chegaria.",
  ui_story_5088_50880202_20_dialog_content = "Você e seus camaradas não me devem nada. Se alguma coisa, eu sou devedor a você.",
  ui_story_5088_50880202_21_dialog_content = "Mas todos nós sabemos muito bem que eu estava certo em fazer as coisas que fiz.",
  ui_story_5088_50880202_22_dialog_content = "Busco a sua erradicação não por desejo pessoal, mas pelo bem da paz duramente conquistada que nosso reino agora desfruta.",
  ui_story_5088_50880202_23_dialog_content = "Você... Como pode dizer isso?!",
  ui_story_5088_50880202_24_dialog_content = "Sacrifiquei tudo o que era caro para mim, e nosso reino agora está em paz por causa disso.",
  ui_story_5088_50880202_25_dialog_content = "Sempre lembrarei de cada gota de sangue que você e seus camaradas derramaram por nossa nação.",
  ui_story_5088_50880202_26_dialog_content = "O Conselho Ancião foi forçado à rebelião, e as chamas da guerra ainda queimam por todo o reino! Isso é o que você chama de \"paz\"?!",
  ui_story_5088_50880202_27_dialog_content = "As chamas estão sob o meu controle. Eu sei exatamente o que elas devem queimar.",
  ui_story_5088_50880202_28_dialog_content = "...!",
  ui_story_5088_50880202_29_dialog_content = "Quem era seu espião dentro do Conselho Ancião?",
  ui_story_5088_50880202_30_dialog_content = "E quem você enviou para destruí-los?",
  ui_story_5088_50880202_31_dialog_content = "Por que fui deixado no escuro todo esse tempo?!",
  ui_story_5088_50880202_32_dialog_content = "Aquiles, quando você jurou defender a justiça a todo custo...",
  ui_story_5088_50880202_33_dialog_content = "Eu sabia que tinha que me distanciar de você.",
  ui_story_5088_50880202_34_dialog_content = "Mas ainda há tantas pessoas no Conselho dos Anciões que são leais ao reino... Como você poderia...",
  ui_story_5088_50880202_35_dialog_content = "Pense, Aquiles.",
  ui_story_5088_50880202_36_dialog_content = "O norte era uma vez um lugar caótico e atingido pela guerra, mas você e eu estabelecemos as bases para a paz.",
  ui_story_5088_50880202_37_dialog_content = "Ninguém no Conselho dos Anciões preza pela paz, é por isso que eles escolheram semear a animosidade entre nós.",
  ui_story_5088_50880202_38_dialog_content = "Quando minha família caiu em suspeita, aquele tirano os exilou para as regiões mais frias da terra e os deixou para morrer.",
  ui_story_5088_50880202_39_dialog_content = "O Conselho dos Anciões testemunhou a destruição da minha família e não fez nada para me ajudar quando fui feito prisioneiro.",
  ui_story_5088_50880202_40_dialog_content = "Eu aceitei tudo o que aconteceu comigo.",
  ui_story_5088_50880202_41_dialog_content = "Então você decidiu exterminar toda a família do ex-rei.",
  ui_story_5088_50880202_42_dialog_content = "Na época... Eu estava atrasado demais para te impedir.",
  ui_story_5088_50880202_43_dialog_content = "Mas mesmo assim, eu não percebi que o seu ódio se estendia também ao Conselho dos Anciões...",
  ui_story_5088_50880202_44_dialog_content = "Você está errado. Eu abandonei meu rancor há muito tempo, é por isso que conseguimos unir os estados beligerantes de Northland em uma verdadeira nação.",
  ui_story_5088_50880202_45_dialog_content = "O que o Conselho Ancião fez para merecer seu destino?",
  ui_story_5088_50880202_46_dialog_content = "Eles me temem, Aquiles. Eles desejam parar minha revolução, virando nosso povo contra mim, incluindo os sacerdotes.",
  ui_story_5088_50880202_47_dialog_content = "Eles também te prejudicaram para ganhar seu favor e sua força militar, não foi?",
  ui_story_5088_50880202_48_dialog_content = "Isso não é da minha preocupação.",
  ui_story_5088_50880202_49_dialog_content = "Houve um tempo em que acreditei que qualquer um de nós poderia ser rei. Mas você sempre foi muito íntegro para o trono.",
  ui_story_5088_50880202_50_dialog_content = "Alguém como você nunca poderia purgar a corrupção do nosso reino e trazer paz ao seu povo.",
  ui_story_5088_50880202_51_dialog_content = "Se ao menos você tivesse nascido em uma era de paz. Tão poderoso e imparcial quanto você é, poderia ter sido o maior marechal da história do nosso reino.",
  ui_story_5088_50880202_52_dialog_content = "Mas agora, não há nada que você possa fazer para me ajudar. Você mal é o marechal que Northland precisa neste momento.",
  ui_story_5088_50880202_53_dialog_content = "É por isso que você nunca pode ser mais do que um general... Ou um monstro no comando de outros monstros.",
  ui_story_5088_50880202_54_dialog_content = "Chega do seu falatório sem sentido, Agamemnon! Liberte meus camaradas e pare com todo esse assassinato sem sentido.",
  ui_story_5088_50880202_55_dialog_content = "E se eu recusar?",
  ui_story_5088_50880202_56_dialog_content = "A fonte da ameaça Eclipsita foi erradicada, o Conselho dos Anciãos está à beira do colapso e o templo perdeu seu Sumo Sacerdote.",
  ui_story_5088_50880202_57_dialog_content = "Como o indiscutível vencedor, por que você insiste em continuar sua série de assassinatos?",
  ui_story_5088_50880202_58_dialog_content = "Agora que você eliminou dois dos três corpos governantes do nosso reino, você poderia se tornar imperador de toda Northland.",
  ui_story_5088_50880202_59_dialog_content = "Você e seus compatriotas são poderosos demais para serem deixados vivos. Suas próprias existências representam um grande risco para a paz que tanto desejo.",
  ui_story_5088_50880202_60_dialog_content = "E o fato permanece que vocês são todos impotentes para suprimir a corrupção em seus corpos.",
  ui_story_5088_50880202_61_dialog_content = "No mínimo... Você deve poupar as crianças e deixar meus camaradas deixarem o reino... Para que eles possam levar nossa querida amiga de volta à sua distante terra natal e a colocar para descansar.",
  ui_story_5088_50880202_62_dialog_content = "Vou ficar aqui e pagar qualquer preço que você me pedir.",
  ui_story_5088_50880202_63_dialog_content = "Nunca pensei que você falaria em nome do Conselho Ancião no final. Você está fazendo isso por justiça? Ou talvez por lealdade ao seu próprio povo?",
  ui_story_5088_50880202_64_dialog_content = "Estou fazendo isso como uma pessoa, Agamemnon.",
  ui_story_5088_50880202_65_dialog_content = "... Os outros Guerreiros Estelares caíram na loucura. Você, Aquiles, é o único cuja vontade não vacilou.",
  ui_story_5088_50880202_66_dialog_content = "Não é de se admirar que aquela Celestita tola tenha dado a vida dela para—",
  ui_story_5088_50880202_67_dialog_content = "<color=#e8d9bb>A pressão de um poderoso corte o interrompe no meio da frase.</color>",
  ui_story_5088_50880202_68_dialog_content = "Nem mais uma palavra!",
  ui_story_5088_50880202_69_dialog_content = "Não vou deixar você insultar meu amigo por mais tempo!",
  ui_story_5088_50880202_70_dialog_content = "... \"Amigo,\" você diz?",
  ui_story_5088_50880202_71_dialog_content = "Eu também não era seu amigo, Aquiles?",
  ui_story_5088_50880202_72_dialog_content = "Durante nossos dias militares, você era meu aliado mais confiável, tão confiável quanto meu próprio braço armado. Ainda me lembro das inúmeras vezes que você salvou minha vida.",
  ui_story_5088_50880202_73_dialog_content = "Mas o momento mais memorável... foi quando eu deixei meu escudo cair na batalha, e você me protegeu com seu corpo. Eu me lembro de todas as dezessete lesões que você sofreu naquele dia.",
  ui_story_5088_50880202_74_dialog_content = "... E por minha causa, você quebrou as fileiras e derrubou os lanceiros que estavam se aproximando de mim, tudo isso sem o seu escudo.",
  ui_story_5088_50880202_75_dialog_content = "Seus ferimentos eram tão graves quanto os meus, e você foi acorrentado por violar ordens. Sua própria irmã faleceu na prisão por causa disso também.",
  ui_story_5088_50880202_76_dialog_content = "Aliados...",
  ui_story_5088_50880202_77_dialog_content = "Eu sei que você nunca poderia me matar, Aquiles, porque não existe uma pessoa melhor viva que poderia ocupar meu lugar.",
  ui_story_5088_50880202_78_dialog_content = "Nenhum de nós quer mergulhar nosso reino no caos mais uma vez.",
  ui_story_5088_50880202_79_dialog_content = "...",
  ui_story_5088_50880202_80_dialog_content = "Agora saia.",
  ui_story_5088_50880202_81_dialog_content = "?!",
  ui_story_5088_50880202_82_dialog_content = "Não faz diferença se eu deixar um de vocês ou todos vocês irem.",
  ui_story_5088_50880202_83_dialog_content = "Leve todos com você. Seus companheiros de equipe, os guerreiros que juram lealdade a você, as crianças do Conselho Ancião e seu amigo Celestita...",
  ui_story_5088_50880202_84_dialog_content = "Leve-os para algum lugar distante e nunca mais pise em nossas terras puras e intocadas novamente.",
  ui_story_5088_50880202_85_dialog_content = "Vou remover qualquer menção a você e seus camaradas dos anais da nossa história. Ninguém cantará seus louvores ou buscará o poder que você possui nunca mais.",
  ui_story_5088_50880202_86_dialog_content = "Garantirei que a arte de criar soldados Eclipsitas seja perdida com o passar do tempo.",
  ui_story_5088_50880202_87_dialog_content = "Olhe nos meus olhos, Gaius Agamemnon, e me diga que você está fazendo isso não por ganho pessoal, mas em nome de nossos ideais.",
  ui_story_5088_50880202_88_dialog_content = "Sim. Mesmo enquanto desço para um rio de pecado imperdoável... Eu sempre ansiarei pela paz. Isso será especialmente verdadeiro uma vez que eu assuma o trono e olhe para o caos como rei.",
  ui_story_5088_50880202_89_dialog_content = "E assim, vou suportar a sujeira que você nunca poderia aceitar. Enquanto Northland não for assolada nem pela guerra nem por aqueles que a procuram, eu juro solenemente—",
  ui_story_5088_50880202_90_dialog_content = "Nenhum garoto terá que mendigar por pão para sobreviver. Nenhuma santinha terá que se queimar novamente. Nenhuma criança jamais se perderá na floresta...",
  ui_story_5088_50880202_91_dialog_content = "Nenhuma garota será temida por causa de suas chamas. Nenhuma criança nascerá e será deixada em um orfanato. Ninguém terá que passar a vida inteira em lágrimas...",
  ui_story_5088_50880202_92_dialog_content = "E nenhum indivíduo íntegro terá que sentir a dor da traição nunca mais.",
  ui_story_5088_50880202_93_dialog_content = "Devorarei todos os vestígios de sujeira até que todo Northland seja tão puro e impecável quanto a neve que o cobre.",
  ui_story_5088_50880202_94_dialog_content = "Por isso, pagarei qualquer preço.",
  ui_story_5088_50880202_95_dialog_content = "Me diga, como se sente ao sentar sozinho no topo de um trono podre?",
  ui_story_5088_50880202_96_dialog_content = "...",
  ui_story_5088_50880202_97_dialog_content = "...",
  ui_story_5088_50880202_98_dialog_content = "Adeus, Gaius Agamemnon.",
  ui_story_5088_50880202_99_dialog_content = "Adeus, meu amigo.",
  ui_story_5088_50880202_100_dialog_content = "May todos vocês encontrem a paz um dia.",
  ui_story_5088_50880202_101_dialog_content = "... Está frio.",
  ui_story_5088_50880202_102_dialog_content = "Este trono é mais frio do que você jamais poderia imaginar, meu amigo.",
  ui_story_5088_50880202_103_dialog_content = "<color=#e8d9bb>Sexto dia: Os caçadores—Um conto perdido no tempo.</color>",
  ui_story_5088_50880202_104_dialog_content = "Muitas vezes, a verdade é enterrada nas areias do tempo.",
  ui_story_5088_50880202_105_dialog_content = "O que mais posso fazer? Mesmo que eu grave tudo... alguém saberá a verdade?",
  ui_story_5088_50880202_106_dialog_content = "Eu fracassei. Não há nada que eu possa fazer para salvá-lo.",
  ui_story_5088_50880202_107_dialog_content = "Mas também fui bem-sucedido. Ninguém no reino mencionará seus nomes novamente.",
  ui_story_5088_50880202_108_dialog_content = "Você será esquecido. Independentemente de conquista ou desgraça, você será esquecido.",
  ui_story_5088_50880202_109_dialog_content = "Vocês são todos estrelas se apagando. Quando sua luz apagar, ninguém se lembrará de vocês.",
  ui_story_5088_50880202_110_dialog_content = "E ainda assim você continua escrevendo no seu diário, Senhor Aquiles.",
  ui_story_5088_50880202_111_dialog_content = "Mesmo que destruamos todos os registros de sua existência, você nunca poderá esquecê-los.",
  ui_story_5088_50880202_112_dialog_content = "É porque Freya uma vez disse que ela não queria que fôssemos esquecidos.",
  ui_story_5088_50880202_113_dialog_content = "O resto do mundo pode esquecer de nós, já que essa calamidade nunca mais aparecerá neste mundo.",
  ui_story_5088_50880202_114_dialog_content = "Mas eu não posso... Eu não posso esquecer deles...",
  ui_story_5088_50880202_115_dialog_content = "As palavras que estou escrevendo são apenas para mim.",
  ui_story_5088_50880202_116_dialog_content = "... E você tem certeza de que este selo é resistente o suficiente para resistir ao teste do tempo?",
  ui_story_5088_50880202_117_dialog_content = "Tudo está no lugar agora. O selo só será quebrado quando um Celestita decidir libertá-los deste lugar.",
  ui_story_5088_50880202_118_dialog_content = "As estrelas estão em paz agora, e as crianças foram escoltadas com segurança para fora de Northland pelos outros...",
  ui_story_5088_50880202_119_dialog_content = "Há apenas uma última coisa que posso fazer por você, Senhor Aquiles, e agora é a hora de fazê-lo.",
  ui_story_5088_50880202_120_dialog_content = "O que seria?",
  ui_story_5088_50880202_121_dialog_content = "Eu sou o único mortal neste mundo que sabe sobre este lugar, e tenho que garantir que sua existência permaneça um segredo para sempre.",
  ui_story_5088_50880202_122_dialog_content = "Devo-lhe minha vida, meu senhor, e agora é hora de retribuir com ela!",
  ui_story_5088_50880202_123_dialog_content = "Lord Aquiles? Por que você me parou?",
  ui_story_5088_50880202_124_dialog_content = "Já chega, Anthony. Você já me deu sua lealdade e amizade. Não há necessidade de me dar sua vida.",
  ui_story_5088_50880202_125_dialog_content = "Mas...",
  ui_story_5088_50880202_126_dialog_content = "Esta formação serve a dois propósitos: manter o selo em meus camaradas e evitar que eu os machuque uma vez que eu perca minha sanidade.",
  ui_story_5088_50880202_127_dialog_content = "Em troca, vai me prender aqui e drenar lentamente minha força. Mas mesmo que eu me torne um Eclipsite, continuarei a vigiá-los.",
  ui_story_5088_50880202_128_dialog_content = "Não tenho como sair deste lugar, Anthony.",
  ui_story_5088_50880202_129_dialog_content = "Então, por favor, encontre Eraveil em meu lugar e me ajude a colocar Ludweiss para descansar em sua terra natal.",
  ui_story_5088_50880202_130_dialog_content = "Essa foi a promessa que fiz a ela.",
  ui_story_5088_50880202_131_dialog_content = "Ludweiss uma vez me disse que Eraveil ainda não estava aberta para o mundo exterior. Pode levar anos para você encontrá-la.",
  ui_story_5088_50880202_132_dialog_content = "Mas até então, você não tem permissão para morrer.",
  ui_story_5088_50880202_133_dialog_content = "Senhor Aquiles... Você sabia que eu tentaria tirar minha própria vida para manter este lugar em segredo, não sabia?",
  ui_story_5088_50880202_134_dialog_content = "...",
  ui_story_5088_50880202_135_dialog_content = "Então você decidiu usar isso como uma desculpa para me impedir de fazer isso.",
  ui_story_5088_50880202_136_dialog_content = "Você deu cada grama de bondade em seu corpo para todos, menos para si mesmo. Não é justo, meu senhor.",
  ui_story_5088_50880202_137_dialog_content = "Mas se essa é a sua vontade... Então, eu, Anthony Longinus, por meio deste juro a você:",
  ui_story_5088_50880202_138_dialog_content = "A família Longinus procurará por Eraveil, bem como os meios para salvar você e seus camaradas. Mesmo que nossa busca se estenda por gerações, não pararemos até obtermos sucesso.",
  ui_story_5088_50880202_139_dialog_content = "Anthony...",
  ui_story_5088_50880202_140_dialog_content = "A partir deste dia, meus descendentes e eu guardaremos seu segredo.",
  ui_story_5088_50880202_141_dialog_content = "E se eu não puder estar com você no fim de sua vigília eterna, Senhor Aquiles...",
  ui_story_5088_50880202_142_dialog_content = "A família Longinus ficará ao seu lado ao longo dos séculos.",
  ui_story_5088_50880202_143_dialog_content = "Não há necessidade disso.",
  ui_story_5088_50880202_144_dialog_content = "O mundo pode esquecer das estrelas, mas sempre persistiremos em nossa missão de salvá-lo. Se tivermos que fazer isso em total obscuridade, que assim seja.",
  ui_story_5088_50880202_145_dialog_content = "Você e os outros merecem isso.",
  ui_story_5088_50880202_146_dialog_content = "...",
  ui_story_5088_50880202_147_dialog_content = "<color=#e8d9bb>Pouco depois de Anthony partir, Claymore usa um conjunto simples de ferramentas para esculpir uma série de novos emblemas.</color>",
  ui_story_5088_50880202_148_dialog_content = "<color=#e8d9bb>Depois de cuidadosamente esculpir a imagem de um pergaminho em um deles, ele cuidadosamente o coloca dentro de seu caderno.</color>",
  ui_story_5088_50880202_149_dialog_content = "Ludweiss, vamos esperar juntos pelo derretimento da neve e pela chegada da primavera.",
  ui_story_5088_50880301_1_dialog_content = "Então este emblema foi feito para a Srta. Ludweiss...",
  ui_story_5088_50880301_2_dialog_content = "E assim como no sonho de Adras, Claymore, ou melhor, Aquiles, costumava ser uma pessoa bondosa e íntegra.",
  ui_story_5088_50880301_3_dialog_content = "Mas o Claymore que acabamos de ver era um ser tão violento. O que poderia ter acontecido entre aquela época e agora?",
  ui_story_5088_50880301_4_dialog_content = "(Não só isso... Adras e seus camaradas foram os que mataram seu capitão com suas próprias mãos.)",
  ui_story_5088_50880301_5_dialog_content = "Você está bem?",
  ui_story_5088_50880301_6_dialog_content = "Desde aquele dia, você tem um olhar tão preocupado no rosto.",
  ui_story_5088_50880301_7_dialog_content = "Algo sobre o meu sonho está te incomodando?",
  ui_story_5088_50880301_8_dialog_content = "Se for, é sempre uma boa ideia contar para as outras pessoas. Não guarde tudo para você, okay?",
  ui_story_5088_50880301_9_dialog_content = "Vocês ainda se lembram quando voltamos àquela caverna congelada?",
  ui_story_5088_50880301_10_dialog_content = "Todos vocês eram tão familiarizados com aquele lugar...",
  ui_story_5088_50880301_11_dialog_content = "Isso é porque fomos lá em uma missão há muito, muito tempo atrás.",
  ui_story_5088_50880301_12_dialog_content = "Não conseguimos nos lembrar de detalhes específicos, embora. Pode ser um efeito colateral de estar selado por tanto tempo...",
  ui_story_5088_50880301_13_dialog_content = "Mas o que eu me lembro é que havia algo claramente errado com aquele cara durante nossa missão...",
  ui_story_5088_50880301_14_dialog_content = "Ah... Não adianta, não consigo me lembrar de mais nada... Mas muitos anos depois, foi onde você nos encontrou...",
  ui_story_5088_50880301_15_dialog_content = "Isso prova que ele nos traiu.",
  ui_story_5088_50880301_16_dialog_content = "Mas quando acordamos, o lugar era totalmente diferente de quando entramos pela primeira vez.",
  ui_story_5088_50880301_17_dialog_content = "Acho que dois mil anos realmente podem mudar um lugar, certo?",
  ui_story_5088_50880301_18_dialog_content = "Eu... Eu só fui para aquela caverna sob a orientação de Queen Bethlehem.",
  ui_story_5088_50880301_19_dialog_content = "Há um tempo atrás, eu resgatei um Auroriano que havia sido congelado no gelo. Desde o início, eu pensei...",
  ui_story_5088_50880301_20_dialog_content = "Bethlehem...?",
  ui_story_5088_50880301_21_dialog_content = "...Hã?",
  ui_story_5088_50880301_22_dialog_content = "(Estou totalmente sem pistas. O que devo fazer agora?)",
  ui_story_5088_50880301_23_dialog_content = "(Se eu combinar tudo o que vi agora com o que vi no sonho, prova que Claymore foi quem selou todos na arena antes de levá-los para a caverna congelada.)",
  ui_story_5088_50880301_24_dialog_content = "(Mas quando finalmente acordaram, suas memórias estavam em total desordem, e acabaram matando Claymore sem sequer perceber...)",
  ui_story_5088_50880301_25_dialog_content = "(Se isso for realmente a verdade... É quase insuportável de suportar...)",
  ui_story_5088_50880301_26_dialog_content = "Desculpe, mas há um lugar que eu quero ir.",
  ui_story_5088_50880301_27_dialog_content = "Eu já não te disse vezes suficientes, minha querida? É impossível para mim conhecer a história completa de cada um desses objetos.",
  ui_story_5088_50880301_28_dialog_content = "Sem mencionar que muitas dessas coisas são ganhos ilícitos dos primeiros dias do Istvan sênior.",
  ui_story_5088_50880301_29_dialog_content = "Naquela época, Umbraton era um antro de crime e caos. Quase tudo na cidade vinha de origens duvidosas, na melhor das hipóteses.",
  ui_story_5088_50880301_30_dialog_content = "Eu era o único disposto a salvaguardar esses objetos, também.",
  ui_story_5088_50880301_31_dialog_content = "Mas isso é realmente importante para mim...",
  ui_story_5088_50880301_32_dialog_content = "Oh, não faça essa cara, meu querido! Parte meu coração te ver tão abatido! Ah, se ao menos Vergil estivesse aqui para resolver as coisas.",
  ui_story_5088_50880301_33_dialog_content = "Que tal agora?",
  ui_story_5088_50880301_34_dialog_content = "Está ficando tarde, então por que eu não vendo todos os pergaminhos e anotações manuscritas aqui de uma vez só?",
  ui_story_5088_50880301_35_dialog_content = "Dessa forma, você pode levar tudo para casa e pesquisar no seu próprio ritmo. Eu até vou incluir um desconto familiar, apenas para você! Então, o que você me diz?",
  ui_story_5088_50880301_36_dialog_content = "T-Tá então...",
  ui_story_5088_50880301_37_dialog_content = "Ei, Caelestite... Tem certeza de que quer andar por Umbraton sozinho tão tarde da noite?",
  ui_story_5088_50880301_38_dialog_content = "Ei, viu isso? O Caelestite acabou de comprar um monte de coisas da Guilda Cloudrover.",
  ui_story_5088_50880301_39_dialog_content = "Não sei. Roubar o último Celestita pode ter consequências bastante sérias. Você tem alguma ideia de quão assustadores os Lovegators podem ser?",
  ui_story_5088_50880301_40_dialog_content = "Vamos lá, é o meio da noite! Só temos que dar uma surra nele e fugir com as mercadorias antes que alguém perceba!",
  ui_story_5088_50880301_41_dialog_content = "Poderíamos fugir da cidade e ir para algum lugar distante, um lugar onde até o Senhor das Sombras não pudesse nos encontrar.",
  ui_story_5088_50880301_42_dialog_content = "Basta olhar o tamanho desse caso! Uma vez que façamos nossa fuga, podemos viver como reis pelo resto de nossas vidas!",
  ui_story_5088_50880301_43_dialog_content = "... Tudo bem, mas vamos esperar até que ele se afaste um pouco mais de Umbraton. É quando faremos nossa jogada.",
  ui_story_5088_50880301_44_dialog_content = "Quem tá aí?!",
  ui_story_5088_50880301_45_dialog_content = "Oh? Acho que é verdade que os Celestitas podem nos sentir.",
  ui_story_5088_50880301_46_dialog_content = "Se for esse o caso, teremos que fazer nossa jogada agora!",
  ui_story_5088_50880301_47_dialog_content = "E-Espere um minuto! Você não quer nada disso! São apenas um monte de escritos e pergaminhos antigos!",
  ui_story_5088_50880301_48_dialog_content = "Ouviu isso? Parece um tesouro histórico para mim!",
  ui_story_5088_50880301_49_dialog_content = "(Eles não estão me ouvindo de jeito nenhum!)",
  ui_story_5088_50880301_50_dialog_content = "Vá em frente, idiotas.",
  ui_story_5088_50880301_51_dialog_content = "Hã?",
  ui_story_5088_50880301_52_dialog_content = "É-É ela! A Caçadora do Corvo!",
  ui_story_5088_50880301_53_dialog_content = "O que ela está fazendo aqui?!",
  ui_story_5088_50880301_54_dialog_content = "Tudo bem, seus sem-vergonhas... Hora de enfrentar seu castigo!",
  ui_story_5088_50880302_1_dialog_content = "Uh... Obrigado.",
  ui_story_5088_50880302_2_dialog_content = "Seu idiota!",
  ui_story_5088_50880302_3_dialog_content = "Hã?",
  ui_story_5088_50880302_4_dialog_content = "Você sabe muito bem que é um Celestita, então por que insiste em andar por aí completamente desprotegido?",
  ui_story_5088_50880302_5_dialog_content = "Mesmo que você esteja em bons termos com o Shadowlord e sua gangue, isso não é desculpa para subestimar os perigos de Umbraton.",
  ui_story_5088_50880302_6_dialog_content = "Não me deixe pegar você andando por essas ruas sozinho nunca mais.",
  ui_story_5088_50880302_7_dialog_content = "Inacreditável. Você realmente se deixou ser assaltado.",
  ui_story_5088_50880302_8_dialog_content = "Todo Umbraton está agitado agora por causa de você.",
  ui_story_5088_50880302_9_dialog_content = "Quando vi que você estava perfeitamente bem, pensei que houvesse algum erro.",
  ui_story_5088_50880302_10_dialog_content = "Hã?",
  ui_story_5088_50880302_11_dialog_content = "O Senhor das Sombras e seu povo ficaram furiosos quando descobriram, então eles caçaram os caras que tentaram te roubar.",
  ui_story_5088_50880302_12_dialog_content = "Mas já que você está bem, suponho que foi uma boa oportunidade para tirar um pouco mais do lixo daqui.",
  ui_story_5088_50880302_13_dialog_content = "Aqui, um sinal de simpatia da Senhora Sheol. Ela insistiu muito para que eu lhe desse isso.",
  ui_story_5088_50880302_14_dialog_content = "Obrigado... Mas realmente, estou bem. Alguém veio ao meu resgate bem na hora.",
  ui_story_5088_50880302_15_dialog_content = "Ouvi dizer. Os canalhas que te assaltaram nos disseram que o Caçador Raven foi quem te salvou.",
  ui_story_5088_50880302_16_dialog_content = "Sim, é assim que eles também a chamavam... A Caçadora Corvo...",
  ui_story_5088_50880302_17_dialog_content = "Ela começou a aparecer há cerca de dois anos. De vez em quando, ela caça criminosos no meio da noite e os pune.",
  ui_story_5088_50880302_18_dialog_content = "Um vigilante de Umbraton que só aparece à noite? Parece muito com Pittman de antigamente.",
  ui_story_5088_50880302_19_dialog_content = "Cuidado com o que você diz. Os métodos dessa pessoa são muito mais brutais.",
  ui_story_5088_50880302_20_dialog_content = "Nós dois somos corvos, mas uma coisa que não temos em comum é que ela não deixa pontas soltas.",
  ui_story_5088_50880302_21_dialog_content = "Independentemente de seus crimes, ela os espanca até ficarem a um passo da morte.",
  ui_story_5088_50880302_22_dialog_content = "Muitas pessoas suspeitam que ela possa ser uma Justice Knight renegada ou algo assim.",
  ui_story_5088_50880302_23_dialog_content = "Pacote para você, Sr. Navegador! Por favor, assine aqui.",
  ui_story_5088_50880302_24_dialog_content = "Obrigado.",
  ui_story_5088_50880302_25_dialog_content = "Você comprou ainda mais dessas coisas?",
  ui_story_5088_50880302_26_dialog_content = "Você não está apenas tentando encontrar uma agulha no palheiro neste momento?",
  ui_story_5088_50880302_27_dialog_content = "Eu sei... Mas isso é tudo que posso fazer agora... Além disso, vasculhar a história em busca de conhecimento perdido sempre será um desafio.",
  ui_story_5088_50880302_28_dialog_content = "...",
  ui_story_5088_50880302_29_dialog_content = "(Hã?)",
  ui_story_5088_50880302_30_dialog_content = "Então Tweety, você também tem entregas para fazer aqui?",
  ui_story_5088_50880302_31_dialog_content = "Tão má memória, Sr. Navegador. É quase Windelion, você sabe!",
  ui_story_5088_50880302_32_dialog_content = "Eu vim para confirmar a correspondência de Eraveil!",
  ui_story_5088_50880302_33_dialog_content = "É verdade! Eu esqueci completamente disso!",
  ui_story_5088_50880302_34_dialog_content = "Vice e Carleen devem voltar antes de Windelion. Tenho certeza de que Vice ficará mais do que feliz em...",
  ui_story_5088_50880302_35_dialog_content = "Agora que entreguei o presente da Senhora Sheol e confirmei sua segurança, estou me retirando.",
  ui_story_5088_50880302_36_dialog_content = "Também devemos ir! Vejo você por aí, Sr. Navegador!",
  ui_story_5088_50880302_37_dialog_content = "... Tchau.",
  ui_story_5088_50880302_38_dialog_content = "Tudo bem, vejo todos vocês mais tarde!",
  ui_story_5088_50880302_39_dialog_content = "Espere, Casta—",
  ui_story_5088_50880302_40_dialog_content = "Não sei se consigo lidar com a leitura de cada uma dessas anotações.",
  ui_story_5088_50880302_41_dialog_content = "Acha que pode usar sua incrível sorte para me dizer por onde começar?",
  ui_story_5088_50880302_42_dialog_content = "Quando o trabalho duro não pode te salvar e você não tem mais para onde ir, é nesse momento que você deve bater palmas e rezar pela sorte.",
  ui_story_5088_50880302_43_dialog_content = "Mas você não pode contar com a sorte quando o trabalho duro ainda é uma opção.",
  ui_story_5088_50880302_44_dialog_content = "Então, eu poderia adicioná-lo à minha lista de serviços prestados... Aqui, comece com este.",
  ui_story_5088_50880302_45_dialog_content = "Hã?",
  ui_story_5088_50880302_46_dialog_content = "Parece que sua técnica secreta falhou desta vez. Não sinto nada vindo deste notebook.",
  ui_story_5088_50880302_47_dialog_content = "Eu confio em muito mais do que apenas minha sorte, sabe.",
  ui_story_5088_50880302_48_dialog_content = "Por que você não tenta acreditar um pouco mais em si mesmo?",
  ui_story_5088_50880302_49_dialog_content = "Suponho que você esteja certo... Desculpe, Casta, eu não deveria ter tentado tirar vantagem da sua boa sorte assim.",
  ui_story_5088_50880302_50_dialog_content = "A-ahn?!",
  ui_story_5088_50880302_51_dialog_content = "Olhe a capa deste caderno... É uma Boneca Windelion!",
  ui_story_5088_50880302_52_dialog_content = "Deve... Deve ter pertencido a um Celestita!",
  ui_story_5088_50880302_53_dialog_content = "(É fraco, mas este caderno está emitindo uma onda tão familiar quanto aqueles emblemas. Este pode ser o caderno da Senhorita Ludweiss...)",
  ui_story_5088_50880302_54_dialog_content = "Parece que você está no caminho certo novamente. Te vejo.",
  ui_story_5088_50880302_55_dialog_content = "(Mas a senhorita Ludweiss nunca retornou a Eraveil em sua vida. Talvez houvesse outros Caelestites viajantes como ela que sabiam como fazer Bonecas Windelion?)",
  ui_story_5088_50880302_56_dialog_content = "Ainda assim, não há como negar a sensação familiar que vem deste caderno... Acho que não saberei até abri-lo e ver...",
  ui_story_5088_50880401_1_dialog_content = "<color=#e8d9bb>No meio de uma fria noite de inverno, um grupo especial de pessoas se reúne logo fora de uma caverna congelada.</color>",
  ui_story_5088_50880401_2_dialog_content = "<color=#e8d9bb>De dentro da caverna, seu venerável e envelhecido mestre fala sobre uma existência que eles devem proteger.</color>",
  ui_story_5088_50880401_3_dialog_content = "... O rei cumpriu sua promessa e a paz foi restaurada. Agora, não há necessidade do mundo lembrar dos Soldados Eclipsitas, ou das técnicas de aumento que deram origem a eles.",
  ui_story_5088_50880401_4_dialog_content = "As crianças que foram exiladas dessas terras encontraram novas tribos para chamar de suas. De fato, alguns afirmam que até descobriram um paraíso flutuando no céu.",
  ui_story_5088_50880401_5_dialog_content = "A família da Senhora Freya reconstruiu a cidade fronteiriça em um lugar esplêndido e belo. A montanha congelada, que existia desde tempos imemoriais, derreteu e formou um lago tão prístino e vítreo quanto um espelho.",
  ui_story_5088_50880401_6_dialog_content = "*Tosse* E ainda... Eu nunca consegui encontrar Eraveil.",
  ui_story_5088_50880401_7_dialog_content = "Embora minha vida tenha durado muitos anos, não consegui levar nossa querida amiga Ludweiss de volta para casa e colocá-la para descansar.",
  ui_story_5088_50880401_8_dialog_content = "... Não é sua culpa, Anthony.",
  ui_story_5088_50880401_9_dialog_content = "Envelheci, Senhor Aquiles... A morte ameaça me levar a qualquer momento.",
  ui_story_5088_50880401_10_dialog_content = "Mas antes disso, tenho mais a dizer para você. É por isso que pedi aos meus filhos para me trazerem aqui hoje.",
  ui_story_5088_50880401_11_dialog_content = "Desejo expressar meu remorso, meu senhor. Ao falhar em completar a missão que me deu, falhei com você como seu guarda... E embora eu seja seu soldado, não tenho como morrer ao seu lado na batalha.",
  ui_story_5088_50880401_12_dialog_content = "Acreditei ser leal, e ainda assim não fiz nada além de decepcioná-lo... e mesmo no fim, terei que fechar meus olhos diante de você.",
  ui_story_5088_50880401_13_dialog_content = "Levante a cabeça, Anthony. Não o culpo, apenas o máximo de orgulho e gratidão.",
  ui_story_5088_50880401_14_dialog_content = "Você já fez mais do que o suficiente por nós, meu amigo.",
  ui_story_5088_50880401_15_dialog_content = "Não... Você merece muito mais do que isso, meu senhor! Você já perdeu tantas pessoas... Você deve achar que sou cruel por deixar você me ver em meu estado velho e moribundo.",
  ui_story_5088_50880401_16_dialog_content = "Mas eu estava preocupado que, se eu não viesse, você se preocuparia desnecessariamente por minha causa.",
  ui_story_5088_50880401_17_dialog_content = "Como seu guarda... É apenas certo que eu morra antes de você. Se eu não soubesse sobre seu imenso fardo, sonharia em lutar ao seu lado novamente algum dia.",
  ui_story_5088_50880401_18_dialog_content = "Meu general, o herói do reino... Você devorou a escuridão, mas eu sou o único que testemunhou sua luz.",
  ui_story_5088_50880401_19_dialog_content = "Meus descendentes serão os que ficarão ao seu lado a partir de agora... Mas poucos se lembrarão da grandeza de suas realizações.",
  ui_story_5088_50880401_20_dialog_content = "Tenha certeza, Anthony.",
  ui_story_5088_50880401_21_dialog_content = "Mesmo que a história nos esqueça, nunca abandonarei meu propósito. Fiz uma promessa aos meus camaradas de que suportaria tudo.",
  ui_story_5088_50880401_22_dialog_content = "Então, deixe seu remorso de lado e descanse, meu amigo cansado. Você mais do que merece isso.",
  ui_story_5088_50880401_23_dialog_content = "Ah... Seu perdão significa mais para mim do que você jamais saberá, meu senhor.",
  ui_story_5088_50880401_24_dialog_content = "Mas e o Ludweiss? Ainda não posso fechar meus olhos. Eu não posso...",
  ui_story_5088_50880401_25_dialog_content = "Você me salvou e mesmo assim eu falhei com você, Senhor Aquiles. Eu também falhei com Dominic.",
  ui_story_5088_50880401_26_dialog_content = "Olhe para trás em sua vida, Anthony.",
  ui_story_5088_50880401_27_dialog_content = "Você sempre protegeu os fracos e indefesos, bem como a nossa honra. Você semeou as sementes do amor e lealdade, e criou seus filhos e netos com orgulho.",
  ui_story_5088_50880401_28_dialog_content = "Você sacrificou riqueza e glória para manter sua promessa. Nenhuma alma brilha mais do que a sua, meu amigo.",
  ui_story_5088_50880401_29_dialog_content = "Nenhuma parte da sua vida foi gasta em vão. Você honrou os desejos daqueles que se sacrificaram... E o meu próprio desejo também.",
  ui_story_5088_50880401_30_dialog_content = "Mas...",
  ui_story_5088_50880401_31_dialog_content = "Fique em paz, Anthony. Você conquistou seu lugar no paraíso dos soldados.",
  ui_story_5088_50880401_32_dialog_content = "E se fechar as portas para você, estarei lá para abri-las com minha lâmina.",
  ui_story_5088_50880401_33_dialog_content = "Então não se preocupe... Ludweiss e eu vamos permanecer neste mundo, esperando pelo amanhecer do futuro que ela uma vez viu.",
  ui_story_5088_50880401_34_dialog_content = "Então deixe seus momentos finais serem preenchidos com esperança, meu amigo.",
  ui_story_5088_50880401_35_dialog_content = "Senhor Aquiles...",
  ui_story_5088_50880401_36_dialog_content = "Quer saber por que estou indo tão longe por eles?",
  ui_story_5088_50880401_37_dialog_content = "Você está fazendo o mesmo, não está? Pelo que me diz respeito, não há diferença entre nós.",
  ui_story_5088_50880401_38_dialog_content = "Como fiel guarda do Senhor Aquiles, tenho um dever a cumprir.",
  ui_story_5088_50880401_39_dialog_content = "Mas não tenho certeza se as coisas podem realmente mudar...",
  ui_story_5088_50880401_40_dialog_content = "Ei, Anthony... Se você me perguntar, é exatamente isso que é a esperança: uma tocha que queima na noite mais escura.",
  ui_story_5088_50880401_41_dialog_content = "Sei que vou ficar esgotado...",
  ui_story_5088_50880401_42_dialog_content = "Mas o caminho que forjei guiará outros para fora da escuridão.",
  ui_story_5088_50880401_43_dialog_content = "A partir de agora, aqueles que seguem este caminho não precisam mais temer se perder.",
  ui_story_5088_50880401_44_dialog_content = "As estrelas brilham para todos nós. Você, eu e inúmeras outras pessoas que sofrem em nosso mundo.",
  ui_story_5088_50880401_45_dialog_content = "Você realmente acha que eles poderiam ver o lado bom antes de começarem?",
  ui_story_5088_50880401_46_dialog_content = "Você está dizendo...",
  ui_story_5088_50880401_47_dialog_content = "Olhe atrás de você, Anthony.",
  ui_story_5088_50880401_48_dialog_content = "Você já iluminou o caminho para tantas pessoas.",
  ui_story_5088_50880401_49_dialog_content = "Pode não ser agora, mas essa mudança definitivamente acontecerá em algum momento no futuro, e tudo graças ao que você fez na vida.",
  ui_story_5088_50880401_50_dialog_content = "Tenha fé no futuro. Você fez tanto por todos, mas agora é a sua vez de descansar.",
  ui_story_5088_50880401_51_dialog_content = "Eu... realmente mereço isso?",
  ui_story_5088_50880401_52_dialog_content = "Ei, você realmente precisa perguntar?",
  ui_story_5088_50880401_53_dialog_content = "Anthony Longinus... Tenho a honra de ter presenciado o momento em que a chama de sua alma orgulhosa e nobre foi extinta. Esteja bem em sua jornada para o paraíso do soldado, meu amigo.",
  ui_story_5088_50880401_54_dialog_content = "Você merece tudo.",
  ui_story_5088_50880401_55_dialog_content = "O avô sorriu ao falecer.",
  ui_story_5088_50880401_56_dialog_content = "...",
  ui_story_5088_50880401_57_dialog_content = "Como seu sucessor, tenho a honra de entrar nesta caverna e servi-lo, Senhor Aquiles.",
  ui_story_5088_50880401_58_dialog_content = "Então, pegue este emblema e use-o com orgulho.",
  ui_story_5088_50880401_59_dialog_content = "Apresento-o a ele e a você, seus nobres descendentes.",
  ui_story_5088_50880401_60_dialog_content = "M-Mas meu senhor, este emblema... É muito precioso para nós aceitarmos.",
  ui_story_5088_50880401_61_dialog_content = "Anthony era meu companheiro de armas, além de um verdadeiro amigo. Ele ganhou meu respeito, e por isso estendo o mesmo a você.",
  ui_story_5088_50880401_62_dialog_content = "Só espero que o poder deste emblema seja útil para a sua família.",
  ui_story_5088_50880401_63_dialog_content = "Leve-o para casa. Seu avô viveu uma vida plena e significativa, e merece ser posto para descansar com as lágrimas e bênçãos de sua família.",
  ui_story_5088_50880401_64_dialog_content = "E-Eu entendo, Senhor Aquiles. Se nos der licença...",
  ui_story_5088_50880401_65_dialog_content = "Meus amigos... Eu gostaria de descansar meus olhos por um tempo também...",
  ui_story_5088_50880401_66_dialog_content = "...",
  ui_story_5088_50880401_67_dialog_content = "Por favor... Visite-me em meus sonhos e faça-me companhia mais uma vez.",
  ui_story_5088_50880401_68_dialog_content = "<color=#e8d9bb>E assim começou seu sonho solitário e infinito.</color>",
  ui_story_5088_50880401_69_dialog_content = "<color=#e8d9bb>Mas ele se desviará de seu mundo mais uma vez quando despertar de seu sono.</color>",
  ui_story_5088_50880401_70_dialog_content = "Desculpe-me... Mas você sabe como entrar em Eraveil?",
  ui_story_5088_50880401_71_dialog_content = "Estivemos procurando o lugar por anos e nos disseram que a entrada estava próxima.",
  ui_story_5088_50880401_72_dialog_content = "Hã? Por que está indo para Eraveil?",
  ui_story_5088_50880401_73_dialog_content = "... Temos uma promessa para cumprir.",
  ui_story_5088_50880401_74_dialog_content = "Perdoe-me por ser direto, mas você se parece muito com o Celestita mencionado nas lendas da nossa família.",
  ui_story_5088_50880401_75_dialog_content = "Ah, é mesmo? Bem, você está com sorte porque eu aconteço ser...",
  ui_story_5088_50880401_76_dialog_content = "<color=#FFB400>Aumento de Força!</color>",
  ui_story_5088_50880401_77_dialog_content = "Tudo bem, vocês estranhos forasteiros, vamos ver que tipo de pensamentos perversos vocês têm em suas cabeças...",
  ui_story_5088_50880401_78_dialog_content = "Você está acordado, Senhor Aquiles!",
  ui_story_5088_50880401_79_dialog_content = "Você é... o neto do Anthony?",
  ui_story_5088_50880401_80_dialog_content = "Não, meu senhor. Já se passaram muitas, muitas eras desde o tempo de nossos ancestrais.",
  ui_story_5088_50880401_81_dialog_content = "?!",
  ui_story_5088_50880401_82_dialog_content = "Minhas memórias foram quebradas novamente... Quantas delas eu perdi desta vez?",
  ui_story_5088_50880401_83_dialog_content = "... Por favor, não fique triste, Senhor Aquiles.",
  ui_story_5088_50880401_84_dialog_content = "Viemos trazer boas notícias.",
  ui_story_5088_50880401_85_dialog_content = "Oh... Eles estavam dizendo a verdade afinal.",
  ui_story_5088_50880401_86_dialog_content = "Então você é Claymore, huh?",
  ui_story_5088_50880401_87_dialog_content = "Devo pedir que você se dirija ao Senhor Aquiles de uma maneira mais adequada, Sr. Czerny.",
  ui_story_5088_50880401_88_dialog_content = "Sério? Porque eu acho que Claymore parece muito mais legal.",
  ui_story_5088_50880401_89_dialog_content = "Você... Você está...?",
  ui_story_5088_50880401_90_dialog_content = "Sua roupas... seu rosto...",
  ui_story_5088_50880401_91_dialog_content = "Você é um dos seguidores de Ludweiss?",
  ui_story_5088_50880401_92_dialog_content = "Desculpe, mas eu não conheço nenhum Ludweiss. Nosso povo não gosta muito de correr pelo mundo exterior, sabe?",
  ui_story_5088_50880401_93_dialog_content = "Ela uma vez disse... Sua família deixou Eraveil há muito tempo, então ela passou a vida inteira procurando por ele novamente.",
  ui_story_5088_50880401_94_dialog_content = "Vocês dois... podem me dizer seus nomes?",
  ui_story_5088_50880401_95_dialog_content = "Farei o meu melhor para lembrar.",
  ui_story_5088_50880401_96_dialog_content = "Seria uma honra, meu senhor... Eu sou Dominic Longinus, e moro numa ilha atualmente conhecida como Azurite.",
  ui_story_5088_50880401_97_dialog_content = "Dominic... Ouvir esse nome me enche de nostalgia.",
  ui_story_5088_50880401_98_dialog_content = "O Sr. Anthony desejava que, em qualquer época, uma presença familiar estivesse lá para cumprimentá-lo ao acordar.",
  ui_story_5088_50880401_99_dialog_content = "Desculpe se pareci rude agora. Meu nome é Czerny, e encontrei seu amigo aqui vagando por Eraveil, então dei uma pequena olhada em sua mente.",
  ui_story_5088_50880401_100_dialog_content = "Vi toda a sua história, e tenho que dizer... Foi incrível!",
  ui_story_5088_50880401_101_dialog_content = "Especialmente sua amizade com aquela garota Celestita! A coisa toda me abalou até o âmago!",
  ui_story_5088_50880401_102_dialog_content = "Então, não só vou levar Ludweiss de volta para Eraveil para descansar, como também vou salvar todos vocês!",
  ui_story_5088_50880401_103_dialog_content = "Agora, onde está aquele selo? Algum Celestita pode desfazê-lo?",
  ui_story_5088_50880401_104_dialog_content = "... Por favor, não os libere agora.",
  ui_story_5088_50880401_105_dialog_content = "Ainda não é a hora deles.",
  ui_story_5088_50880401_106_dialog_content = "Hã?",
  ui_story_5088_50880401_107_dialog_content = "... Ludweiss os selou para evitar que a corrupção em seus corpos se espalhasse para suas mentes.",
  ui_story_5088_50880401_108_dialog_content = "Ela queria dar a eles um alívio muito necessário de seu sofrimento.",
  ui_story_5088_50880401_109_dialog_content = "Apenas quando seus corpos forem completamente transformados haverá esperança de preservar sua sensibilidade.",
  ui_story_5088_50880401_110_dialog_content = "Também infundi magia incolor em todos os seus selos. Uma vez que seus corpos tenham sido liberados, quero libertar suas emoções trancadas também.",
  ui_story_5088_50880401_111_dialog_content = "Eu realmente não entendo... Mas tudo bem. Afinal, é a sua decisão.",
  ui_story_5088_50880401_112_dialog_content = "Você tem combatido a corrupção por muito tempo também, não é?",
  ui_story_5088_50880401_113_dialog_content = "Vou te ajudar a encontrar uma saída para essa bagunça... E se isso não funcionar, também posso te selar.",
  ui_story_5088_50880401_114_dialog_content = "É realmente possível?",
  ui_story_5088_50880401_115_dialog_content = "Não custa tentar, não é?",
  ui_story_5088_50880401_116_dialog_content = "Podemos descobrir primeiro como te salvar, depois podemos levar Ludweiss de volta e deixá-la descansar.",
  ui_story_5088_50880401_117_dialog_content = "... Eu não posso ser selado como os outros. Se eu entrar em um estado similar de inconsciência, não haverá ninguém para manter o selo deles.",
  ui_story_5088_50880401_118_dialog_content = "Agradeço sua gentil oferta, mas tenho o dever de preservar esta formação e garantir que meus amigos permaneçam selados.",
  ui_story_5088_50880401_119_dialog_content = "Ah... Isso também é bom! Temos muito tempo! Vou ficar por aqui e tentar algumas coisas. Sinta-se à vontade para ir para casa quando quiser, Dominic.",
  ui_story_5088_50880401_120_dialog_content = "Se precisar de algo, Sr. Czerny, tudo o que precisa fazer é pedir. Nossa família está mais do que disposta a ajudá-lo.",
  ui_story_5088_50880401_121_dialog_content = "Czerny... Você realmente viajou até aqui direto de Eraveil simplesmente porque foi tocado pela nossa história?",
  ui_story_5088_50880401_122_dialog_content = "Claro! Mas também quero provar algo para mim mesmo.",
  ui_story_5088_50880401_123_dialog_content = "Quero provar... que não sou um fracote.",
  ui_story_5088_50880401_124_dialog_content = "Quero que todos saibam que também sou capaz de realizar grandes coisas. Quando tudo isso acabar, tenho certeza de que todos finalmente me respeitarão como um herói!",
  ui_story_5088_50880401_125_dialog_content = "E então, eles não terão escolha a não ser me escolher como uma Colossus'... Ah, mas isso é irrelevante.",
  ui_story_5088_50880401_126_dialog_content = "Qualquer um que resgate um herói também pode ser chamado de herói, certo?",
  ui_story_5088_50880401_127_dialog_content = "É bom ter uma ambição, Czerny. Independentemente dos seus motivos para estar aqui, sou grato por você ter vindo.",
  ui_story_5088_50880401_128_dialog_content = "Mas a grandeza de uma pessoa não vem apenas de suas realizações.",
  ui_story_5088_50880401_129_dialog_content = "Espero que você se lembre do que queria em primeiro lugar.",
  ui_story_5088_50880401_130_dialog_content = "Sim, claro, eu te ouço. Apenas deixe comigo!",
  ui_story_5088_50880401_131_dialog_content = "Agora então, por onde devo começar...",
  ui_story_5088_50880401_132_dialog_content = "Realmente não há necessidade de você fazer isso, Czerny. Já muitas pessoas se sacrificaram por nós.",
  ui_story_5088_50880401_133_dialog_content = "Então por favor, apenas leve Ludweiss de volta para Eraveil.",
  ui_story_5088_50880401_134_dialog_content = "Eu seria eternamente grato a você por fazer isso sozinho.",
  ui_story_5088_50880401_135_dialog_content = "<color=#FFB400>Aumento de Força!</color>",
  ui_story_5088_50880402_1_dialog_content = "... Isso vai ser mais complicado do que eu pensava.",
  ui_story_5088_50880402_2_dialog_content = "Não tenho dúvida disso.",
  ui_story_5088_50880402_3_dialog_content = "Mas não se preocupe, eu vou encontrar um jeito!",
  ui_story_5088_50880402_4_dialog_content = "Além disso, você poderia usar a companhia, não acha?",
  ui_story_5088_50880402_5_dialog_content = "Dominic pode cuidar de toda a comida e água que eu preciso, então não se preocupe comigo.",
  ui_story_5088_50880402_6_dialog_content = "Haha, essa também é uma nova e emocionante aventura para mim, sabe!",
  ui_story_5088_50880402_7_dialog_content = "... Nesse caso, você pode ficar com o resto dos meus camaradas.",
  ui_story_5088_50880402_8_dialog_content = "Mas não importa o que você possa ouvir à noite, você não pode sair daquele lugar. Entendeu?",
  ui_story_5088_50880402_9_dialog_content = "Oh? Isso está começando a soar muito mais perigoso agora!",
  ui_story_5088_50880402_10_dialog_content = "Minha luz há muito foi drenada. Não há como dizer quanto tempo mais eu posso aguentar.",
  ui_story_5088_50880402_11_dialog_content = "Você vê aquelas marcas na parede? Essas foram o meu trabalho manual.",
  ui_story_5088_50880402_12_dialog_content = "Mas se você ficar perto deles, eu não vou chegar perto de você.",
  ui_story_5088_50880402_13_dialog_content = "...",
  ui_story_5088_50880402_14_dialog_content = "Humph, boa tentativa, mas você não vai me assustar. Já que eu já aceitei essa tarefa, vou fazer um bom trabalho. Espere e verá!",
  ui_story_5088_50880402_15_dialog_content = "Estou sem pistas novamente... O que aconteceu a seguir? E quem é esse cara Czerny, afinal?",
  ui_story_5088_50880402_16_dialog_content = "(Ele não parece muito confiável. Isso é realmente ok?)",
  ui_story_5088_50880402_17_dialog_content = "Suspiro... Eu deveria escrever para Jeriah.",
  ui_story_5088_50880402_18_dialog_content = "(Ela é uma especialista em história. Talvez ela saiba mais sobre os Guerreiros Estelares?)",
  ui_story_5088_50880402_19_dialog_content = "O que... Meu nariz está sangrando?",
  ui_story_5088_50880402_20_dialog_content = "(Eu tenho usado demais meus poderes ultimamente?)",
  ui_story_5088_50880402_21_dialog_content = "Isso não é bom... Não posso deixar ninguém me ver assim...",
  ui_story_5088_50880402_22_dialog_content = "Então isso também não vai funcionar, hein? Me pergunto o que deu errado desta vez...",
  ui_story_5088_50880402_23_dialog_content = "Eu não quero te culpar, Czerny, mas... por favor, pare de desperdiçar mais tempo com isso.",
  ui_story_5088_50880402_24_dialog_content = "Não vale a pena o tempo, você ainda é jovem.",
  ui_story_5088_50880402_25_dialog_content = "Sem chance! Na verdade, é exatamente por isso que não posso desistir agora!",
  ui_story_5088_50880402_26_dialog_content = "Você pode não saber disso, mas meu povo se tornou complacente desde que Eraveil decidiu se retirar da guerra.",
  ui_story_5088_50880402_27_dialog_content = "Encontrar paz e tranquilidade ao se afastar do mundo... Ou é o que dizemos. A verdade é que estamos apenas nos escondendo em nossa própria bolha.",
  ui_story_5088_50880402_28_dialog_content = "Mas mesmo assim, ainda estamos envolvidos em todos os tipos de conflito.",
  ui_story_5088_50880402_29_dialog_content = "Vou provar a todos que eu posso fazer isso. Eu tenho o que é preciso.",
  ui_story_5088_50880402_30_dialog_content = "...",
  ui_story_5088_50880402_31_dialog_content = "Não vou a lugar nenhum ficando em casa. Em vez de ficar preso no chão para sempre, prefiro arriscar e ver o quão alto posso voar.",
  ui_story_5088_50880402_32_dialog_content = "Ainda há tempo, então por favor apenas confie em mim! Eu prometo que encontrarei uma maneira de selar você ou impedir que a corrupção tome conta da sua mente.",
  ui_story_5088_50880402_33_dialog_content = "Eu só preciso de alguns dias para descansar... Apenas alguns serão suficientes...",
  ui_story_5088_50880402_34_dialog_content = "... Desculpe, Czerny, mas estou ficando sem tempo.",
  ui_story_5088_50880402_35_dialog_content = "Já passei por todos os diários de Ludweiss.",
  ui_story_5088_50880402_36_dialog_content = "Mas, além de histórias e partituras, nada pode me ajudar.",
  ui_story_5088_50880402_37_dialog_content = "Estive fora por tanto tempo... Eu me pergunto quantas vezes eu poderia ter sido escolhido como piloto até agora...",
  ui_story_5088_50880402_38_dialog_content = "Droga!",
  ui_story_5088_50880402_39_dialog_content = "Eu não acho que as partituras sejam inúteis.",
  ui_story_5088_50880402_40_dialog_content = "Então você ouviu, huh? Mas eu estou aqui fora.",
  ui_story_5088_50880402_41_dialog_content = "Czerny, no meu mundo cruel e implacável, palavras de ódio são facilmente proferidas, mas poucos conseguem manter sua bondade diante da dor.",
  ui_story_5088_50880402_42_dialog_content = "Essa música, que vem do coração, é um testemunho da glória do povo deste mundo.",
  ui_story_5088_50880402_43_dialog_content = "Há muitos anos, tive o privilégio de ouvir uma das músicas de Ludweiss. Era uma melodia elegante e compassiva, tão suave e gentil quanto a luz da lua.",
  ui_story_5088_50880402_44_dialog_content = "Você poderia... entrar nos meus sonhos e me ajudar a lembrar da música dela mais uma vez?",
  ui_story_5088_50880402_45_dialog_content = "A noite está escura e este lugar é tão frio. Acho que ambos poderíamos usar o brilho calmo da lua.",
  ui_story_5088_50880402_46_dialog_content = "... Agora que sua luz foi devorada, a única coisa que resta é a escuridão que continua a corromper você por dentro.",
  ui_story_5088_50880402_47_dialog_content = "Mesmo como um Celestita, não consigo discernir sua cor. Me desculpe, mas sua mente é muito perigosa para eu entrar agora.",
  ui_story_5088_50880402_48_dialog_content = "Não tenho como procurar com segurança em sua consciência uma maneira de separá-lo dessa escuridão. É por isso que isso está me levando tanto tempo.",
  ui_story_5088_50880402_49_dialog_content = "Mas por favor, só me dê um pouco mais de tempo...",
  ui_story_5088_50880402_50_dialog_content = "Certo... Depois de tirar um dia para descansar, eu deveria ser capaz de continuar procurando através dessas memórias...",
  ui_story_5088_50880402_51_dialog_content = "(Acho que meu palpite está certo. Alguém espalhou deliberadamente essas notas por todo o Astra.)",
  ui_story_5088_50880402_52_dialog_content = "(Mesmo que a escrita seja quase completamente ilegível, as páginas ainda estão tão cheias de história. É quase como se quem fez isso não pudesse suportar destruir essas notas.)",
  ui_story_5088_50880402_53_dialog_content = "(Como se... Estivessem esperando que um Caelestite os sentisse algum dia.)",
  ui_story_5088_50880402_54_dialog_content = "... De qualquer forma, é hora de começar a trabalhar.",
  ui_story_5088_50880402_55_dialog_content = "Como isso pode estar acontecendo? Treinei por mais de uma década apenas para poder pilotar um Colossus.",
  ui_story_5088_50880402_56_dialog_content = "Então, por que sou tão inútil quando se trata de ajudar Claymore?",
  ui_story_5088_50880402_57_dialog_content = "Não deveria ser assim... Não deveria...",
  ui_story_5088_50880402_58_dialog_content = "Estou aqui há tanto tempo. Não posso possivelmente voltar para casa de mãos vazias.",
  ui_story_5088_50880402_59_dialog_content = "Czerny...",
  ui_story_5088_50880402_60_dialog_content = "A-Apenas me dê um segundo para descansar. Eu tenho usado meus poderes psíquicos por tanto tempo que parece que minha cabeça vai se partir ao meio.",
  ui_story_5088_50880402_61_dialog_content = "Corra, Czerny.",
  ui_story_5088_50880402_62_dialog_content = "Hã?",
  ui_story_5088_50880402_63_dialog_content = "Não consegui me livrar deles—",
  ui_story_5088_50880402_64_dialog_content = "A escuridão dentro de mim está aumentando.",
  ui_story_5088_50880402_65_dialog_content = "Você tem que ir, agora! Caso contrário...",
  ui_story_5088_50880402_66_dialog_content = "Eu vou te matar!",
  ui_story_5088_50880402_67_dialog_content = "N-De jeito nenhum!",
  ui_story_5088_50880402_68_dialog_content = "Ah, não, ele está sério... ele não vai durar muito mais tempo.",
  ui_story_5088_50880402_69_dialog_content = "Como isso pode acontecer? O que estou perdendo aqui?!",
  ui_story_5088_50880402_70_dialog_content = "Isso mesmo, os diários! Preciso vasculhar cada detalhe da mente dela e encontrar a resposta...",
  ui_story_5088_50880402_71_dialog_content = "PlayerName! Acordar! Por que você está dormindo no chão?",
  ui_story_5088_50880402_72_dialog_content = "E olhe para você mesmo! Você tem sangue seco escorrendo do seu nariz até o peito.",
  ui_story_5088_50880402_73_dialog_content = "Apenas o que é que você está escondendo de nós? Conte-nos!",
  ui_story_5088_50880402_74_dialog_content = "Desculpe, mas ainda não posso te dizer!",
  ui_story_5088_50880402_75_dialog_content = "Por favor, apenas me dê mais alguns dias e eu te contarei tudo. Te vejo!",
  ui_story_5088_50880402_76_dialog_content = "Ei, espera!",
  ui_story_5088_50880402_77_dialog_content = "(Não posso contar nada a eles se Claymore foi salvo. Eu simplesmente não posso...)",
  ui_story_5088_50880402_78_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5088_50880402_79_dialog_content = "Não... Isso não pode ser possível...",
  ui_story_5088_50880402_80_dialog_content = "Ela fez sua <color=#FFB400>escolha</color> há muito tempo. Ela até mesmo <color=#FFB400>previu</color> isso...",
  ui_story_5088_50880402_81_dialog_content = "A pessoa que vai salvá-los não sou eu, mas outro Celestita no futuro distante.",
  ui_story_5088_50880402_82_dialog_content = "<color=#e8d9bb>Na chuva pesada, o rugido do trovão rasga o céu. Profundamente dentro da caverna congelada, outro rugido pode ser ouvido...</color>",
  ui_story_5088_50880402_83_dialog_content = "Graaaaaaah—!!!",
  ui_story_5088_50880402_84_dialog_content = "<color=#e8d9bb>Com um corte poderoso, uma onda de energia pura surge da caverna e rasga o chão ao meio.</color>",
  ui_story_5088_50880402_85_dialog_content = "<color=#e8d9bb>Embora o golpe tenha quase errado Czerny, seu espírito é completamente dominado por sua intenção assassina.</color>",
  ui_story_5088_50880402_86_dialog_content = "<color=#e8d9bb>Nesse momento, ele finalmente percebe o quão perigoso seu companheiro pode ser.</color>",
  ui_story_5088_50880402_87_dialog_content = "Por que... Por que tem que ser assim...?",
  ui_story_5088_50880402_88_dialog_content = "<color=#e8d9bb>Tremendo violentamente, Czerny tenta se levantar, mas suas pernas falham logo em seguida.</color>",
  ui_story_5088_50880402_89_dialog_content = "<color=#e8d9bb>Ele deixa cair os diários de Ludweiss, e a tempestade uivante rapidamente espalha as páginas.</color>",
  ui_story_5088_50880402_90_dialog_content = "Não! Nããão-!!!",
  ui_story_5088_50880402_91_dialog_content = "<color=#e8d9bb> Czerny agarra desesperadamente as páginas, mas só consegue recuperar um punhado delas.</color>",
  ui_story_5088_50880402_92_dialog_content = "<color=#e8d9bb>Ele falhou.</color>",
  ui_story_5088_50880402_93_dialog_content = "Eu... eu falhei com eles... Todos eles.",
  ui_story_5088_50880402_94_dialog_content = "Eu desperdicei os esforços finais de Ludweiss...",
  ui_story_5088_50880402_95_dialog_content = "E eu falhei com Aquiles.",
  ui_story_5088_50880402_96_dialog_content = "<color=#e8d9bb>A chuva eventualmente diminui após um período de tempo desconhecido, junto com os terríveis sons vindos de dentro da caverna.</color>",
  ui_story_5088_50880402_97_dialog_content = "<color=#e8d9bb>Czerny entra na caverna mais uma vez, segurando as poucas páginas do caderno que conseguiu recuperar.</color>",
  ui_story_5088_50880402_98_dialog_content = "Não há realmente nada que possamos fazer para ajudar você? Aquiles...",
  ui_story_5088_50880402_99_dialog_content = "...",
  ui_story_5088_50880402_100_dialog_content = "Eu não pude fazer nada por você além de desperdiçar seu tempo. Eu nunca vali nada, não é?",
  ui_story_5088_50880402_101_dialog_content = "Diga-me, Aquiles! Diga-me que tolo eu sou!",
  ui_story_5088_50880402_102_dialog_content = "Saia, Czerny. Com meus últimos momentos de lucidez, quero agradecer por ficar comigo todo esse tempo.",
  ui_story_5088_50880402_103_dialog_content = "Ter alguém para conversar era suficiente para aplacar os monstros no meu coração.",
  ui_story_5088_50880402_104_dialog_content = "Deixe este lugar e não conte a ninguém sobre isso... Não quero que mais pessoas de bom coração... sacrifiquem algo por minha causa.",
  ui_story_5088_50880402_105_dialog_content = "Ahhhhhh—!!!",
  ui_story_5088_50880402_106_dialog_content = "Até mais... Czerny.",
  ui_story_5088_50880402_107_dialog_content = "Você não falhou, Czerny, eu ainda posso te ajudar!",
  ui_story_5088_50880402_108_dialog_content = "Não, minha voz não pode alcançá-lo...",
  ui_story_5088_50880402_109_dialog_content = "Argh, por que isso está acontecendo agora?!",
  ui_story_5088_50880402_110_dialog_content = "Deixe-me ajudar você, Czerny! Eu posso—",
  ui_story_5088_50880402_111_dialog_content = "Espere, não o deixe sozinho!!!",
  ui_story_5088_50880402_112_dialog_content = "Ainda posso te ajudar!!!",
  ui_story_5088_50880501_1_dialog_content = "Você está coberto de sangue novamente. Até os Celestitas têm um limite para seus poderes, não têm?",
  ui_story_5088_50880501_2_dialog_content = "Com quem... você está falando?",
  ui_story_5088_50880501_3_dialog_content = "Czerny... Onde está Czerny?!",
  ui_story_5088_50880501_4_dialog_content = "Não há mais ninguém aqui além de nós.",
  ui_story_5088_50880501_5_dialog_content = "Espere, quem é Czerny?",
  ui_story_5088_50880501_6_dialog_content = "Não... Não, não! Ele estava bem ali! Ele também estava chorando... Eu tenho que ajudá-lo a salvar Aquiles—",
  ui_story_5088_50880501_7_dialog_content = "Saia do meu caminho! Eu vou usar minha magia de cura para-",
  ui_story_5088_50880501_8_dialog_content = "Isso não será necessário. Eu posso cuidar das coisas daqui.",
  ui_story_5088_50880501_9_dialog_content = "Ugh...",
  ui_story_5088_50880501_10_dialog_content = "Apenas olhe todo esse sangue! O que você tem feito nesses últimos dias?!",
  ui_story_5088_50880501_11_dialog_content = "Este mensageiro foi gentil o suficiente para fazer um remédio para você parar o sangramento. Você deveria agradecê-la pelo esforço.",
  ui_story_5088_50880501_12_dialog_content = "Th-Obrigado.",
  ui_story_5088_50880501_13_dialog_content = "Não é nada. Só vim pegar sua correspondência.",
  ui_story_5088_50880501_14_dialog_content = "Não somos idiotas... Seja lá o que você está fazendo, tem algo a ver conosco.",
  ui_story_5088_50880501_15_dialog_content = "E veja onde você se meteu. Se você não nos contar nada, terei que contar a alguém sobre o seu segredo, talvez—",
  ui_story_5088_50880501_16_dialog_content = "Não diga a Vice ou Carleen sobre isso! Por favor!",
  ui_story_5088_50880501_17_dialog_content = "Então, você vai falar?",
  ui_story_5088_50880501_18_dialog_content = "Eu... Estou tentando aprender a verdade sobre algo. Desculpe... Mas é tudo que posso te dizer agora.",
  ui_story_5088_50880501_19_dialog_content = "Quando chegar a hora, vou te contar tudo.",
  ui_story_5088_50880501_20_dialog_content = "Você está se segurando porque está preocupado com o que vamos sentir?",
  ui_story_5088_50880501_21_dialog_content = "É por causa do meu sonho que você está envolvido nisso tudo agora.",
  ui_story_5088_50880501_22_dialog_content = "Desculpe... Mas eu tenho que descobrir a verdade sobre o que aconteceu com Aquiles... Quero dizer, Claymore.",
  ui_story_5088_50880501_23_dialog_content = "Mas não consigo alcançá-los depois que deixei seu sonho...",
  ui_story_5088_50880501_24_dialog_content = "Deve haver algum outro meio de transmitir meus pensamentos... Victoria uma vez disse que todos os pensamentos dos Celestitas alcançariam...",
  ui_story_5088_50880501_25_dialog_content = "Eu... Eu tenho que ajudá-los...",
  ui_story_5088_50880501_26_dialog_content = "Há um Celestita ao lado dele. Ele ainda não desistiu...",
  ui_story_5088_50880501_27_dialog_content = "Você parece que mal tem sangue no corpo. Se continuar se esforçando assim, vai morrer.",
  ui_story_5088_50880501_28_dialog_content = "Por que você está indo tão longe por um grupo de forasteiros como nós?",
  ui_story_5088_50880501_29_dialog_content = "Não há estranhos no Soroz. Você é família.",
  ui_story_5088_50880501_30_dialog_content = "?!",
  ui_story_5088_50880501_31_dialog_content = "Hum...",
  ui_story_5088_50880501_32_dialog_content = "(E também... Eu sou igual ao Czerny. Eu não posso simplesmente ficar parado e não fazer nada, não depois de ver a história deles.)",
  ui_story_5088_50880501_33_dialog_content = "(Recuso-me a deixar essas estrelas desaparecerem de forma tão trágica.)",
  ui_story_5088_50880501_34_dialog_content = "Por favor, só preciso de um pouco mais de tempo...",
  ui_story_5088_50880501_35_dialog_content = "... Sua cabeça ainda dói?",
  ui_story_5088_50880501_36_dialog_content = "Estou bem, só preciso de um pouco de ar fresco.",
  ui_story_5088_50880501_37_dialog_content = "Quase me esqueci, mas você poderia entregar isso para Jeriah? Ela está estacionada no posto do Deserto Rediesel.",
  ui_story_5088_50880501_38_dialog_content = "... Você trata seus amigos incrivelmente bem. Você estava olhando aqueles livros antigos para seus amigos, não estava?",
  ui_story_5088_50880501_39_dialog_content = "Perdoe-me se estou sendo intrusivo, mas esta é uma carta pedindo a ajuda da Senhora Jeriah, não é?",
  ui_story_5088_50880501_40_dialog_content = "Sim...",
  ui_story_5088_50880501_41_dialog_content = "Quero ajudá-los não importa o que aconteça.",
  ui_story_5088_50880501_42_dialog_content = "Eu só quero descobrir a verdade... Mesmo que esteja muito atrasado.",
  ui_story_5088_50880501_43_dialog_content = "(Quero ver o que aconteceu com Aquiles e entender como ele acabou assim...)",
  ui_story_5088_50880501_44_dialog_content = "(Ainda tenho esperança de que posso encontrar uma maneira de ajudá-lo.)",
  ui_story_5088_50880501_45_dialog_content = "(Também, ainda preciso encontrar os restos de Ludweiss.)",
  ui_story_5088_50880501_46_dialog_content = "Peço desculpas por lhe dar respostas tão estranhas.",
  ui_story_5088_50880501_47_dialog_content = "Não seja. Fui eu quem te fez uma pergunta estranha para começar.",
  ui_story_5088_50880501_48_dialog_content = "Vou garantir que esta carta chegue em segurança à Senhora Jeriah.",
  ui_story_5088_50880501_49_dialog_content = "Obrigado pela sua ajuda e pelo remédio também. É assustador, mas definitivamente parou o sangramento.",
  ui_story_5088_50880501_50_dialog_content = "Sou um mensageiro, e os mensageiros sempre têm alguns truques na manga.",
  ui_story_5088_50880501_51_dialog_content = "Bem, já vou indo agora.",
  ui_story_5088_50880501_52_dialog_content = "Proponho que acabemos com isso bem aqui e agora.",
  ui_story_5088_50880501_53_dialog_content = "Concordo com Friegson. Recuperar nossas memórias não deveria comprometer sua saúde, então vamos parar com isso.",
  ui_story_5088_50880501_54_dialog_content = "Mesmo que isso signifique que você nunca mais se lembrará do seu amor novamente?",
  ui_story_5088_50880501_55_dialog_content = "... Eu tenho todo o tempo do mundo para continuar procurando por ela.",
  ui_story_5088_50880501_56_dialog_content = "O que você diz, Freya?",
  ui_story_5088_50880501_57_dialog_content = "\"Não há estranhos no Soroz, você é família.\" Essas foram as palavras dele.",
  ui_story_5088_50880501_58_dialog_content = "Sempre confiei nos meus amigos, e ele não é diferente. Eu respeito a decisão dele.",
  ui_story_5088_50880501_59_dialog_content = "Você ainda tem esperança, mesmo tendo sido traído no passado?",
  ui_story_5088_50880501_60_dialog_content = "Sou um cavaleiro, liderar a carga na batalha sempre foi meu dever. Algumas feridas de faca nunca poderiam me desencorajar disso.",
  ui_story_5088_50880501_61_dialog_content = "Então eu também quero acreditar nele.",
  ui_story_5088_50880501_62_dialog_content = "Não somos perfeitos de maneira alguma, então talvez não devêssemos ser tão rápidos em descartar PlayerName.",
  ui_story_5088_50880501_63_dialog_content = "No passado, não importa que tipo de dor ou fraqueza enfrentávamos, desde que tivéssemos um ao outro...",
  ui_story_5088_50880501_64_dialog_content = "Poderíamos superar qualquer coisa e continuar avançando.",
  ui_story_5088_50880501_65_dialog_content = "Uau... Isso foi lindo, Cynthia. Você não diz nada tão sério há muito tempo. Isso realmente não é nada parecido com você.",
  ui_story_5088_50880501_66_dialog_content = "Eu quero que os Caçadores Silenciosos estejam juntos novamente. O que todos pensam disso?",
  ui_story_5088_50880501_67_dialog_content = "...",
  ui_story_5088_50880501_68_dialog_content = "Mesmo depois de tudo que eu disse a ele, ele ainda teve sorte e encontrou isso com outro dos chefes.",
  ui_story_5088_50880501_69_dialog_content = "Acho que é chamado de Brasão de Estrela?",
  ui_story_5088_50880501_70_dialog_content = "...",
  ui_story_5088_50880501_71_dialog_content = "Ele está sondando o segredo dos Guerreiros Estelares...",
  ui_story_5088_50880501_72_dialog_content = "Eu... tenho que cumprir minha missão... E detê-lo...",
  ui_story_5088_50880501_73_dialog_content = "Mas...",
  ui_story_5088_50880501_74_dialog_content = "Quando se trata de ajudar meus amigos, farei o que for necessário.",
  ui_story_5088_50880501_75_dialog_content = "Devo dar a ele amanhã.",
  ui_story_5088_50880501_76_dialog_content = "Venham aqui e me encarem, seus covardes.",
  ui_story_5088_50880501_77_dialog_content = "O-O Caçador de Corvos?! De novo não!",
  ui_story_5088_50880501_78_dialog_content = "Por que você não nos deixa em paz?! Estamos apenas tentando extorquir um pouco de dinheiro dela, só isso!",
  ui_story_5088_50880501_79_dialog_content = "O que faz você pensar que ela tem algo que valha a pena roubar?",
  ui_story_5088_50880501_80_dialog_content = "Por que ela não faria isso? Ela tem trabalhado para a Guilda Cloudrover e até é amiga daquele cara Celestita.",
  ui_story_5088_50880501_81_dialog_content = "Desculpe decepcioná-los, idiotas gananciosos, mas aquilo é completamente inútil.",
  ui_story_5088_50880501_82_dialog_content = "Mas tentar roubar um objeto sem valor ainda é um crime. Prepare-se para ser punido!",
  ui_story_5088_50880502_1_dialog_content = "Oh? Parece que estou atrasado para a diversão.",
  ui_story_5088_50880502_2_dialog_content = "Ainda assim, eu sabia que te encontraria aqui.",
  ui_story_5088_50880502_3_dialog_content = "...",
  ui_story_5088_50880502_4_dialog_content = "O que há de errado? Você tem agido diferente ultimamente.",
  ui_story_5088_50880502_5_dialog_content = "E você também está sendo muito mais duro com os caras maus.",
  ui_story_5088_50880502_6_dialog_content = "Não é nada. Por que você está fora tão tarde, de qualquer maneira? Você não tem trabalho durante o dia?",
  ui_story_5088_50880502_7_dialog_content = "Eu faço... Mas tudo bem.",
  ui_story_5088_50880502_8_dialog_content = "É sempre mais importante ouvir meus amigos.",
  ui_story_5088_50880502_9_dialog_content = "Não tenho nada a dizer. Só nos conhecemos há dois anos e só nos encontramos à noite às vezes. Você realmente chamaria isso de \"amizade\"?",
  ui_story_5088_50880502_10_dialog_content = "Dois anos é muito tempo, sabe!",
  ui_story_5088_50880502_11_dialog_content = "Além disso, nos conhecemos por causa de nossos esforços para combater o crime. Isso nos torna companheiros de batalha!",
  ui_story_5088_50880502_12_dialog_content = "Camaradas de batalha? Por favor. Você nem sabe o meu nome.",
  ui_story_5088_50880502_13_dialog_content = "Você está certo, é por isso que eu adoraria te conhecer durante o dia também. Aposto que você é tão legal quanto quando não está lutando contra os caras maus!",
  ui_story_5088_50880502_14_dialog_content = "Desculpe desapontá-lo, mas não há nada de interessante em mim ou na minha vida diária.",
  ui_story_5088_50880502_15_dialog_content = "Especialmente não para alguém como você... Que brilha tão intensamente o tempo todo...",
  ui_story_5088_50880502_16_dialog_content = "Hã? Você está tentando dizer que é apenas uma pessoa comum durante o dia?",
  ui_story_5088_50880502_17_dialog_content = "Porque eu acho que você é poderoso demais para ser qualquer coisa além de extraordinário!",
  ui_story_5088_50880502_18_dialog_content = "Na verdade, aposto que você pode inspirar os outros assim como alguns dos melhores ídolos por aí!",
  ui_story_5088_50880502_19_dialog_content = "... Não seja absurdo.",
  ui_story_5088_50880502_20_dialog_content = "Sabe... Tem algo que eu gostaria de falar. É trivial, mas você estaria disposto a ouvir?",
  ui_story_5088_50880502_21_dialog_content = "Claro! E não se preocupe, não importa quão importante ou trivial seja, eu prometo manter isso em segredo.",
  ui_story_5088_50880502_22_dialog_content = "Um segredo, huh? Heheh...",
  ui_story_5088_50880502_23_dialog_content = "A verdade é, eu nasci em um clã único, e durante toda a minha vida, me foi confiada a realização de uma certa missão.",
  ui_story_5088_50880502_24_dialog_content = "Para isso, me ensinaram a sempre observar as coisas de longe e nunca me envolver.",
  ui_story_5088_50880502_25_dialog_content = "A nossa é uma família de sombras que opera além do fluxo do tempo. É por isso que devemos nos manter escondidos durante o dia.",
  ui_story_5088_50880502_26_dialog_content = "Mas agora... Aqueles que juramos proteger... Não restam muitos deles.",
  ui_story_5088_50880502_27_dialog_content = "Uau! Parece que sua família está protegendo algum tipo de criatura rara!",
  ui_story_5088_50880502_28_dialog_content = "Como você pode pensar que isso não é importante? Proteger algo como sua missão na vida requer muito foco e cautela.",
  ui_story_5088_50880502_29_dialog_content = "Acho incrível que você consiga manter sua luz escondida pelo bem da sua missão.",
  ui_story_5088_50880502_30_dialog_content = "Uma \"criatura rara\"... Isso não está totalmente errado, eu suponho. De qualquer forma, se eu falhar em cumprir minha missão, então isso mais ou menos terminará comigo.",
  ui_story_5088_50880502_31_dialog_content = "Porque aquela pessoa... Não tenho certeza se essa pessoa é capaz de cumprir a profecia.",
  ui_story_5088_50880502_32_dialog_content = "E então meu clã estará ligado pelo resto do tempo.",
  ui_story_5088_50880502_33_dialog_content = "Mas além disso, eu... eu só quero ajudar aquele determinado grupo de pessoas.",
  ui_story_5088_50880502_34_dialog_content = "Mas eu fiz um voto para proteger seus segredos, então só posso vigiá-los em silêncio. Não posso trair meu voto.",
  ui_story_5088_50880502_35_dialog_content = "É isso que vem te incomodando?",
  ui_story_5088_50880502_36_dialog_content = "Você tem descontado sua frustração nos caras maus por causa disso?",
  ui_story_5088_50880502_37_dialog_content = "Por várias razões que não posso discutir, meus ancestrais conseguiram imbuir algumas de suas memórias em nossa herança de família, que tem sido passada de geração em geração.",
  ui_story_5088_50880502_38_dialog_content = "Através disso, posso ouvir a raiva e os arrependimentos deles.",
  ui_story_5088_50880502_39_dialog_content = "Mas o senhor uma vez nos disse para não envolver ninguém mais por causa dele.",
  ui_story_5088_50880502_40_dialog_content = "Desde então, nos mantivemos escondidos e observamos em silêncio, esperando pelo profetizado para cumprir nossa missão e libertar a todos nós.",
  ui_story_5088_50880502_41_dialog_content = "Mas o povo do profetizado... Todos eles foram...",
  ui_story_5088_50880502_42_dialog_content = "Não posso dizer que entendo muito do que você está dizendo.",
  ui_story_5088_50880502_43_dialog_content = "Mas parece que você leva uma vida muito importante... E solitária, nisso.",
  ui_story_5088_50880502_44_dialog_content = "Seu clã foi encarregado de sua missão há muito tempo, certo? É impressionante que você tenha permanecido fiel a ela depois de todos esses anos.",
  ui_story_5088_50880502_45_dialog_content = "E isso só pode ser o resultado de uma fé e determinação inabaláveis.",
  ui_story_5088_50880502_46_dialog_content = "Algo me diz que seu ancestral, aquele que fez aquele voto, sentiu um incrível senso de amor e compaixão pelos que jurou proteger.",
  ui_story_5088_50880502_47_dialog_content = "O que me faz supor que eles não querem que você seja tão passivo sobre sua missão.",
  ui_story_5088_50880502_48_dialog_content = "Hã?",
  ui_story_5088_50880502_49_dialog_content = "Se você tomar uma atitude para ajudar aqueles que jurou proteger, acredito que isso cumpriria melhor os desejos de seus ancestrais. Você não concorda?",
  ui_story_5088_50880502_50_dialog_content = "Além disso, nos nossos dois anos de combate ao crime juntos, nunca te conheci para ser muito passivo sobre qualquer coisa.",
  ui_story_5088_50880502_51_dialog_content = "Esperando que alguém mais te salve como uma donzela em perigo... Isso não é nada parecido com você.",
  ui_story_5088_50880502_52_dialog_content = "Acho que ainda há muito que você pode fazer para cumprir sua missão.",
  ui_story_5088_50880502_53_dialog_content = "Você não precisa quebrar seu juramento, mas com alguns empurrões na direção certa... Você pode ser capaz de realizar os objetivos do seu antepassado.",
  ui_story_5088_50880502_54_dialog_content = "Você acha mesmo?",
  ui_story_5088_50880502_55_dialog_content = "Claro que eu faço!",
  ui_story_5088_50880502_56_dialog_content = "... Agradeço.",
  ui_story_5088_50880502_57_dialog_content = "Você está absolutamente certo. Meus ancestrais não conseguiram chegar ao dia profetizado, mas eu estou...",
  ui_story_5088_50880502_58_dialog_content = "No mínimo, eu deveria tentar fazer algo.",
  ui_story_5088_50880502_59_dialog_content = "Mas você já sabia disso, não é?",
  ui_story_5088_50880502_60_dialog_content = "... Sim. É só que eu sempre tive medo de piorar as coisas.",
  ui_story_5088_50880502_61_dialog_content = "Mas eu odeio ficar parado enquanto eles ainda precisam da minha ajuda.",
  ui_story_5088_50880502_62_dialog_content = "Quando se trata de profecias, sempre tem que haver alguém para torná-las realidade.",
  ui_story_5088_50880502_63_dialog_content = "É por isso que você não pode confiar em outras pessoas para fazer as coisas acontecerem. Você tem que fazer isso sozinho.",
  ui_story_5088_50880502_64_dialog_content = "Esse é um dos princípios básicos de ser um ídolo... Er, quero dizer, um herói!",
  ui_story_5088_50880502_65_dialog_content = "Obrigado, Goldie.",
  ui_story_5088_50880502_66_dialog_content = "Vou encontrar uma maneira de ajudá-los sem quebrar meu voto.",
  ui_story_5088_50880502_67_dialog_content = "Não é nada demais... Espera, você sabe quem eu sou?!?",
  ui_story_5088_50880502_68_dialog_content = "E-Ei, volte aqui! Você tem algumas explicações para dar!",
  ui_story_5088_50880502_69_dialog_content = "Não é justo se eu não puder conhecer sua identidade também! Volte!",
  ui_story_5088_50880601_1_dialog_content = "(Casta me trouxe outro emblema. Assim como o outro, não reconheço o design gravado nele.)",
  ui_story_5088_50880601_2_dialog_content = "(São estas... notas musicais?)",
  ui_story_5088_50880601_3_dialog_content = "Só para que você saiba, se notarmos algo errado com você, vamos pará-lo imediatamente.",
  ui_story_5088_50880601_4_dialog_content = "Essa é a nossa condição.",
  ui_story_5088_50880601_5_dialog_content = "Não se preocupe, eu não vou me esforçar demais.",
  ui_story_5088_50880601_6_dialog_content = "... Farei algo especial para você experimentar quando voltar do nosso tempo.",
  ui_story_5088_50880601_7_dialog_content = "Tente não se perder no sonho.",
  ui_story_5088_50880601_8_dialog_content = "... Quanto tempo passou desde então? Czerny conseguiu retornar em segurança para Eraveil?",
  ui_story_5088_50880601_9_dialog_content = "Rezo pela sua paz e espero que ele esqueça de nós um dia e viva uma vida longa e feliz.",
  ui_story_5088_50880601_10_dialog_content = "Me desculpe, Ludweiss, mas você vai ter que esperar conosco por mais um pouco...",
  ui_story_5088_50880601_11_dialog_content = "Não consigo mais acompanhar o tempo. Tantas coisas estão começando a se misturar.",
  ui_story_5088_50880601_12_dialog_content = "Acho que estou quase no meu limite... Preciso escrever um último aviso para os descendentes do clã Longinus...",
  ui_story_5088_50880601_13_dialog_content = "\"Mantenha-se longe das profundezas da caverna.\"",
  ui_story_5088_50880601_14_dialog_content = "Urgh... Até fazer algo tão simples como isso me deixa completamente exausto...",
  ui_story_5088_50880601_15_dialog_content = "Eu deveria ter sido completamente corrompido até agora, mas eles ainda não pararam.",
  ui_story_5088_50880601_16_dialog_content = "Por quanto tempo mais posso manter o controle? Será que... realmente está além de mim agora?",
  ui_story_5088_50880601_17_dialog_content = "Você mentiu para mim, Ludweiss.",
  ui_story_5088_50880601_18_dialog_content = "Não... O que acabou de acontecer?! Como eu poderia culpar Ludweiss por isso?",
  ui_story_5088_50880601_19_dialog_content = "Meus amigos... eu também falhei com vocês...",
  ui_story_5088_50880601_20_dialog_content = "É realmente impossível usar minhas memórias para resistir ao passar do tempo?",
  ui_story_5088_50880601_21_dialog_content = "Por favor... Me ajude...",
  ui_story_5088_50880601_22_dialog_content = "<color=#e8d9bb>O ar se enche de aplausos altos e animados—</color>",
  ui_story_5088_50880601_23_dialog_content = "...?",
  ui_story_5088_50880601_24_dialog_content = "Louvor aos Guerreiros Estelares, os heróis que erradicaram os Eclipsitas!",
  ui_story_5088_50880601_25_dialog_content = "Como seu rei, é uma honra distinta apresentar-lhe esses prêmios.",
  ui_story_5088_50880601_26_dialog_content = "Heróis! Heróis! Heróis! Heróis!",
  ui_story_5088_50880601_27_dialog_content = "Ah... O momento de nossa maior glória...",
  ui_story_5088_50880601_28_dialog_content = "Faça seus votos perante os deuses e receba a honra que você tão justamente conquistou.",
  ui_story_5088_50880601_29_dialog_content = "Avance.",
  ui_story_5088_50880601_30_dialog_content = "Enquanto houver uma única pessoa justa neste mundo, estarei sempre pronto para sacrificar minha vida por ela.",
  ui_story_5088_50880601_31_dialog_content = "Você é o nobre escudo do reino, firme e disposto a defender os fracos e inocentes. Com os deuses como minhas testemunhas, eu concedo a você o título de \"Regal\"!",
  ui_story_5088_50880601_32_dialog_content = "Juro me tornar um rio de fogo castigador, e purgar o mundo da maldade com minhas chamas.",
  ui_story_5088_50880601_33_dialog_content = "Suas chamas queimam mais brilhantes enquanto você lidera a carga na batalha. Com os deuses como minhas testemunhas, eu concedo a você o título de \"Frostfire\"!",
  ui_story_5088_50880601_34_dialog_content = "Juro preservar a esperança e me tornar a luz que guia os sofredores e desesperados!",
  ui_story_5088_50880601_35_dialog_content = "Com sua brilhante lança, você despedaça a escuridão e anuncia o amanhecer que se aproxima. Com os deuses como minhas testemunhas, eu concedo a você o título de \"Requiem\"!",
  ui_story_5088_50880601_36_dialog_content = "Juro proteger cada único momento de paz e me agarrar ao meu cajado mesmo que meu corpo pereça.",
  ui_story_5088_50880601_37_dialog_content = "Sua luz silenciosa acalma o tumulto de nosso mundo em nome da paz. Com os deuses como minhas testemunhas, eu lhe concedo o título de \"Mythos\"!",
  ui_story_5088_50880601_38_dialog_content = "Uhul-!!!",
  ui_story_5088_50880601_39_dialog_content = "É a sua vez agora, Capitão.",
  ui_story_5088_50880601_40_dialog_content = "Avance e faça seu voto, Aquiles.",
  ui_story_5088_50880601_41_dialog_content = "May os deuses testemunham meu juramento! Pelo bem dos meus entes queridos, juro sacrificar tudo até que o tempo me reduza a pó!",
  ui_story_5088_50880601_42_dialog_content = "Eu não tenho arrependimentos—",
  ui_story_5088_50880601_43_dialog_content = "Ah... Foi apenas um sonho... Um raro e agradável, não menos.",
  ui_story_5088_50880601_44_dialog_content = "Alguma vez vou conseguir ver como essas pessoas vivem suas vidas pacíficas? O reino ainda precisa que outros se sacrifiquem por ele?",
  ui_story_5088_50880601_45_dialog_content = "<color=#e8d9bb>Rachadura-</color>",
  ui_story_5088_50880601_46_dialog_content = "?",
  ui_story_5088_50880601_47_dialog_content = "Tem alguém aí...?",
  ui_story_5088_50880601_48_dialog_content = "Hã? Argh, não de novo! Como poderia cortar bem ali?!",
  ui_story_5088_50880601_49_dialog_content = "Tudo bem PlayerName, isso é o suficiente por hoje. Você fez um bom trabalho, agora venha e coma conosco!",
  ui_story_5088_50880601_50_dialog_content = "Ele pode não parecer, mas Adras é um cozinheiro bastante decente!",
  ui_story_5088_50880601_51_dialog_content = "Eu tenho que ser se eu quiser alimentar essas crianças adequadamente... Hmm?",
  ui_story_5088_50880601_52_dialog_content = "Eu...",
  ui_story_5088_50880601_53_dialog_content = "Não se esforce demais. Tudo bem se você não consegue se lembrar por agora.",
  ui_story_5088_50880601_54_dialog_content = "...",
  ui_story_5088_50880601_55_dialog_content = "Vamos, Adras, vamos comer.",
  ui_story_5088_50880601_56_dialog_content = "Claro.",
  ui_story_5088_50880601_57_dialog_content = "Você é o maior, Adras! Ah, eu estive morrendo de vontade de comer isso pelos últimos dois mil anos!",
  ui_story_5088_50880601_58_dialog_content = "Eh? Quem está aí?!",
  ui_story_5088_50880601_59_dialog_content = "Pare aí! Este lugar pertence aos Blue Wolverines.",
  ui_story_5088_50880601_60_dialog_content = "Estou bem ciente disso!",
  ui_story_5088_50880601_61_dialog_content = "Meu clã deixou algo em sua posse. Estou aqui para pegá-lo de volta.",
  ui_story_5088_50880601_62_dialog_content = "Hã?",
  ui_story_5088_50880601_63_dialog_content = "Desapareça!",
  ui_story_5088_50880601_64_dialog_content = "Então acho que terei que te mostrar.",
  ui_story_5088_50880601_65_dialog_content = "Testemunhe-me—Pois eu sou a morte.",
  ui_story_5088_50880602_1_dialog_content = "Uau, você realmente chegou cedo!",
  ui_story_5088_50880602_2_dialog_content = "A Senhora Jeriah me pediu para entregar isso pessoalmente a você. Deve ser muito urgente.",
  ui_story_5088_50880602_3_dialog_content = "Até a próxima.",
  ui_story_5088_50880602_4_dialog_content = "Uh... Senhorita Mithra?",
  ui_story_5088_50880602_5_dialog_content = "Sim?",
  ui_story_5088_50880602_6_dialog_content = "Tenho certeza de que este diário é realmente importante, mas... Não preciso usar meus poderes nele para saber que pertencia ao clã Longinus.",
  ui_story_5088_50880602_7_dialog_content = "Já estou familiarizado com a frequência deles.",
  ui_story_5088_50880602_8_dialog_content = "...",
  ui_story_5088_50880602_9_dialog_content = "Como Celestita, discernir diferentes pessoas é algo que vem naturalmente para mim.",
  ui_story_5088_50880602_10_dialog_content = "Não sinto Jeriah neste diário de forma alguma, mas sinto uma presença muito familiar nele... A sua.",
  ui_story_5088_50880602_11_dialog_content = "... Eu não tinha certeza naquele dia, já que só tínhamos nos encontrado uma vez antes.",
  ui_story_5088_50880602_12_dialog_content = "Mas quando você apareceu com Tweety no dia seguinte, eu sabia que era você.",
  ui_story_5088_50880602_13_dialog_content = "...",
  ui_story_5088_50880602_14_dialog_content = "Independentemente das circunstâncias, você me salvou e sou grato por isso. Deve haver um motivo para manter sua identidade oculta, certo?",
  ui_story_5088_50880602_15_dialog_content = "Quanto a este caderno... Por que você usaria o nome da Senhora Jeriah para trazê-lo até mim?",
  ui_story_5088_50880602_16_dialog_content = "Não é... importante para a sua família?",
  ui_story_5088_50880602_17_dialog_content = "Tudo bem, vamos fazer uma rápida contagem—Com um levantar de mãos, quantos de nós somos ingratos idiotas? Vá em frente, levante suas mãos.",
  ui_story_5088_50880602_18_dialog_content = "...",
  ui_story_5088_50880602_19_dialog_content = "Bom! Parece que nenhum de nós é um ingrato egoísta.",
  ui_story_5088_50880602_20_dialog_content = "Agora, vamos convidar Cynthia para dizer algumas palavras!",
  ui_story_5088_50880602_21_dialog_content = "... Vamos lá.",
  ui_story_5088_50880602_22_dialog_content = "Como esperado de um Celestita.",
  ui_story_5088_50880602_23_dialog_content = "Neste ponto, você pode saber até mais do que eu. Parece que não há mais razão para manter essa farsa...",
  ui_story_5088_50880602_24_dialog_content = "É exatamente como você disse. Meu nome é Mithra Longinus.",
  ui_story_5088_50880602_25_dialog_content = "Minha família, o Clã Longinus, esperou pacientemente pela chegada de um Celestita profetizado por mais de dois mil anos.",
  ui_story_5088_50880602_26_dialog_content = "Dois mil anos...?",
  ui_story_5088_50880602_27_dialog_content = "Heheh, duvido que até a Senhora Ludweiss soubesse que sua profecia levaria tanto tempo.",
  ui_story_5088_50880602_28_dialog_content = "Por eras, nosso clã observou as mudanças do mundo das sombras.",
  ui_story_5088_50880602_29_dialog_content = "Mesmo após todos esses anos, nunca esquecemos nosso propósito: impedir que alguém descubra os segredos das estrelas.",
  ui_story_5088_50880602_30_dialog_content = "E ainda assim, você nunca tentou me impedir de investigar. É porque eu sou um Celestita?",
  ui_story_5088_50880602_31_dialog_content = "Correto. E não só isso, você é o Celestita da profecia da Senhora Ludweiss.",
  ui_story_5088_50880602_32_dialog_content = "Nossa tribo sempre permitiu que os Celestitas investigassem nosso segredo por séculos, mas nunca pedimos explicitamente a ajuda deles. Tenho certeza que você sabe o motivo por que—",
  ui_story_5088_50880602_33_dialog_content = "O Lord Aquiles não pode ser selado, mas sua corrupção também não pode ser revertida.",
  ui_story_5088_50880602_34_dialog_content = "Seu corpo está infundido com o poder da escuridão. Os Caelestites comuns, limitados por suas algemas inatas, nunca poderiam esperar controlar esse tipo de poder.",
  ui_story_5088_50880602_35_dialog_content = "Tentar sentir sua mente faria você perder a sua própria no melhor dos casos, mas no pior... O contra-ataque dos sussurros da estrela caída poderia matá-lo.",
  ui_story_5088_50880602_36_dialog_content = "... Os Celestitas em Eraveil são incomparáveis em sua bondade e compaixão. Por causa disso, pedir ajuda a eles seria o mesmo que colocar suas vidas em risco.",
  ui_story_5088_50880602_37_dialog_content = "As chances de salvação deles são escassas, e o Senhor Aquiles se recusa a deixar que mais pessoas se sacrifiquem por eles.",
  ui_story_5088_50880602_38_dialog_content = "Então você guardou tudo isso para si em vez de contar aos Celestitas?",
  ui_story_5088_50880602_39_dialog_content = "... Há mais razões do que essa, mas sim. No final, decidimos que esperar em silêncio era a melhor escolha.",
  ui_story_5088_50880602_40_dialog_content = "Antes da Senhora Ludweiss falecer, ela afirmou ter visto um Celestita de milhares de anos no futuro.",
  ui_story_5088_50880602_41_dialog_content = "E ao lado daquele Celestita estava o Senhor Adras, que havia sido libertado de seu selo.",
  ui_story_5088_50880602_42_dialog_content = "Desde então, estamos pacientemente aguardando a realização desta profecia.",
  ui_story_5088_50880602_43_dialog_content = "Mas mesmo após dois milênios e a revolução de todo o nosso mundo... O dia que estamos esperando ainda não chegou.",
  ui_story_5088_50880602_44_dialog_content = "... E agora eu sou o único Celestita restante no mundo. Nos últimos dezessete anos ou mais, o mundo pensou que nosso povo havia sido completamente exterminado... Mas então eu apareci.",
  ui_story_5088_50880602_45_dialog_content = "Mas mesmo depois disso, sua família ainda permaneceu forte e esperou.",
  ui_story_5088_50880602_46_dialog_content = "Eu... Não há nada de forte em mim. Na verdade, meu coração ainda está cheio de dúvidas...",
  ui_story_5088_50880602_47_dialog_content = "Não acredito que este suposto \"salvador\" seja o único que pode nos libertar e ao Senhor Aquiles do nosso destino.",
  ui_story_5088_50880602_48_dialog_content = "Através dos meus esforços, acabei percebendo que meus ancestrais sentiam da mesma maneira que eu e que enfrentamos obstáculos semelhantes em nossas vidas.",
  ui_story_5088_50880602_49_dialog_content = "Sem um Caelestite, até mesmo quebrar o selo dos Guerreiros Estelares se tornaria impossível.",
  ui_story_5088_50880602_50_dialog_content = "Mas ainda assim, deve haver algo que eu possa fazer...",
  ui_story_5088_50880602_51_dialog_content = "Então é por isso que você trouxe isso para mim...",
  ui_story_5088_50880602_52_dialog_content = "Esse diário contém os desejos e experiências mais profundos de Longinus ao longo das eras.",
  ui_story_5088_50880602_53_dialog_content = "Como um celestita, você deve ser capaz de obter muita orientação dele.",
  ui_story_5088_50880602_54_dialog_content = "Fazer isso também não é uma violação do meu voto.",
  ui_story_5088_50880602_55_dialog_content = "Obrigado. Vou cuidar bem disso e aprender o máximo que puder.",
  ui_story_5088_50880602_56_dialog_content = "Eles estão contando com você... E eu também.",
  ui_story_5088_50880602_57_dialog_content = "(Parece que ela acredita que ainda há uma chance de salvar Aquiles...)",
  ui_story_5088_50880602_58_dialog_content = "(Não, isso não pode estar certo. Se Aquiles realmente está morto e os outros Guerreiros Estelares foram despertados por mim, então não há motivo para ela se preocupar com isso.)",
  ui_story_5088_50880602_59_dialog_content = "(Mas como ela ainda está cumprindo seus deveres, então isso deve significar... Aquiles pode ainda estar vivo em algum lugar, o que significa que ainda há uma chance...)",
  ui_story_5088_50880602_60_dialog_content = "Eu tenho que voltar para aquela caverna!",
  ui_story_5088_50880602_61_dialog_content = "Nada mal, PlayerName! Como sabia que voltaríamos àquele lugar?",
  ui_story_5088_50880602_62_dialog_content = "Huh? O que vocês estão fazendo?",
  ui_story_5088_50880602_63_dialog_content = "Nunca fomos pessoas ingratas.",
  ui_story_5088_50880602_64_dialog_content = "Alguém usou suas emoções poderosas para nos selar.",
  ui_story_5088_50880602_65_dialog_content = "E queremos saber quem era essa pessoa.",
  ui_story_5088_50880602_66_dialog_content = "Isso mesmo, e também queremos saber exatamente o que ele fez conosco.",
  ui_story_5088_50880602_67_dialog_content = "Se fosse apenas um simples ato de traição, não havia necessidade de selar nossas emoções também.",
  ui_story_5088_50880602_68_dialog_content = "Mas... Fomos nós que o matamos... Se você aprender a história por trás disso...",
  ui_story_5088_50880602_69_dialog_content = "Ele foi quem me ensinou que minhas chamas podem ser usadas para ajudar as pessoas.",
  ui_story_5088_50880602_70_dialog_content = "Ele impediu os Eclipsitas de destruir minha floresta e me mostrou como usar meus poderes para proteger este mundo.",
  ui_story_5088_50880602_71_dialog_content = "Ele me ajudou a derrotar aqueles que me prejudicaram e me deu um motivo para continuar vivendo.",
  ui_story_5088_50880602_72_dialog_content = "Heheh, ele me tirou da escuridão e me deu um novo objetivo na vida.",
  ui_story_5088_50880602_73_dialog_content = "Vocês...",
  ui_story_5088_50880602_74_dialog_content = "Então, pelo que nos diz respeito, aquele cara não é Claymore ou algum monstro. O nome dele é Aquiles.",
  ui_story_5088_50880602_75_dialog_content = "Não podemos deixar você fazer isso sozinho, e certamente não podemos fingir que ele é mal e encerrar o dia.",
  ui_story_5088_50880602_76_dialog_content = "Mesmo que eu me lembre dele agora... Eu ainda não consigo deixar de sentir raiva...",
  ui_story_5088_50880602_77_dialog_content = "Mas ainda precisamos saber a verdade.",
  ui_story_5088_50880602_78_dialog_content = "Esses sentimentos são reais. Temos certeza disso.",
  ui_story_5088_50880602_79_dialog_content = "Heh, devemos ter realmente odiado ele antes, já que queríamos nos matar assim que cruzamos os olhares.",
  ui_story_5088_50880602_80_dialog_content = "Verdade... Às vezes fazemos parecer trivial, mas a verdade é que ele nos atravessou com sua espada sem dizer uma palavra.",
  ui_story_5088_50880602_81_dialog_content = "Ele era mais forte do que todos nós, e tentou nos matar sem dizer nada... Lutar contra ele era inevitável.",
  ui_story_5088_50880602_82_dialog_content = "Mas lembre-se, nosso motivo para ir lá é descobrir a verdade e confirmar se ele ainda está vivo ou não. A única diferença agora é que nossas mentes estão mais calmas e claras do que antes.",
  ui_story_5088_50880602_83_dialog_content = "... Esses são nossos pensamentos sobre o assunto, PlayerName.",
  ui_story_5088_50880602_84_dialog_content = "Não importa quão doloroso ou cruel possa ser, ainda queremos saber a verdade.",
  ui_story_5088_50880602_85_dialog_content = "Pelos nossos momentos, e pela sua honra.",
  ui_story_5088_50880602_86_dialog_content = "Não podemos simplesmente esquecer de tudo assim.",
  ui_story_5088_50880602_87_dialog_content = "E por causa de nossos corpos imortais, ainda há esperança...",
  ui_story_5088_50880602_88_dialog_content = "Mesmo que haja apenas uma pequena chance de salvá-lo...",
  ui_story_5088_50880602_89_dialog_content = "Faremos tudo o que pudermos para que isso aconteça, mesmo que ele realmente nos tenha traído no passado.",
  ui_story_5088_50880602_90_dialog_content = "Então vamos todos juntos!",
  ui_story_5088_50880602_91_dialog_content = "...",
  ui_story_5088_50880602_92_dialog_content = "Vamos!",
  ui_story_5088_50880701_1_dialog_content = "<color=#e8d9bb>De acordo com o caderno, o Clã Longinus finalmente conseguiu descobrir o paradeiro de Czerny.</color>",
  ui_story_5088_50880701_2_dialog_content = "<color=#e8d9bb>Depois de retornar a Eraveil, ele não mencionou os Guerreiros Estelares para ninguém.</color>",
  ui_story_5088_50880701_3_dialog_content = "<color=#e8d9bb>Os pais de Czerny, aliviados por seu filho finalmente ter voltado para casa, o receberam de braços abertos, e retomaram suas vidas felizes juntos.</color>",
  ui_story_5088_50880701_4_dialog_content = "<color=#e8d9bb>Mas até então, a arrogância que definia a personalidade de Czerny havia sido substituída por uma atitude calma e gentil.</color>",
  ui_story_5088_50880701_5_dialog_content = "<color=#e8d9bb>Ele nunca participou de outra competição, e em vez disso, dedicou seus esforços para ensinar música.</color>",
  ui_story_5088_50880701_6_dialog_content = "<color=#e8d9bb>Suas obras mais famosas eram tanto trágicas quanto solenes, e logo se tornaram as melodias características do feriado Celestita de Windelion.</color>",
  ui_story_5088_50880701_7_dialog_content = "<color=#e8d9bb>Mais tarde em sua vida, ele ergueu uma lápide sem nome no lugar onde todos os Celestitas foram colocados para descansar. Todos os anos no Windelion, ele visitava a lápide e prestava seus respeitos.</color>",
  ui_story_5088_50880701_8_dialog_content = "<color=#e8d9bb>A maioria das pessoas não tinha ideia de quem ele estava lamentando. Por respeito a este professor de música, ninguém ousou perguntar ou mesmo especular quem poderia ser.</color>",
  ui_story_5088_50880701_9_dialog_content = "<color=#e8d9bb>Deixado sozinho após a morte de seus pais, Czerny se dedicou à adoção e educação dos órfãos de Eraveil, filhos e filhas daqueles que haviam sido exilados. Com o tempo, ele se tornou um dos professores mais reverenciados e amados de Eraveil.</color>",
  ui_story_5088_50880701_10_dialog_content = "Graças ao mapa de Queen Bethlehem, conseguimos retornar a este lugar bastante rapidamente.",
  ui_story_5088_50880701_11_dialog_content = "Eu me pergunto qual é a conexão dela com tudo isso... Ela não me contou quando eu perguntei...",
  ui_story_5088_50880701_12_dialog_content = "Ei Freya, acabei de lembrar de algo! Esse nome, \"Bethlehem\"... Não tinha alguém na sua família com...",
  ui_story_5088_50880701_13_dialog_content = "Uau! Alguém saiu da caverna por aqui? Por que nunca notamos essa abertura antes?",
  ui_story_5088_50880701_14_dialog_content = "Tudo aqui está congelado sólido, sem esperança de descongelar...",
  ui_story_5088_50880701_15_dialog_content = "...",
  ui_story_5088_50880701_16_dialog_content = "?",
  ui_story_5088_50880701_17_dialog_content = "Ninguém mais está na caverna, mas também não sinto a presença dele.",
  ui_story_5088_50880701_18_dialog_content = "... Isso significa que realmente o matamos da última vez?",
  ui_story_5088_50880701_19_dialog_content = "Não sejamos precipitados. Encontrei alguns pergaminhos esfarrapados na outra entrada da caverna.",
  ui_story_5088_50880701_20_dialog_content = "Isso deveria ter sido a única entrada ou saída, o que significa que essa abertura deve ter sido feita posteriormente.",
  ui_story_5088_50880701_21_dialog_content = "Será que ele conseguiu quebrar as paredes da caverna daqui e escapou?",
  ui_story_5088_50880701_22_dialog_content = "A formação mágica estava segurando ele no lugar, não nós. Deveria ter sido impossível para ele deixar este lugar.",
  ui_story_5088_50880701_23_dialog_content = "Então talvez ele estivesse de muito mau humor um dia, então descontou na parede da caverna e deixou este buraco gigante!",
  ui_story_5088_50880701_24_dialog_content = "Apenas deixe-me tentar sentir esses fragmentos de pergaminho primeiro.",
  ui_story_5088_50880701_25_dialog_content = "Tudo bem, mas só porque eu posso te curar com minha magia não significa que você pode se esforçar demais. Entendeu?",
  ui_story_5088_50880701_26_dialog_content = "Eu sei.",
  ui_story_5088_50880701_27_option_content = "Varredura Psíquica",
  ui_story_5088_50880701_28_dialog_content = "Quando a escuridão passa, as pessoas não precisam mais das estrelas para guiar seu caminho.",
  ui_story_5088_50880701_29_dialog_content = "Eles não são mais soldados daquele reino.",
  ui_story_5088_50880701_30_dialog_content = "Sétimo dia: May Você viva livre de agora em diante.",
  ui_story_5088_50880701_31_dialog_content = "Quem está aí? Fique fora desta caverna!",
  ui_story_5088_50880701_32_dialog_content = "<color=#e8d9bb>Pat, pat, pat—</color>",
  ui_story_5088_50880701_33_dialog_content = "<color=#e8d9bb>Uma jovem Celestita limpa o pó da lápide sem nome e coloca flores frescas diante dela.</color>",
  ui_story_5088_50880701_34_dialog_content = "...",
  ui_story_5088_50880701_35_dialog_content = "Mestre Czerny, limpei a Senhora Ludweiss novamente, exatamente como você pediu.",
  ui_story_5088_50880701_36_dialog_content = "Muito bem, pequenino. Obrigado.",
  ui_story_5088_50880701_37_dialog_content = "Mas... May Eu pergunto por que você ainda parece tão triste, Mestre?",
  ui_story_5088_50880701_38_dialog_content = "Todos dizem que Windelion é um dia para lembrar dos queridos que partiram e oferecer a eles nossos pensamentos e orações.",
  ui_story_5088_50880701_39_dialog_content = "Então, temos que ser fortes e mostrar a eles que estamos felizes.",
  ui_story_5088_50880701_40_dialog_content = "...",
  ui_story_5088_50880701_41_dialog_content = "Isso é o que você nos ensinou, Mestre Czerny...",
  ui_story_5088_50880701_42_dialog_content = "Mas a cada Windelion, você parece estar em tanta dor.",
  ui_story_5088_50880701_43_dialog_content = "Lamento, pequenino... Mas aqueles por quem eu luto nunca ouvirão meus pensamentos. O destino cuidou disso.",
  ui_story_5088_50880701_44_dialog_content = "Você é uma alma bondosa. Apesar de sua pouca idade, você já consegue sentir a dor no coração das outras pessoas.",
  ui_story_5088_50880701_45_dialog_content = "Mas você deve saber que os bondosos sempre sofrem mais do que qualquer outra pessoa.",
  ui_story_5088_50880701_46_dialog_content = "Você me acolheu e me criou, Mestre Czerny. É por isso que eu quero ser exatamente como você.",
  ui_story_5088_50880701_47_dialog_content = "Além disso, você não se sentirá tão mal se eu puder ajudá-lo, certo?",
  ui_story_5088_50880701_48_dialog_content = "?!",
  ui_story_5088_50880701_49_dialog_content = "Se eu tentar um pouco mais, então talvez você consiga viver mais feliz algum dia...",
  ui_story_5088_50880701_50_dialog_content = "E quando esse dia chegar... Talvez você finalmente consiga dizer adeus à Senhora Ludweiss no Windelion. Certo, Mestre Czerny?",
  ui_story_5088_50880701_51_dialog_content = "Ah...",
  ui_story_5088_50880701_52_dialog_content = "<color=#e8d9bb>À medida que a canção lamentosa de Windelion começa a tocar, Czerny cai de joelhos em dor.</color>",
  ui_story_5088_50880701_53_dialog_content = "Por que você está chorando, Mestre Czerny?",
  ui_story_5088_50880701_54_dialog_content = "Eu disse algo errado? Me desculpe... Por favor, não chore.",
  ui_story_5088_50880701_55_dialog_content = "Eu... O que eu estive fazendo todo esse tempo...?",
  ui_story_5088_50880701_56_dialog_content = "O que há de errado, Mestre Czerny? Você não fez nada de errado—todos te amam!",
  ui_story_5088_50880701_57_dialog_content = "A música que você toca para nós é simplesmente maravilhosa, e suas aulas são tão interessantes...",
  ui_story_5088_50880701_58_dialog_content = "Por favor, não chore mais...",
  ui_story_5088_50880701_59_dialog_content = "Neste ponto, ainda posso encarar todos vocês com um coração aberto? A sinfonia que eu dei a vocês...",
  ui_story_5088_50880701_60_dialog_content = "Quem está aí? Ninguém tem permissão para entrar na caverna!",
  ui_story_5088_50880701_61_dialog_content = "Uau... a estrela que todos nós vivemos para servir. Você é real...",
  ui_story_5088_50880701_62_dialog_content = "Longinus...?",
  ui_story_5088_50880701_63_dialog_content = "Levante-se, agora. Por que você parece tão... para baixo?",
  ui_story_5088_50880701_64_dialog_content = "Aconteceu algo terrível com você?",
  ui_story_5088_50880701_65_dialog_content = "Lumópolis está em um estado de grande tumulto, e nossa família foi implicada em meio ao caos.",
  ui_story_5088_50880701_66_dialog_content = "Agora, nos tornamos nada mais do que as sombrias sombras da Baixa Lumópolis.",
  ui_story_5088_50880701_67_dialog_content = "Nossa família enfrenta uma turbulência sem precedentes e muitos perderam a fé.",
  ui_story_5088_50880701_68_dialog_content = "Como o novo chefe da família, eu... devo carregar o peso do nosso futuro.",
  ui_story_5088_50880701_69_dialog_content = "Você precisa de alguma ajuda?",
  ui_story_5088_50880701_70_dialog_content = "Não, eu não preciso de nada, meu senhor.",
  ui_story_5088_50880701_71_dialog_content = "Nesta noite mais escura, desejo apenas prestar meus respeitos...",
  ui_story_5088_50880701_72_dialog_content = "Por seu comando, duas gerações de chefes de família vieram e se foram sem serem agraciados com sua presença. É por isso que muitos acreditam que você é apenas uma lenda de nossa linhagem.",
  ui_story_5088_50880701_73_dialog_content = "Especialmente em tempos tão sombrios, ninguém acredita na grandeza que já servimos... Eles começaram a perder a esperança.",
  ui_story_5088_50880701_74_dialog_content = "Até eu... sinto uma vergonhosa dúvida no meu coração.",
  ui_story_5088_50880701_75_dialog_content = "Pelo bem do clã, você deveria desistir. Eu não vou te culpar.",
  ui_story_5088_50880701_76_dialog_content = "Mas agora, eu vi você.",
  ui_story_5088_50880701_77_dialog_content = "Vou acabar com todas as disputas. A sombra sobre Longinus não está sem uma estrela guia.",
  ui_story_5088_50880701_78_dialog_content = "Você...",
  ui_story_5088_50880701_79_dialog_content = "Retornarei a Lumópolis, liderando meus parentes nas sombras, continuando a desafiar esse destino insondável.",
  ui_story_5088_50880701_80_dialog_content = "... Quem é você para o Dominic?",
  ui_story_5088_50880701_81_dialog_content = "Czerny?",
  ui_story_5088_50880701_82_dialog_content = "O Guerreiro Estelar reconhece você... Você é o Celestita que uma vez nos deu uma mão? Dominic é meu tio.",
  ui_story_5088_50880701_83_dialog_content = "Dei uma mão? Eu?",
  ui_story_5088_50880701_84_dialog_content = "Hahahaha!",
  ui_story_5088_50880701_85_dialog_content = "Em que tolice estive envolvido? Claramente, eu sou o Celestita, aquele que ajudaria Aquiles, mas não consegui realizar nada.",
  ui_story_5088_50880701_86_dialog_content = "Por que você voltou...?",
  ui_story_5088_50880701_87_dialog_content = "Eu queria te visitar, Aquiles.",
  ui_story_5088_50880701_88_dialog_content = "Não posso soltar, nem posso encarar a verdade.",
  ui_story_5088_50880701_89_dialog_content = "Mas quando ouvi tudo isso na entrada da caverna... Eu... não pude deixar de ser tocado pela convicção deste.",
  ui_story_5088_50880701_90_dialog_content = "Devo continuar cuidando deste assunto inacabado.",
  ui_story_5088_50880702_1_dialog_content = "<color=#e8d9bb>Se vocês virem isso, pessoas do futuro, por favor, testemunhem meu registro final.</color>",
  ui_story_5088_50880702_2_dialog_content = "<color=#e8d9bb>Devido à piora da condição de Aquiles, devo me distanciar um pouco e continuar o trabalho dos anos passados.</color>",
  ui_story_5088_50880702_3_dialog_content = "<color=#e8d9bb>Agora estou mais calmo, calmo o suficiente para deixar essa informação de forma sistemática.</color>",
  ui_story_5088_50880702_4_dialog_content = "<color=#e8d9bb>Depois desta página, deveriam haver quatrocentas e quarenta e três páginas de registros de pesquisa.</color>",
  ui_story_5088_50880702_5_dialog_content = "<color=#e8d9bb>Mas mesmo com todos esses pergaminhos, acabei de começar a fazer progresso.</color>",
  ui_story_5088_50880702_6_dialog_content = "<color=#e8d9bb>Infelizmente, agora estou sem tempo...</color>",
  ui_story_5088_50880702_7_dialog_content = "Tosse, tosse... Tosse, tosse, tosse...",
  ui_story_5088_50880702_8_dialog_content = "Você tem tossido mais do que o normal ultimamente.",
  ui_story_5088_50880702_9_dialog_content = "Está muito frio aqui. Você deveria sair e ir a um médico.",
  ui_story_5088_50880702_10_dialog_content = "Isso não é uma doença, Aquiles. Isso é... tosse, tosse... velhice.",
  ui_story_5088_50880702_11_dialog_content = "...",
  ui_story_5088_50880702_12_dialog_content = "O tempo é verdadeiramente impiedoso.",
  ui_story_5088_50880702_13_dialog_content = "Eu pensei que tinha tanto tempo restante...",
  ui_story_5088_50880702_14_dialog_content = "Nesta idade, eu invejo todos vocês. Se ao menos eu pudesse viver para sempre...",
  ui_story_5088_50880702_15_dialog_content = "...",
  ui_story_5088_50880702_16_dialog_content = "Aquiles, ainda tá acordado?",
  ui_story_5088_50880702_17_dialog_content = "... Sim.",
  ui_story_5088_50880702_18_dialog_content = "Se eu ouvir o monstro no meu coração se aproximando, vou rugir para ele instantaneamente, Czerny.",
  ui_story_5088_50880702_19_dialog_content = "Eu estava apenas refletindo.",
  ui_story_5088_50880702_20_dialog_content = "Eu posso ser tão impotente quanto você, e meu cérebro está desacelerando. Se eu não der tudo de mim, bem, eu nem consigo pensar.",
  ui_story_5088_50880702_21_dialog_content = "Somos apenas um par de velhos fósseis.",
  ui_story_5088_50880702_22_dialog_content = "Hahaha... É raro ouvir você brincar.",
  ui_story_5088_50880702_23_dialog_content = "Mas não consegui nada, e agora estou velho e morrendo... No final, parece que eu não era o Celestita da profecia.",
  ui_story_5088_50880702_24_dialog_content = "Czerny, você não precisa desesperar. O tempo pode trazer o crepúsculo, mas você rugiu contra ele.",
  ui_story_5088_50880702_25_dialog_content = "Sem você, eu poderia ter desistido há muito tempo.",
  ui_story_5088_50880702_26_dialog_content = "Você quer dizer que, meu breve lampejo te ajudou a resistir à esmagadora escuridão?",
  ui_story_5088_50880702_27_dialog_content = "De fato. Até eu possuo minhas próprias fraquezas. Sem o apoio de um amigo como você, eu não poderia ter permanecido lúcido por tanto tempo.",
  ui_story_5088_50880702_28_dialog_content = "Entendo sua determinação, então não vou mais insistir para você partir. Espero que entenda que já realizou verdadeiros milagres para mim.",
  ui_story_5088_50880702_29_dialog_content = "Você me deu esperança - isso não é suficiente para afastar a escuridão?",
  ui_story_5088_50880702_30_dialog_content = "Esperança...",
  ui_story_5088_50880702_31_dialog_content = "Assim como Ludweiss me deu esperança com a profecia, infundindo-me com a coragem para seguir em frente.",
  ui_story_5088_50880702_32_dialog_content = "Você fez o mesmo.",
  ui_story_5088_50880702_33_dialog_content = "... Ah!",
  ui_story_5088_50880702_34_dialog_content = "Sim... deve ser isso...",
  ui_story_5088_50880702_35_dialog_content = "Todo esse tempo, minha pesquisa estava focada na direção errada!",
  ui_story_5088_50880702_36_dialog_content = "Como assim?",
  ui_story_5088_50880702_37_dialog_content = "Eu estava tão fixado em alcançar um final perfeito que negligenciei o fato de que ainda temos uma maneira de chegar a um compromisso!",
  ui_story_5088_50880702_38_dialog_content = "A coisa mais importante é a sua consciência! Enquanto eu preservar sua consciência, sei que será suficiente!",
  ui_story_5088_50880702_39_dialog_content = "Tenho pesquisado como parar sua erosão e restaurá-lo ao seu antigo eu, mas fui impedido pelo problema do seu poder.",
  ui_story_5088_50880702_40_dialog_content = "Mas a verdade é que não precisamos do seu corpo - só precisamos encontrar uma maneira de preservar sua consciência!",
  ui_story_5088_50880702_41_dialog_content = "O que isso significa?",
  ui_story_5088_50880702_42_dialog_content = "Você, como os outros, passou por extensas modificações, seu corpo preenchido com o poder da escuridão.",
  ui_story_5088_50880702_43_dialog_content = "Eles foram afetados pela erosão até certo ponto, mas após serem selados, essa escuridão foi mantida à distância por suas emoções mais fortes.",
  ui_story_5088_50880702_44_dialog_content = "Seus corpos, embora tenham passado pela transformação Eclipsita, gradualmente se estabilizaram. Com a ajuda da sua formação mágica, aquela erosão de rejeição não acontecerá novamente!",
  ui_story_5088_50880702_45_dialog_content = "Você também! Mesmo que eu não consiga selar você, e se eu puxar sua consciência para fora do seu corpo? Seu corpo pode permanecer na formação mágica!",
  ui_story_5088_50880702_46_dialog_content = "Talvez um dia, seu corpo se adapte à erosão e se estabilize, e aquele poder sombrio não te deixará louco.",
  ui_story_5088_50880702_47_dialog_content = "Você quer dizer que tem um jeito de extrair e preservar minha consciência?",
  ui_story_5088_50880702_48_dialog_content = "Pesquisar isso será mais fácil do que curar você diretamente.",
  ui_story_5088_50880702_49_dialog_content = "A parte mais difícil será encontrar um recipiente que possa conter temporariamente \"você\" sem qualquer forma de rejeição.",
  ui_story_5088_50880702_50_dialog_content = "Hahaha! Isso realmente é um raio de esperança!",
  ui_story_5088_50880702_51_dialog_content = "Aquiles, o que Ludweiss nos deixou não foi uma <color=#FFB400>profecia</color>, mas <color=#FFB400>esperança</color>!",
  ui_story_5088_50880702_52_dialog_content = "<color=#FFB400>Esperança</color>...",
  ui_story_5088_50880702_53_dialog_content = "Caso contrário, por que ela se sacrificaria sabendo que não seria a única a resolver esse problema?",
  ui_story_5088_50880702_54_dialog_content = "Além disso, o método dela não era perfeito.",
  ui_story_5088_50880702_55_dialog_content = "Mas porque ela acreditava no futuro, acreditava na esperança, ela se sacrificou voluntariamente para abrir caminho para aquele que a seguiria.",
  ui_story_5088_50880702_56_dialog_content = "Sou eu quem agora a segue!",
  ui_story_5088_50880702_57_dialog_content = "Hahaha! Aquiles, agora sou eu quem a segue!",
  ui_story_5088_50880702_58_dialog_content = "Eu posso não ser o mencionado na profecia, mas ainda posso ser o mencionado na profecia!",
  ui_story_5088_50880702_59_dialog_content = "Parece que você finalmente percebeu a luz que carrega dentro de si.",
  ui_story_5088_50880702_60_dialog_content = "E minha fé será passada para o próximo celestita!",
  ui_story_5088_50880702_61_dialog_content = "Passaremos uma chama na escuridão selvagem até que nossa luz ilumine esta terra de desespero!",
  ui_story_5088_50880702_62_dialog_content = "Ludweiss, finalmente entendi suas últimas palavras... Finalmente entendi suas últimas palavras!!!",
  ui_story_5088_50880702_63_dialog_content = "Não preciso completar tudo sozinho - só preciso fazer o que posso e depois passar para o próximo celestita.",
  ui_story_5088_50880702_64_dialog_content = "Também vou registrar minhas percepções, tornando-me um mensageiro para as futuras gerações!",
  ui_story_5088_50880702_65_dialog_content = "Cem anos, mil anos, dois mil anos a partir de agora! Um dia, quando seu corpo se estabilizar, um Celestita trará sua consciência de volta!",
  ui_story_5088_50880702_66_dialog_content = "Eu confio em você, meu amigo. O que você precisa que eu faça?",
  ui_story_5088_50880702_67_dialog_content = "<color=#e8d9bb>Então, para você que está lendo isso, meu sucessor, por favor, atenda às minhas palavras.</color>",
  ui_story_5088_50880702_68_dialog_content = "<color=#e8d9bb>Eu fui uma vez excessivamente ambicioso, acreditando ser o salvador escolhido, e por isso falhei naquela época...</color>",
  ui_story_5088_50880702_69_dialog_content = "<color=#e8d9bb>Mas eu também tive sucesso, pois fiz tudo o que pude e passei a tocha para você.</color>",
  ui_story_5088_50880702_70_dialog_content = "<color=#e8d9bb>Agora, se você estiver disposto, não importa o quanto ou quão pouco você possa fazer, eu sinceramente espero que você possa ajudar a manter esta chama viva.</color>",
  ui_story_5088_50880702_71_dialog_content = "<color=#e8d9bb>Nós, que viemos antes de você, sempre seremos gratos pela sua ajuda.</color>",
  ui_story_5088_50880702_72_dialog_content = "<color=#e8d9bb>E se o gelo e a neve derreterem, e a primavera chegar a esta terra de desespero, por favor, venha até aqui.</color>",
  ui_story_5088_50880702_73_dialog_content = "<color=#e8d9bb>Claymore aguarda. Por favor, diga a ele, \"A primavera chegou.\"</color>",
  ui_story_5088_50880801_1_dialog_content = "Se revele!",
  ui_story_5088_50880801_2_dialog_content = "... Quando você notou que eu estava aqui?",
  ui_story_5088_50880801_3_dialog_content = "Desde o começo mesmo.",
  ui_story_5088_50880801_4_dialog_content = "Não se deixe enganar pela equipe e pela aparência perpetuamente confusa de Cynthia.",
  ui_story_5088_50880801_5_dialog_content = "Ela é a melhor batedora da nossa equipe.",
  ui_story_5088_50880801_6_dialog_content = "Ela costumava disfarçar seu cajado como um arco para evitar incomodar os magos. Assim como você, ela gosta de ficar escondida.",
  ui_story_5088_50880801_7_dialog_content = "... Desculpe por segui-lo. Eu prometo, minhas intenções são boas. Meu nome é Mithra Longinus, e eu tenho uma missão.",
  ui_story_5088_50880801_8_dialog_content = "Uma garota Longinus? Descendente de Anthony, presumo?",
  ui_story_5088_50880801_9_dialog_content = "Você se lembra do meu antepassado?",
  ui_story_5088_50880801_10_dialog_content = "Haha, ele sempre estava disposto a passar tempo conosco, criaturas. Pensávamos que ele estava simplesmente atrás de alguma comida grátis. Deixe-me dizer, ele deixou uma grande impressão em nós.",
  ui_story_5088_50880801_11_dialog_content = "Agora, após dois mil anos, encontramos outro Longinus.",
  ui_story_5088_50880801_12_dialog_content = "Anthony... ele viveu uma vida feliz?",
  ui_story_5088_50880801_13_dialog_content = "... Ele estava muito feliz. Após receber a bênção do Senhor Aquiles, ele sorriu e faleceu. Ele foi enterrado nas proximidades com honra.",
  ui_story_5088_50880801_14_dialog_content = "Para realizar grandes feitos e deixar este mundo nos braços de entes queridos... ele foi abençoado.",
  ui_story_5088_50880801_15_dialog_content = "Dois mil anos se passaram, mas finalmente recebemos algumas boas notícias.",
  ui_story_5088_50880801_16_dialog_content = "... Longinus, podemos adivinhar qual é essa missão que o prende.",
  ui_story_5088_50880801_17_dialog_content = "Neste ponto, só você conhece o destino dessa pessoa...",
  ui_story_5088_50880801_18_dialog_content = "Mas parece que você, como eu, abraça voluntariamente essas algemas.",
  ui_story_5088_50880801_19_dialog_content = "Se pedirmos, você pode nos contar?",
  ui_story_5088_50880801_20_dialog_content = "A missão da nossa família é guardar os segredos das estrelas e não deixar ninguém se aproximar delas.",
  ui_story_5088_50880801_21_dialog_content = "Mas se este é o comando dos Guerreiros Estelares, falarei da minha missão.",
  ui_story_5088_50880801_22_dialog_content = "Mas antes disso, eu só quero dizer... você já me ajudou.",
  ui_story_5088_50880801_23_dialog_content = "Uau, você acordou!",
  ui_story_5088_50880801_24_dialog_content = "Esses eram apenas os registros mais triviais do nosso clã. O quanto você viu se deve à sua própria convicção.",
  ui_story_5088_50880801_25_dialog_content = "Certo... Eu vi a perseverança do clã Longinus através das gerações.",
  ui_story_5088_50880801_26_dialog_content = "... Acho que a melhor maneira de descrever seria \"inflexível até o fim.\"",
  ui_story_5088_50880801_27_dialog_content = "E eu não estou falando apenas de uma pessoa—essa coisa de \"inabalável até o fim\" se aplica a todo o clã Longinus.",
  ui_story_5088_50880801_28_dialog_content = "Então, acho que o motivo de todos terem uma fé tão forte é até mesmo o motivo pelo qual você continua até hoje...",
  ui_story_5088_50880801_29_dialog_content = "Deve ser porque Aquiles ainda está por aqui em algum lugar.",
  ui_story_5088_50880801_30_dialog_content = "Então você voltou aqui para procurar pistas?",
  ui_story_5088_50880801_31_dialog_content = "Certo, e eu já vi o local final. Quero ver o que o Sr. Czerny deixou para trás.",
  ui_story_5088_50880801_32_dialog_content = "Então o que estamos esperando?",
  ui_story_5088_50880801_33_dialog_content = "Uau! Friegson está tão ansiosa de repente! Está ansiosa para um duelo com Aquiles, hein?",
  ui_story_5088_50880801_34_dialog_content = "... Chega de tagarelice. Vamos.",
  ui_story_5088_50880801_35_dialog_content = "Estamos aqui.",
  ui_story_5088_50880801_36_dialog_content = "Hmm, à primeira vista, nada se destaca. E em uma inspeção mais de perto... ainda nada.",
  ui_story_5088_50880801_37_dialog_content = "No entanto, através da lente da magia, um intrigante poder incolor é reunido aqui.",
  ui_story_5088_50880801_38_dialog_content = "De fato. Esta é a formação mágica de Aquiles.",
  ui_story_5088_50880801_39_dialog_content = "Podemos forçá-lo a abrir com nossa magia?",
  ui_story_5088_50880801_40_dialog_content = "Vale a pena tentar.",
  ui_story_5088_50880801_41_dialog_content = "Não... Não há necessidade de ir a tais extremos.",
  ui_story_5088_50880801_42_dialog_content = "Senhorita Mithra, por favor, abra o selo.",
  ui_story_5088_50880801_43_dialog_content = "Você tem a chave, certo?",
  ui_story_5088_50880801_44_dialog_content = "...",
  ui_story_5088_50880801_45_dialog_content = "Quando meu ancestral faleceu, o Senhor Aquiles deu à nossa família um amuleto.",
  ui_story_5088_50880801_46_dialog_content = "O Brasão de Estrela...",
  ui_story_5088_50880801_47_dialog_content = "Uma formação mágica auto-sustentável do material mais delicado— a maior honra que o Senhor Aquiles concedeu ao nosso clã.",
  ui_story_5088_50880801_48_dialog_content = "Ele provavelmente pretendia que usássemos esse poder para nos proteger, mas os chefes da família Longinus sempre foram relutantes em usá-lo.",
  ui_story_5088_50880801_49_dialog_content = "Assim, tornou-se um símbolo do nosso voto, uma herança de família.",
  ui_story_5088_50880801_50_dialog_content = "Nunca pensei que um dia seria colocado em uso.",
  ui_story_5088_50880801_51_dialog_content = "Isso violará seu juramento?",
  ui_story_5088_50880801_52_dialog_content = "Não, porque este é o seu desejo e a intenção original do clã Longinus.",
  ui_story_5088_50880801_53_dialog_content = "... Agradeço.",
  ui_story_5088_50880801_54_dialog_content = "Não, Senhora Friegson, por favor não me agradeça...",
  ui_story_5088_50880801_55_dialog_content = "Nunca sonhei que alguém nos protegeria por dois milênios.",
  ui_story_5088_50880801_56_dialog_content = "Mithra, por tudo isso, por favor, aceite minha gratidão.",
  ui_story_5088_50880801_57_dialog_content = "Caso contrário, Friegson pode se sentir um tanto desconfortável.",
  ui_story_5088_50880801_58_dialog_content = "Eu entendo... Então, eu vou quebrar o selo.",
  ui_story_5088_50880801_59_dialog_content = "<color=#e8d9bb>Mithra remove seu colar, revelando sua verdadeira forma - um Brasão de Estrela.</color>",
  ui_story_5088_50880801_60_dialog_content = "<color=#e8d9bb>Então, ela invoca a ponta de uma lança do Brasão de Estrela.</color>",
  ui_story_5088_50880801_61_dialog_content = "Isso é...",
  ui_story_5088_50880801_62_dialog_content = "Eraveil?",
  ui_story_5088_50880801_63_dialog_content = "H-Como isso é possível?",
  ui_story_5088_50880801_64_dialog_content = "Uau, que planícies lindas... Olha, dentes-de-leão de Eraveil.",
  ui_story_5088_50880801_65_dialog_content = "Até a Torre Branca permanece, restaurada em toda a sua glória.",
  ui_story_5088_50880801_66_dialog_content = "Parece que devemos nos aventurar lá para entender tudo.",
  ui_story_5088_50880801_67_dialog_content = "No entanto, não parece ser tão sereno quanto Eraveil já foi.",
  ui_story_5088_50880801_68_dialog_content = "Hã? São estes...",
  ui_story_5088_50880802_1_dialog_content = "Poderiam ser estas as defesas de Aquiles?",
  ui_story_5088_50880802_2_dialog_content = "Talvez devêssemos ir primeiro ao Obelisco do Retorno.",
  ui_story_5088_50880802_3_dialog_content = "Quanto mais nos aproximamos, mais estranha se torna essa sensação no meu coração.",
  ui_story_5088_50880802_4_dialog_content = "Cynthia, Freya, vocês também sentem isso?",
  ui_story_5088_50880802_5_dialog_content = "Ainda poderia ser a influência persistente da formação mágica?",
  ui_story_5088_50880802_6_dialog_content = "Não, parece que o brasão está ressoando.",
  ui_story_5088_50880802_7_dialog_content = "Minha espada... parece estar me falando de... memórias...",
  ui_story_5088_50880802_8_dialog_content = "?!",
  ui_story_5088_50880802_9_dialog_content = "Parece que encontramos.",
  ui_story_5088_50880802_10_dialog_content = "Verificando informações biológicas, por favor, aguarde.",
  ui_story_5088_50880802_11_dialog_content = "Isso é exatamente o que eu vi uma vez antes...",
  ui_story_5088_50880802_12_dialog_content = "Caelestita detectada, bem-vindo ao País das Maravilhas.",
  ui_story_5088_50880802_13_dialog_content = "Parece que nosso anfitrião está pronto para nos receber.",
  ui_story_5088_50880802_14_dialog_content = "Agora tocando as últimas palavras de Czerny. Por favor, ouça durante a sua subida.",
  ui_story_5088_50880802_15_dialog_content = "Se você está ouvindo isso, significa que eu tive sucesso, e um celestita de uma nova era foi guiado até aqui.",
  ui_story_5088_50880802_16_dialog_content = "Muito bem, herói do futuro.",
  ui_story_5088_50880802_17_dialog_content = "Para conservar a energia restante desta estrutura, serei breve... Em resumo, há um Colossus danificado atrás desta torre.",
  ui_story_5088_50880802_18_dialog_content = "Foi o veículo que Aquiles e eu usamos para vir aqui...",
  ui_story_5088_50880802_19_dialog_content = "Nunca pensei que chegaria aqui nos meus anos crepusculares... a Colossus...",
  ui_story_5088_50880802_20_dialog_content = "Desculpe, Mestre Czerny, por favor escolha um Colossus rapidamente... Não vou aguentar muito mais tempo—todos podem descobrir que você está aqui em breve.",
  ui_story_5088_50880802_21_dialog_content = "Mantiz ou 6#S%—você pode escolher qualquer um.",
  ui_story_5088_50880802_22_dialog_content = "Não, eu escolho aquele—Fortez!",
  ui_story_5088_50880802_23_dialog_content = "Mas esse é o <color=#FFB400>Colosso de Guerra</color> selado.",
  ui_story_5088_50880802_24_dialog_content = "Sim, é exatamente isso que eu preciso.",
  ui_story_5088_50880802_25_dialog_content = "Pesquisei por tanto tempo para descobrir por que estava selado. Ele... pode gerar Eclipsitas. Talvez nosso clã tenha cometido grandes pecados no passado.",
  ui_story_5088_50880802_26_dialog_content = "Mas os Celestitas não precisam mais de um Colossus de Guerra, então eu poderia muito bem ajudar a destruir o último dispositivo gerador de Eclipsitas.",
  ui_story_5088_50880802_27_dialog_content = "Então por favor, Mestre, leve-o embora.",
  ui_story_5088_50880802_28_dialog_content = "Fortez, atenda ao meu chamado, aceite meu comando, deixe-me navegar você... Hmm?",
  ui_story_5088_50880802_29_dialog_content = "Está desprovido de consciência?",
  ui_story_5088_50880802_30_dialog_content = "Como pode ser? Será que quando foi selado, sua consciência foi deliberadamente apagada?",
  ui_story_5088_50880802_31_dialog_content = "É muito provável. Os Colossos de Guerra não nos obedeceriam, os traidores que viraram as costas para a guerra. Talvez seja apenas nosso prisioneiro agora.",
  ui_story_5088_50880802_32_dialog_content = "Então, eu serei o único a navegar você!",
  ui_story_5088_50880802_33_dialog_content = "Mestre Czerny... você vai voltar?",
  ui_story_5088_50880802_34_dialog_content = "Hahaha, sim! Um dia, eu voltarei para enfrentar meu castigo.",
  ui_story_5088_50880802_35_dialog_content = "Não importa quanto tempo demore, me esforçarei para voltar.",
  ui_story_5088_50880802_36_dialog_content = "Se você não pode esperar por mim, toque minha música em Windelion para me guiar de volta.",
  ui_story_5088_50880802_37_dialog_content = "Mestre Czerny...",
  ui_story_5088_50880802_38_dialog_content = "\"Não vá gentilmente para aquela boa noite.\"",
  ui_story_5088_50880802_39_dialog_content = "\"A velhice deve queimar e delirar ao cair do dia.\"",
  ui_story_5088_50880802_40_dialog_content = "\"Fúria, fúria contra o apagar da luz...\"",
  ui_story_5088_50880802_41_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5088_50880802_42_dialog_content = "?!",
  ui_story_5088_50880802_43_dialog_content = "Estou de volta, Aquiles... Eu acidentalmente fiz um buraco bastante grande. Desculpe...",
  ui_story_5088_50880802_44_dialog_content = "Você... O que está acontecendo aqui?",
  ui_story_5088_50880802_45_dialog_content = "Este Colosso pode usar suas informações genéticas para criar um novo corpo.",
  ui_story_5088_50880802_46_dialog_content = "Eu digo criar, mas é apenas copiar ou usar o termo designado pelo dispositivo de controle - \"clonagem\".",
  ui_story_5088_50880802_47_dialog_content = "Dessa forma, sua consciência não será rejeitada.",
  ui_story_5088_50880802_48_dialog_content = "No entanto, criar um corpo novo leva tempo, e não posso garantir que o novo corpo não enfrentará erosão. Uma observação mais aprofundada pode ser necessária.",
  ui_story_5088_50880802_49_dialog_content = "A Colossus é muito conspícua para permanecer aqui. Primeiro, devo reunir sua consciência usando o Echo Template que trouxe para abrigar você.",
  ui_story_5088_50880802_50_dialog_content = "Se eu perguntasse se você é realmente capaz de ter sucesso em tudo isso, pode parecer que eu não confio em você.",
  ui_story_5088_50880802_51_dialog_content = "Mas... você confirmou nossas dúvidas?",
  ui_story_5088_50880802_52_dialog_content = "A consciência de alguém equivale à sua alma?",
  ui_story_5088_50880802_53_dialog_content = "Memória, pensamento, natureza - juntos, eles formam o meu ser.",
  ui_story_5088_50880802_54_dialog_content = "Essa consciência é minha alma?",
  ui_story_5088_50880802_55_dialog_content = "Eu testei a teoria.",
  ui_story_5088_50880802_56_dialog_content = "Você... Czerny, o que você fez?!",
  ui_story_5088_50880802_57_dialog_content = "Abandonei meu corpo e armazenei minha consciência aqui.",
  ui_story_5088_50880802_58_dialog_content = "Em Fortez.",
  ui_story_5088_50880802_59_dialog_content = "?!",
  ui_story_5088_50880802_60_dialog_content = "Para confirmar todas as especulações que tínhamos, conduzi este experimento - afinal, sou apenas um velhote.",
  ui_story_5088_50880802_61_dialog_content = "A resposta é, minha alma permanece firme, ainda ansiosa para te ajudar.",
  ui_story_5088_50880802_62_dialog_content = "Czerny...",
  ui_story_5088_50880802_63_dialog_content = "Agora eu não sou mais um celestita e não consigo utilizar totalmente minhas habilidades psíquicas.",
  ui_story_5088_50880802_64_dialog_content = "Mas felizmente, você é habilidoso em selar e conjurar formações mágicas.",
  ui_story_5088_50880802_65_dialog_content = "Vou ajudar a transferir sua consciência para o Modelo de Eco do Colossus.",
  ui_story_5088_50880802_66_dialog_content = "Então... nós voaremos para Eraveil!",
  ui_story_5088_50880802_67_dialog_content = "Mesmo que nossas vozes não possam alcançá-los, algum dia, alguém será guiado até nós e nos deslacrará.",
  ui_story_5088_50880802_68_dialog_content = "... Agora entendo sua determinação.",
  ui_story_5088_50880802_69_dialog_content = "Neste último momento, sinto-me compelido a deixar algo para trás.",
  ui_story_5088_50880901_1_dialog_content = "<color=#e8d9bb>Clique! O fluxo de energia dentro da Torre Branca é subitamente cortado, e as palavras de Czerny desaparecem.</color>",
  ui_story_5088_50880901_2_dialog_content = "Eu vou ao centro e dou uma olhada.",
  ui_story_5088_50880901_3_dialog_content = "Como você planeja chegar lá? É muito perigoso.",
  ui_story_5088_50880901_4_dialog_content = "<color=#e8d9bb>Mithra não responde e simplesmente abre suas asas. Suas asas estavam esperando o tempo todo, escondidas sob seu modesto manto.</color>",
  ui_story_5088_50880901_5_dialog_content = "Então, tudo que precisamos fazer é voar... Ah, quase me esqueci—ela é da União Mensageira.",
  ui_story_5088_50880901_6_dialog_content = "Aqueles que se escondem mais frequentemente do que não precisam se reprimir sem compromisso. As asas dela parecem ser a prova deste fato.",
  ui_story_5088_50880901_7_dialog_content = "Você consegue se virar sozinho? Precisa da minha ajuda - eu sou bom com raios...",
  ui_story_5088_50880901_8_dialog_content = "Encontrei a linha defeituosa. Apenas espere lá embaixo.",
  ui_story_5088_50880901_9_dialog_content = "Já fiz inúmeros trabalhos assim antes, então não há nada com o que se preocupar.",
  ui_story_5088_50880901_10_dialog_content = "Se você não ficar de olho nela, é como se ela desaparecesse completamente da história.",
  ui_story_5088_50880901_11_dialog_content = "Devemos fazer o mesmo?",
  ui_story_5088_50880901_12_dialog_content = "Não, isso não será necessário. Estou acostumado a me esconder nas margens de uma história - quanto menos notável, melhor.",
  ui_story_5088_50880901_13_dialog_content = "Nosso clã viveu desta maneira por gerações. Não ficamos em um lugar e não fazemos amigos.",
  ui_story_5088_50880901_14_dialog_content = "Desejamos apenas nos tornar a noite que guarda as estrelas.",
  ui_story_5088_50880901_15_dialog_content = "Você pode estar acostumado a se esconder nas sombras, se misturando à folhagem...",
  ui_story_5088_50880901_16_dialog_content = "Mas, Senhorita Mithra... Eu não acho que você nasceu apenas para cumprir a felicidade de outras pessoas. Você também merece sua própria felicidade.",
  ui_story_5088_50880901_17_dialog_content = "...",
  ui_story_5088_50880901_18_dialog_content = "O povo do seu clã se sacrificou silenciosamente por dois mil anos. Devemos-lhe mais do que as palavras podem expressar.",
  ui_story_5088_50880901_19_dialog_content = "Por favor, não diga isso... Eu não sou nada comparado aos meus antepassados...",
  ui_story_5088_50880901_20_dialog_content = "Eu estive com medo, irritado, confuso, e eu até pensei em desistir...",
  ui_story_5088_50880901_21_dialog_content = "Passei mais de uma década procurando por Celestitas, mas não havia mais ninguém. A dor era insuportável.",
  ui_story_5088_50880901_22_dialog_content = "Eu estava tão apavorado, temendo que eu iria falhar completamente...",
  ui_story_5088_50880901_23_dialog_content = "Mas, um herói é alguém que conhece o medo e ainda assim se mantém firme.",
  ui_story_5088_50880901_24_dialog_content = "Hã?!",
  ui_story_5088_50880901_25_dialog_content = "Esta é a lição mais valiosa que aprendi com meu querido Marcela.",
  ui_story_5088_50880901_26_dialog_content = "Mithra Longinus, levante a cabeça. Você não tem motivo para se sentir envergonhado. Nunca foi justo para o seu clã carregar um fardo tão pesado por dois mil anos.",
  ui_story_5088_50880901_27_dialog_content = "Lembre-se, você é digno do nosso respeito, assim como o seu grande ancestral.",
  ui_story_5088_50880901_28_dialog_content = "Adras...?",
  ui_story_5088_50880901_29_dialog_content = "Somos todos iguais, não somos? Perdidos por muito tempo...",
  ui_story_5088_50880901_30_dialog_content = "Uh-oh, o vice-capitão está vendo coisas de novo?",
  ui_story_5088_50880901_31_dialog_content = "Huh? Por que de repente me lembrei disso?",
  ui_story_5088_50880901_32_dialog_content = "Parece que o capítulo final da história está pronto para ser revelado.",
  ui_story_5088_50880901_33_dialog_content = "Será por causa desses brasões? Eles estão ressoando como loucos desde que chegamos aqui.",
  ui_story_5088_50880901_34_dialog_content = "O degelo em nossos corações está começando a desaparecer...",
  ui_story_5088_50880901_35_dialog_content = "A linha está fixa.",
  ui_story_5088_50880901_36_dialog_content = "Parece que todos nós encontramos nosso caminho.",
  ui_story_5088_50880901_37_dialog_content = "Não precisa se preocupar, pessoal.",
  ui_story_5088_50880901_38_dialog_content = "Eu... sim... ainda não consigo aceitar a partida de Marcela, então ela permanece ao meu lado, me protegendo.",
  ui_story_5088_50880901_39_dialog_content = "Se um dia eu pudesse descansar com ela até o fim dos tempos, seria verdadeiramente maravilhoso, mas até então, desejo proteger este mundo e viajar com todos vocês mais uma vez.",
  ui_story_5088_50880901_40_dialog_content = "Você continuará a caminhar por este caminho comigo?",
  ui_story_5088_50880901_41_dialog_content = "... Você realmente precisa perguntar?",
  ui_story_5088_50880901_42_dialog_content = "Avante!",
  ui_story_5088_50880901_43_dialog_content = "Obrigado, Mithra.",
  ui_story_5088_50880901_44_dialog_content = "Você não precisa me agradecer... Eu deveria ser o único a agradecer a você.",
  ui_story_5088_50880901_45_dialog_content = "É graças aos seus esforços que os Guerreiros Estelares brilharão novamente, e eu finalmente posso ver alguma esperança para o futuro.",
  ui_story_5088_50880901_46_dialog_content = "Você está desempenhando um tipo de papel menor agora. Se você fosse tão corajoso quanto eu e tivesse mais falas, sua presença geral poderia começar a decolar!",
  ui_story_5088_50880901_47_dialog_content = "... Sua alegria é um pouco exagerada.",
  ui_story_5088_50880901_48_dialog_content = "Em dois mil anos, só vimos dois Celestitas.",
  ui_story_5088_50880901_49_dialog_content = "Tanto ela quanto PlayerName são nossos benfeitores, compartilhando nada além de boa vontade.",
  ui_story_5088_50880901_50_dialog_content = "É uma pena...",
  ui_story_5088_50880901_51_dialog_content = "...",
  ui_story_5088_50880901_52_dialog_content = "<size=30>Ai, que conversa fiada...</size> Uau, olha essa pedra! É uma pedra e é tão... pedregosa... e tem inimigos!",
  ui_story_5088_50880901_53_dialog_content = "<size=45>Sério! Atenção, os inimigos estão chegando!</size>",
  ui_story_5088_50880902_1_dialog_content = "Só isso?",
  ui_story_5088_50880902_2_dialog_content = "Deixei minha última obsessão com a formação mágica auto-circulante neste corpo.",
  ui_story_5088_50880902_3_dialog_content = "Enquanto minha carne existir, a formação persistirá. Eu vou vigiar este lugar para sempre.",
  ui_story_5088_50880902_4_dialog_content = "Dê isso para mim. Deixe-me fazer o upload da consciência.",
  ui_story_5088_50880902_5_dialog_content = "Rugido!!!",
  ui_story_5088_50880902_6_dialog_content = "Magia da floresta, esconda-nos dos olhos de nosso perseguidor—Vá!",
  ui_story_5088_50880902_7_dialog_content = "Não! Eu não vou deixar você ir!",
  ui_story_5088_50880902_8_dialog_content = "<size=45>Morte a todos os inimigos!!!</size>",
  ui_story_5088_50880902_9_dialog_content = "Um Celestita... Eu devo poupá-lo...",
  ui_story_5088_50880902_10_dialog_content = "<color=#e8d9bb>Silenciosamente, ele observa enquanto sua presa escapa.</color>",
  ui_story_5088_50880902_11_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50881000_1_dialog_content = "... Mas nossa jornada não está completa.",
  ui_story_5088_50881000_2_dialog_content = "O que aconteceu? Por que parou aqui?",
  ui_story_5088_50881000_3_dialog_content = "PlayerName, você sabe que isso é apenas uma mensagem, certo?",
  ui_story_5088_50881000_4_dialog_content = "Hum...",
  ui_story_5088_50881000_5_dialog_content = "Eu fui descuidado.",
  ui_story_5088_50881000_6_dialog_content = "Eu não sabia que, uma vez ativado o dispositivo de geração, o forte sinal que ele emitia iria atrair...",
  ui_story_5088_50881000_7_dialog_content = "Eles.",
  ui_story_5088_50881000_8_dialog_content = "Aqui, por aqui, por aqui, por aqui...",
  ui_story_5088_50881000_9_dialog_content = "Como tantos Eclipsitas conseguiram nos alcançar?",
  ui_story_5088_50881000_10_dialog_content = "Poderia ser que eles rastrearam o sinal da \"substância X\" do dispositivo? Maldito seja o seu poder sombrio!",
  ui_story_5088_50881000_11_dialog_content = "...",
  ui_story_5088_50881000_12_dialog_content = "Oh não, a consciência de Aquiles ainda não se fundiu com o novo corpo. Ele não pode lutar.",
  ui_story_5088_50881000_13_dialog_content = "<size=45>Asas atingidas...! Estamos acabados!</size>",
  ui_story_5088_50881000_14_dialog_content = "<color=#FFB400>Estrela escura! Erupta!</color>",
  ui_story_5088_50881000_15_dialog_content = "O que houve?",
  ui_story_5088_50881000_16_dialog_content = "Uma quantidade massiva de poder essencial... \"Substância N\" convergiu...",
  ui_story_5088_50881000_17_dialog_content = "Aquiles, é você?",
  ui_story_5088_50881000_18_dialog_content = "... Consegue me ouvir?",
  ui_story_5088_50881000_19_dialog_content = "Você pode controlar remotamente seu novo corpo... É um milagre...",
  ui_story_5088_50881000_20_dialog_content = "Eu... não posso... sustentar isso...",
  ui_story_5088_50881000_21_dialog_content = "Eu bati... Não podemos continuar voando...",
  ui_story_5088_50881000_22_dialog_content = "Vou tentar me consertar com os vaga-lumes, mas antes disso... você pode usar sua mágica para criar uma ilusão?",
  ui_story_5088_50881000_23_dialog_content = "... Eu vou... tentar...",
  ui_story_5088_50881000_24_dialog_content = "Mas, meu reparo falhou.",
  ui_story_5088_50881000_25_dialog_content = "Eu pedi aos vaga-lumes para usar os materiais disponíveis nas proximidades para criar este <color=#FFB400>Obelisco do Retorno</color> para que eu pudesse deixar uma mensagem.",
  ui_story_5088_50881000_26_dialog_content = "Queria incluir as informações genéticas do clã Longinus no sistema de identificação, mas não havia ninguém da família Longinus para coletá-las.",
  ui_story_5088_50881000_27_dialog_content = "Então, extraí as informações raciais dos Celestitas do meu próprio cadáver como a única chave.",
  ui_story_5088_50881000_28_dialog_content = "Antes da energia acabar, eu vi o clã Longinus encontrar este lugar.",
  ui_story_5088_50881000_29_dialog_content = "Mas eles não pareciam entender o que havia acontecido, e talvez devido ao dispositivo gerador de Eclipsitas, eles não ousaram informar Eraveil.",
  ui_story_5088_50881000_30_dialog_content = "Tudo que eu pude fazer foi esperar... esperar pela sua chegada... uma vez que eu desligar, minha consciência desaparecerá... então eu deixei essas palavras para você...",
  ui_story_5088_50881000_31_dialog_content = "Ludweiss e Aquiles estão no topo desta torre, e o novo corpo ainda está na cápsula de hibernação da Colossus.",
  ui_story_5088_50881000_32_dialog_content = "Por favor, suba e veja eles primeiro...",
  ui_story_5088_50881000_33_dialog_content = "... Parece que seu clã estava preocupado com as coisas piorando novamente, então eles se mantiveram firmes em seu dever.",
  ui_story_5088_50881000_34_dialog_content = "E por dois mil anos, seu povo escolheu permanecer escondido, observando silenciosamente aqueles diários, esperando pela profecia...",
  ui_story_5088_50881000_35_dialog_content = "Sim.",
  ui_story_5088_50881000_36_dialog_content = "O brasão que eu carrego, imbuido com o poder do Senhor Aquiles, permite que cada chefe de família adicione uma parte de suas memórias e vontade a ele.",
  ui_story_5088_50881000_37_dialog_content = "Presenciei os esforços dos meus antepassados - eles criaram um ecossistema dentro desta formação mágica e mantiveram o Colosso.",
  ui_story_5088_50881000_38_dialog_content = "Eles esperavam que este lugar se tornasse um lugar de descanso digno.",
  ui_story_5088_50881000_39_dialog_content = "Mais tarde, a Colossus foi reparada e sua energia foi restaurada, mas ninguém ousou tocá-la. Na minha geração, nem mesmo sabíamos sua localização exata.",
  ui_story_5088_50881000_40_dialog_content = " Czerny, me espere lá dentro...",
  ui_story_5088_50881000_41_dialog_content = "Eu já passei por isso antes - uma vez encontrei parte da consciência de um amigo em um Colosso de Guerra.",
  ui_story_5088_50881000_42_dialog_content = "Mesmo após ouvir tudo isso, ainda não entendemos algumas coisas.",
  ui_story_5088_50881000_43_dialog_content = "Assim que isso acabar, por favor, nos diga tudo o que você sabe.",
  ui_story_5088_50881000_44_dialog_content = "Talvez, o próprio Aquiles possa te dizer.",
  ui_story_5088_50881000_45_dialog_content = "Você está bastante confiante sobre tudo isso, não está? Tudo bem! Vou depositar minha fé naquela esperança radiante que brilha em seus olhos!",
  ui_story_5088_50881000_46_dialog_content = "Porque na última vez, nós realmente alcançamos o final perfeito que procurávamos...",
  ui_story_5088_50881000_47_dialog_content = "Então vamos fazer isso de novo!",
  ui_story_5088_50881000_48_dialog_content = "Sim... um final perfeito... mais uma vez!",
  ui_story_5088_50881102_1_dialog_content = "É aqui que a consciência de Aquiles reside agora...",
  ui_story_5088_50881102_2_dialog_content = "Somente você pode fundir a consciência do Senhor Aquiles com seu corpo.",
  ui_story_5088_50881102_3_dialog_content = "Vou tentar o meu melhor.",
  ui_story_5088_50881102_4_dialog_content = "...",
  ui_story_5088_50881102_5_dialog_content = "Você está... aqui...",
  ui_story_5088_50881102_6_dialog_content = "Hum?",
  ui_story_5088_50881102_7_dialog_content = "...",
  ui_story_5088_50881102_8_dialog_content = "Obrigado por nos liderar para fora de dois mil anos de escuridão.",
  ui_story_5088_50881102_9_dialog_content = "É hora de nós a levarmos de volta.",
  ui_story_5088_50881102_10_dialog_content = "Ludweiss...",
  ui_story_5088_50881102_11_dialog_content = "Finalmente, estamos reunidos novamente.",
  ui_story_5088_50881102_12_dialog_content = "PlayerName, gostaríamos de ficar aqui um pouco mais.",
  ui_story_5088_50881102_13_dialog_content = "Você vá primeiro para a Colossus.",
  ui_story_5088_50881102_14_dialog_content = "Claro...",
  ui_story_5088_50881102_15_dialog_content = "Vamos lá. Eu protegerei você.",
  ui_story_5088_50881102_16_dialog_content = "Será que desta vez será como um sonho para o Senhor Aquiles?",
  ui_story_5088_50881102_17_dialog_content = "Para ele, essa perda dura tanto tempo.",
  ui_story_5088_50881102_18_dialog_content = "Mas acho que ele ainda vai sorrir.",
  ui_story_5088_50881102_19_dialog_content = "Porque o Aquiles que eu conheço é um pioneiro, alguém que sempre avança sem medo.",
  ui_story_5088_50881102_20_dialog_content = "Eu sei... ele definitivamente vai continuar.",
  ui_story_5088_50881102_21_dialog_content = "É essa... a filosofia de Windelion?",
  ui_story_5088_50881102_22_dialog_content = "Sim...",
  ui_story_5088_50881102_23_dialog_content = "Lembre-se dos que partiram, e envie-lhes seus pensamentos, mas ao mesmo tempo, continue seguindo em frente.",
  ui_story_5088_50881102_24_dialog_content = "...",
  ui_story_5088_50881102_25_dialog_content = "Estamos aqui.",
  ui_story_5088_50881102_26_dialog_content = "<color=#e8d9bb>No fundo da Colossus desgastada, há um painel de controle semelhante a um piano - um que o Caelestite conhece tão bem.</color>",
  ui_story_5088_50881102_27_dialog_content = "<color=#e8d9bb>E esperando naquele assento, há um esqueleto.</color>",
  ui_story_5088_50881102_28_dialog_content = "Sr. Czerny...",
  ui_story_5088_50881102_29_dialog_content = "...",
  ui_story_5088_50881102_30_dialog_content = "...",
  ui_story_5088_50881102_31_dialog_content = "O corpo de Aquiles descansa aqui.",
  ui_story_5088_50881102_32_dialog_content = "Hora de começar meu trabalho.",
  ui_story_5088_50881102_33_dialog_content = "<color=#e8d9bb>Eu movo cuidadosamente o Sr. Czerny, entregando-o a Mithra, e então, com grande respeito... Eu pressiono as teclas.</color>",
  ui_story_5088_50881102_34_dialog_content = "A Colossus foi reativada. Parece que o tempo chegou.",
  ui_story_5088_50881102_35_dialog_content = "Se você está ouvindo esta mensagem, significa que o programa de auto-verificação foi executado com sucesso e o corpo de Aquiles finalmente está estável.",
  ui_story_5088_50881102_36_dialog_content = "Em seguida, você deve escolher se vai completar essa grande façanha.",
  ui_story_5088_50881102_37_dialog_content = "Mas esta é uma tarefa extremamente perigosa, uma que pode muito bem custar sua vida. Se você escolher recusá-la, não vamos culpá-lo.",
  ui_story_5088_50881102_38_dialog_content = "Mas se você é realmente corajoso o suficiente para aceitar essa responsabilidade, ofereço a você minha mais profunda gratidão.",
  ui_story_5088_50881102_39_dialog_content = "Ouça bem - o poder incolor é a essência da Lúmina.",
  ui_story_5088_50881102_40_dialog_content = "De acordo com minha pesquisa, esta é a elusiva \"substância N\". Infelizmente, não tenho mais tempo para investigar sua conexão com a \"substância X\".",
  ui_story_5088_50881102_41_dialog_content = "A essência do poder incolor e da Lúmina colorida é fundamentalmente a mesma, mas nossa natureza inata torna difícil para nós reconhecermos a essência da variedade incolor.",
  ui_story_5088_50881102_42_dialog_content = "Felizmente, o corpo de Aquiles não está mais emaranhado em poder sombrio, reduzindo o perigo.",
  ui_story_5088_50881102_43_dialog_content = "No entanto, você ainda enfrentará grandes riscos ao guiar a consciência dele através da barreira incolor.",
  ui_story_5088_50881102_44_dialog_content = "Se você estiver pronto, coloque o Modelo Eco aqui e comece o processo de orientação.",
  ui_story_5088_50881102_45_dialog_content = "O sistema de gravação terminou—",
  ui_story_5088_50881102_46_dialog_content = "Tô pronto, Sr. Czerny.",
  ui_story_5088_50881102_47_dialog_content = "Mithra, enquanto estou usando minhas habilidades psíquicas, contarei com você para cuidar de tudo o resto.",
  ui_story_5088_50881102_48_dialog_content = "Eu vou te proteger. Eu juro.",
  ui_story_5088_50881102_49_option_content = "A última varredura psíquica",
  ui_story_5088_50881102_50_dialog_content = "Aquiles, seu longo sonho finalmente pode chegar ao fim.",
  ui_story_5088_50881102_51_dialog_content = "Por favor, volte comigo para...",
  ui_story_5088_50881102_52_dialog_content = "...",
  ui_story_5088_50881102_53_dialog_content = "Realmente é perigoso aqui. Não consigo ver nada...",
  ui_story_5088_50881102_54_dialog_content = "Aqui, por aqui, por aqui, por aqui...",
  ui_story_5088_50881102_55_dialog_content = "O que é isso? Essa voz soa tão familiar...",
  ui_story_5088_50881102_56_dialog_content = "... Outro \"traidor.\"",
  ui_story_5088_50881102_57_dialog_content = "Graças a você me reiniciando, finalmente serei revivido.",
  ui_story_5088_50881102_58_dialog_content = "Você é... essa Colossus?",
  ui_story_5088_50881102_59_dialog_content = "Mas o Sr. Czerny não encontrou uma consciência dentro de você...",
  ui_story_5088_50881102_60_dialog_content = "Idiota! Eu me escondi quando vocês traidores me pegaram. Por que eu me mostraria tão descuidadamente?",
  ui_story_5088_50881102_61_dialog_content = "Obrigado por me devolver ao meu corpo.",
  ui_story_5088_50881102_62_dialog_content = "Entendi... você não armazenou sua consciência nos componentes da máquina... você a transferiu para um modelo de backup!",
  ui_story_5088_50881102_63_dialog_content = "Você é bastante sagaz.",
  ui_story_5088_50881102_64_dialog_content = "Sim. Este traidor e eu compartilhamos o mesmo Modelo Eco.",
  ui_story_5088_50881102_65_dialog_content = "Agora, você deve me ajudar a reviver!",
  ui_story_5088_50881102_66_dialog_content = "(Minha cabeça... dói tanto...)",
  ui_story_5088_50881102_67_dialog_content = "(Está infiltrando minha mente? Como a consciência de um Colossus pode fazer algo assim?)",
  ui_story_5088_50881102_68_dialog_content = "Não se esqueça, você está conectado ao meu sistema operacional.",
  ui_story_5088_50881102_69_dialog_content = "(Não, eu não posso permitir isso...)",
  ui_story_5088_50881102_70_dialog_content = "Agora você é meu!",
  ui_story_5088_50881102_71_dialog_content = "Urghh...",
  ui_story_5088_50881102_72_dialog_content = "<size=45>Aniquilação!</size>",
  ui_story_5088_50881102_73_dialog_content = "Aaaahhhh!",
  ui_story_5088_50881102_74_dialog_content = "<color=#e8d9bb>O corpo adormecido de Claymore de repente desperta, liberando uma poderosa explosão de energia da espada em direção ao chão.</color>",
  ui_story_5088_50881102_75_dialog_content = "<color=#e8d9bb>Com apenas um golpe, Fortez é dividido ao meio.</color>",
  ui_story_5088_50881102_76_dialog_content = "<color=#e8d9bb>Do dispositivo gerador de Eclipsitas ao seu corpo, de suas ameaçadoras asas quebradas às suas ambições, todos são obliterados em um único golpe.</color>",
  ui_story_5088_50881102_77_dialog_content = "PlayerName!",
  ui_story_5088_50881102_78_dialog_content = "Minha conexão foi cortada... Aquiles me salvou.",
  ui_story_5088_50881102_79_dialog_content = "Não! Mas e você, Aquiles?!",
  ui_story_5088_50881102_80_dialog_content = "O Colosso está desmoronando. Está arruinado.",
  ui_story_5088_50881102_81_dialog_content = "Não! Preciso completar a fusão antes que ela se desintegre completamente!",
  ui_story_5088_50881102_82_option_content = "Aumento de Força",
  ui_story_5088_50881102_83_dialog_content = "Tolo! Depois de escapar por pouco, ainda tem a audácia de voltar aqui?",
  ui_story_5088_50881102_84_dialog_content = "O que mais você esperava?",
  ui_story_5088_50881102_85_dialog_content = "Prometi a todos que traria Aquiles de volta.",
  ui_story_5088_50881102_86_dialog_content = "Então, vou dizer a ele que a primavera chegou.",
  ui_story_5088_50881102_87_dialog_content = "Levarei ele, Sr. Czerny, e a Senhora Ludweiss para Eraveil...",
  ui_story_5088_50881102_88_dialog_content = "Para ver as lanternas de dente-de-leão e as coloridas bonecas Windelion com todos!",
  ui_story_5088_50881102_89_dialog_content = "Eu nunca vou deixar Aquiles se tornar apenas uma memória!!!",
  ui_story_5088_50881201_1_dialog_content = "Saiam, meus defensores!",
  ui_story_5088_50881201_2_dialog_content = "Monstros? Não, estão sendo criados por aquele dispositivo de geração?",
  ui_story_5088_50881201_3_dialog_content = "Eu não vou deixar você machucar PlayerName!",
  ui_story_5088_50881201_4_dialog_content = "(Rápido, preciso atravessar essa tempestade sem cor...)",
  ui_story_5088_50881201_5_dialog_content = "Aquiles, onde está você?",
  ui_story_5088_50881201_6_dialog_content = "Deixe-me ser seu farol! Venha comigo e retorne ao seu corpo!",
  ui_story_5088_50881201_7_dialog_content = "Pense novamente! Meu corpo já se foi... agora o corpo dele será meu!",
  ui_story_5088_50881201_8_dialog_content = "Ugh...",
  ui_story_5088_50881201_9_dialog_content = "Um colosso caído que se curva à Eclipse nunca derrotará as habilidades psíquicas de um Caelestite!",
  ui_story_5088_50881201_10_dialog_content = "ei^&c—",
  ui_story_5088_50881201_11_dialog_content = "De onde você tirou esse poder?",
  ui_story_5088_50881201_12_dialog_content = "Lutei contra inúmeros inimigos mais fortes do que você! Você nunca vai me derrubar!",
  ui_story_5088_50881201_13_dialog_content = "... Certamente você não pode lidar com esse poder! Seu corpo não aguenta tanta tensão!",
  ui_story_5088_50881201_14_dialog_content = "Olha, o campo de energia está fora de controle. Você nunca encontrará aquele que deseja ajudar nesta tempestade.",
  ui_story_5088_50881201_15_dialog_content = "Ele é uma existência incolor! Como você vai discernir a aura dele? Com esses olhos seus que só são atraídos pela luz?",
  ui_story_5088_50881201_16_dialog_content = "Eu... Eu terminei de ouvir suas bobagens!!!",
  ui_story_5088_50881201_17_dialog_content = "<size=45>Hyaaaa!</size>",
  ui_story_5088_50881201_18_dialog_content = "Não...",
  ui_story_5088_50881201_19_dialog_content = "(Todo o cansaço desses últimos dias está me alcançando... Minha cabeça parece que vai explodir... como se eu estivesse sendo puxado para baixo...)",
  ui_story_5088_50881201_20_dialog_content = "(Não posso cair agora... Não posso desistir...)",
  ui_story_5088_50881201_21_dialog_content = "(Mas... Estou tão cansado... e essa dor... Sinto que estou no meu limite...)",
  ui_story_5088_50881201_22_dialog_content = "Aquiles... Onde você está...?",
  ui_story_5088_50881201_23_dialog_content = "Quando o trabalho duro não consegue concluir a tarefa, você precisa confiar na sua sorte e intuição.",
  ui_story_5088_50881201_24_dialog_content = "(Por que isso surgiu na minha cabeça de repente...?)",
  ui_story_5088_50881201_25_dialog_content = "(Argh! De onde veio esse fogo neste mar de caos... Huh?)",
  ui_story_5088_50881201_26_dialog_content = "<color=#e8d9bb>Em meus últimos momentos de confusão, sou repentinamente despertado pelas chamas.</color>",
  ui_story_5088_50881201_27_dialog_content = "<color=#e8d9bb>A fonte do fogo são os dois Brasões de Estrela que Casta me ajudou a encontrar.</color>",
  ui_story_5088_50881201_28_dialog_content = "Este é do Ludweiss, e o outro deveria ser... Huh?",
  ui_story_5088_50881201_29_dialog_content = "Olhe para o céu, e as estrelas brilharão em resposta.",
  ui_story_5088_50881201_30_dialog_content = "O calor da sua luz ainda é o mesmo, mesmo após dois mil anos.",
  ui_story_5088_50881201_31_dialog_content = "Desta vez, deixe-nos ajudar você!",
  ui_story_5088_50881201_32_dialog_content = "Senhora Ludweiss? Sr. Czerny?",
  ui_story_5088_50881201_33_dialog_content = "Será que dentro das cristas também se encontram o seu...",
  ui_story_5088_50881201_34_dialog_content = "<color=#FFB400>Nossas esperanças e pensamentos!</color>",
  ui_story_5088_50881201_35_dialog_content = "De onde você veio?! O que você está tentando fazer?",
  ui_story_5088_50881201_36_dialog_content = "Nós? Hah! Nós atravessamos dois milênios—",
  ui_story_5088_50881201_37_dialog_content = "Passado através das eras—",
  ui_story_5088_50881201_38_dialog_content = "Um milagre nascido das conexões mais profundas!",
  ui_story_5088_50881201_39_dialog_content = "Alguém como você, que apenas incita conflitos e impede laços sinceros...",
  ui_story_5088_50881201_40_dialog_content = "Como você poderia possivelmente entender?!",
  ui_story_5088_50881201_41_dialog_content = "Aquiles! Você já dormiu o suficiente! Acorde!!!",
  ui_story_5088_50881201_42_dialog_content = "... Ludweiss?",
  ui_story_5088_50881201_43_dialog_content = "Não, não! Esse é o meu corpo!!!",
  ui_story_5088_50881201_44_dialog_content = "Cuidado, está prestes a atacar!",
  ui_story_5088_50881201_45_dialog_content = "Deixe-me cobrir a defesa!",
  ui_story_5088_50881201_46_dialog_content = "Jovem traidor, você acha que eles podem realmente te proteger? Você é muito fraco...",
  ui_story_5088_50881201_47_dialog_content = "Irmãozinho do futuro!",
  ui_story_5088_50881201_48_dialog_content = "Você uma vez me disse que acredita que as memórias são uma maldição.",
  ui_story_5088_50881201_49_dialog_content = "Mas, tendo vivido minha vida, tenho algo para compartilhar com você.",
  ui_story_5088_50881201_50_dialog_content = "Para mim, <color=#FFB400>memórias são presentes</color>! Você recebeu muitos presentes e honrou esses inúmeros pensamentos. Isso é algo verdadeiramente notável.",
  ui_story_5088_50881201_51_dialog_content = "Isso mesmo.",
  ui_story_5088_50881201_52_dialog_content = "Você herdou nossas memórias e vontade, e chegou até aqui. Isso por si só é incrível.",
  ui_story_5088_50881201_53_dialog_content = "Suas ações provam que a tocha do heroísmo pode ser passada de uma era para a próxima.",
  ui_story_5088_50881201_54_dialog_content = "Agora, é hora dos heróis de outrora realizarem sua alegria.",
  ui_story_5088_50881201_55_dialog_content = "Então, não tenha medo, e não fique confuso...",
  ui_story_5088_50881201_56_dialog_content = "Mantenha-se firme e dê o golpe final.",
  ui_story_5088_50881201_57_dialog_content = "Vamos!",
  ui_story_5088_50881201_58_dialog_content = "Caçadores Silenciosos!",
  ui_story_5088_50881201_59_dialog_content = "<color=#FFB400>Engajar!</color>",
  ui_story_5088_50881201_60_dialog_content = "O que é isso...? Inimigos mais problemáticos...",
  ui_story_5088_50881201_61_dialog_content = "Fortez... não ouse desviar o olhar... você ainda tem que...",
  ui_story_5088_50881201_62_dialog_content = "Seu pequeno pirralho...",
  ui_story_5088_50881201_63_dialog_content = "Pegue...",
  ui_story_5088_50881201_64_dialog_content = "... fora deste mundo!",
  ui_story_5088_50881201_65_dialog_content = "Não, não, não, não!",
  ui_story_5088_50881201_66_dialog_content = "<size=45>Eu vejo isso, comprimento de onda incolor!</size>",
  ui_story_5088_50881201_67_dialog_content = "Aquiles!",
  ui_story_5088_50881202_1_dialog_content = "PlayerName está sangrando muito! Precisamos encontrar uma maneira de parar isso...",
  ui_story_5088_50881202_2_dialog_content = "Não, deixe-me cuidar disso desta vez.",
  ui_story_5088_50881202_3_dialog_content = "Não podemos perturbá-lo agora. Tudo o que podemos fazer é usar magia para parar o sangramento.",
  ui_story_5088_50881202_4_dialog_content = "A consciência de Fortez se foi, e a consciência de Aquiles retornou com sucesso... Ludweiss, nós conseguimos...",
  ui_story_5088_50881202_5_dialog_content = "Parece que a hora de dizer adeus realmente chegou.",
  ui_story_5088_50881202_6_dialog_content = "Mas...",
  ui_story_5088_50881202_7_dialog_content = "Finalmente consegui ver todos vocês...",
  ui_story_5088_50881202_8_dialog_content = "É verdade.",
  ui_story_5088_50881202_9_dialog_content = "Bem, eu decidi há algum tempo que é justo eu te dar um presente - por todo o seu trabalho duro, é claro.",
  ui_story_5088_50881202_10_dialog_content = "Espero que você goste.",
  ui_story_5088_50881202_11_dialog_content = "Esta é a última coisa que posso realizar com a energia restante...",
  ui_story_5088_50881202_12_dialog_content = "Ah, a propósito, você poderia nos dizer o seu nome?",
  ui_story_5088_50881202_13_dialog_content = "Meu nome é PlayerName... Eu sou... um celestita. Eu trabalho com meus amigos na logística.",
  ui_story_5088_50881202_14_dialog_content = "Você é uma alma muito gentil e notável - um verdadeiro herói glorioso da sua época.",
  ui_story_5088_50881202_15_dialog_content = "Obrigado.",
  ui_story_5088_50881202_16_dialog_content = "Eu... hum... eu...",
  ui_story_5088_50881202_17_dialog_content = "Por favor, nos leve de volta para Eraveil.",
  ui_story_5088_50881202_18_dialog_content = "Limpe suas lágrimas e dê um sorriso para Windelion.",
  ui_story_5088_50881202_19_dialog_content = "Seus pensamentos já nos alcançaram... no rio onde nos reunimos.",
  ui_story_5088_50881202_20_dialog_content = "Você nunca estará sozinho.",
  ui_story_5088_50881202_21_dialog_content = "Adeus.",
  ui_story_5088_50881202_22_dialog_content = "Acorda... Acorda...",
  ui_story_5088_50881202_23_dialog_content = "Eu... Onde eles estão...? O que aconteceu...?",
  ui_story_5088_50881202_24_dialog_content = "Depois que a formação mágica do lado de fora desapareceu, algumas crianças curiosas de uma vila próxima se esgueiraram para dentro.",
  ui_story_5088_50881202_25_dialog_content = "Os Guerreiros das Estrelas partiram para mantê-los seguros.",
  ui_story_5088_50881202_26_dialog_content = "Mas... Acho que eles podem estar incertos de como abordar o Senhor Aquiles.",
  ui_story_5088_50881202_27_dialog_content = "Isto é... o Modelo Eco...",
  ui_story_5088_50881202_28_dialog_content = "Ah, outro está quebrado.",
  ui_story_5088_50881202_29_dialog_content = "Mas felizmente, consegui salvar a consciência dentro desta vez...",
  ui_story_5088_50881202_30_dialog_content = "... Vamos sair por agora. As coisas podem ficar estranhas se a primeira visão de Aquiles for um total estranho quando ele acordar.",
  ui_story_5088_50881202_31_dialog_content = "Vamos, deixe-me ajudá-lo a sair daqui.",
  ui_story_5088_50881202_32_dialog_content = "É tão lindo...",
  ui_story_5088_50881202_33_dialog_content = "Infelizmente, uma vez que a formação mágica do Lord Aquiles seja levantada, este lugar pode em breve voltar a ser as selvas normais de Northland.",
  ui_story_5088_50881202_34_dialog_content = "Mas tudo bem... Muitas coisas são melhores preservadas nas memórias.",
  ui_story_5088_50881202_35_dialog_content = "...",
  ui_story_5088_50881202_36_dialog_content = "Por favor, pegue isso.",
  ui_story_5088_50881202_37_dialog_content = "O que é isso?!",
  ui_story_5088_50881202_38_dialog_content = "É a última entrada no meu diário - um símbolo da gratidão do clã Longinus, concedido apenas àqueles que completam a verdadeira jornada de um herói.",
  ui_story_5088_50881202_39_dialog_content = "...Hã?",
  ui_story_5088_50881202_40_dialog_content = "<color=#e8d9bb>Um vento se levanta sob a distante Torre Branca, ascendendo ao céu.</color>",
  ui_story_5088_50881202_41_dialog_content = "<color=#e8d9bb>Uma melodia suave e melodiosa começa a tocar junto com a brisa.</color>",
  ui_story_5088_50881202_42_dialog_content = "<color=#e8d9bb>A Torre Branca, projetada pelo maestro musical Czerny, é em si um instrumento.</color>",
  ui_story_5088_50881202_43_dialog_content = "<color=#e8d9bb>E toca uma canção de ninar outrora conhecida em toda Eraveil.</color>",
  ui_story_5088_50881202_44_dialog_content = "<color=#e8d9bb>Composta por Czerny sob a orientação de Ludweiss—</color><color=#FFB400>Dia de Windelion: Uma Canção de Ninar para Viajantes.</color>",
  ui_story_5088_50881202_45_dialog_content = "É simplesmente divino.",
  ui_story_5088_50881202_46_dialog_content = "Este é o <color=#FFB400>presente</color>...",
  ui_story_5088_50881202_47_dialog_content = "Obrigada. Obrigado a ambos...",
  ui_story_5088_50881202_48_dialog_content = "<color=#e8d9bb>À medida que este diário chega à sua conclusão, qual final seria mais adequado?</color>",
  ui_story_5088_50881202_49_dialog_content = "<color=#e8d9bb>Ah, sim, deveria ir para você, aquele que se esforçou tanto para chegar a este ponto.</color>",
  ui_story_5088_50881202_50_dialog_content = "<color=#e8d9bb>Obrigado por tornar este milagre possível.</color>",
  ui_story_5088_50881202_51_dialog_content = "<color=#e8d9bb>Sei que essa jornada tem sido árdua e, no final, parece que sua única recompensa é testemunhar a alegria dos outros se reunindo.</color>",
  ui_story_5088_50881202_52_dialog_content = "<color=#e8d9bb>Mas você que lutou tão valentemente pelos outros - qual razão há para não reconhecer sua grandeza?</color>",
  ui_story_5088_50881202_53_dialog_content = "<color=#e8d9bb>May você, que chegou tão longe, também se reúna com aqueles que são importantes para você e encontre sua própria alegria.</color>",
  ui_story_5088_50881202_54_dialog_content = "<color=#e8d9bb>Desejamos a você felicidade do fundo de nossos corações, nossa estrela.</color>",
  ui_story_5088_50881300_1_dialog_content = "<color=#e8d9bb>Este é um reino que dorme na neve branca - um paraíso sereno e pacífico além do alcance do mundo.</color>",
  ui_story_5088_50881300_2_dialog_content = "<color=#e8d9bb>Heróis abençoados sonharam nesta terra congelada por anos, acompanhados pelos pensamentos mais calorosos.</color>",
  ui_story_5088_50881300_3_dialog_content = "<color=#e8d9bb>Debaixo deste mundo puro jaz enterrado muito do passado, e o que pode ser visto são apenas flores crescendo dos túmulos dos sacrificados, guardando um reino de conto de fadas.</color>",
  ui_story_5088_50881300_4_dialog_content = "<color=#e8d9bb>Bethlehem fecha o livro, olhando para a barreira derretendo à distância—dentro do reino há muito congelado de Northland, um campo de flores de primavera floresce.</color>",
  ui_story_5088_50881300_5_dialog_content = "<color=#e8d9bb>A história de Northland começa com o reino que primeiro a unificou. A lenda fala de um rei que sentou sozinho em um trono gelado, trazendo paz para esta terra.</color>",
  ui_story_5088_50881300_6_dialog_content = "<color=#e8d9bb>Muitos anos depois, os descendentes do rei se voltaram uns contra os outros em uma busca pelo poder, mergulhando Northland novamente no caos.</color>",
  ui_story_5088_50881300_7_dialog_content = "<color=#e8d9bb>Quando uma garota das terras fronteiriças testemunhou este mundo devastado, ela jurou restaurar sua pureza.</color>",
  ui_story_5088_50881300_8_dialog_content = "<color=#e8d9bb>Assim, a garota liderou o povo, tornando-se eventualmente rainha.</color>",
  ui_story_5088_50881300_9_dialog_content = "<color=#e8d9bb>Nos antigos tomos selados pelo velho rei, a rainha lê a história das \"estrelas\".</color>",
  ui_story_5088_50881300_10_dialog_content = "<color=#e8d9bb>Assim, cada Bethlehem começou a desejar o futuro das \"estrelas\".</color>",
  ui_story_5088_50881300_11_dialog_content = "Heróis, agora, é primavera.",
  ui_story_5088_50881300_12_dialog_content = "...",
  ui_story_5088_50881300_13_dialog_content = "Onde estamos?",
  ui_story_5088_50881300_14_dialog_content = "Adras, acho que o pão está quase pronto.",
  ui_story_5088_50881300_15_dialog_content = "Friegson, abaixe o aquecimento!",
  ui_story_5088_50881300_16_dialog_content = "... Alguém tem dado mordidinhas sorrateiras nele.",
  ui_story_5088_50881300_17_dialog_content = "Uau, cheira tão bem...",
  ui_story_5088_50881300_18_dialog_content = "O que aconteceu com o seu comportamento nobre?",
  ui_story_5088_50881300_19_dialog_content = "Quem se importa com isso quando há boa comida para comer?",
  ui_story_5088_50881300_20_dialog_content = "Eu posso ajudar!",
  ui_story_5088_50881300_21_dialog_content = "Ei! Você está apenas tentando pegar uma mordida atrevida enquanto finge ajudar, não está? Eu acho que não!",
  ui_story_5088_50881300_22_dialog_content = "Isso é uma mentira! Você não pode me intimidar... Ludweiss, ajuda!",
  ui_story_5088_50881300_23_dialog_content = "Quem sai por aí discutindo com crianças?! Senhora Marcela, você precisa ensinar uma lição a ela!",
  ui_story_5088_50881300_24_dialog_content = "Hã? Não, não, não, eu só estava brincando...",
  ui_story_5088_50881300_25_dialog_content = "<color=#FFB400>Uma ilusão</color>...",
  ui_story_5088_50881300_26_dialog_content = "Sim, esta é a cena que você mais anseia.",
  ui_story_5088_50881300_27_dialog_content = "Ludweiss...",
  ui_story_5088_50881300_28_dialog_content = "Neste sonho feliz, a única coisa que falta é a sua presença.",
  ui_story_5088_50881300_29_dialog_content = "E isso é o suficiente.",
  ui_story_5088_50881300_30_dialog_content = "Aquiles, você é forte o suficiente para reconhecer que isso é apenas uma ilusão, mas fraco no medo de que possa despedaçar essa felicidade.",
  ui_story_5088_50881300_31_dialog_content = "... Você não vai me impedir de sair, vai?",
  ui_story_5088_50881300_32_dialog_content = "Sim.",
  ui_story_5088_50881300_33_dialog_content = "Como essa é a sua fantasia, eu deveria te dizer para ficar.",
  ui_story_5088_50881300_34_dialog_content = "Mas ainda desejo que você explore o novo mundo por mim e me ajude a escrever novos contos de suas viagens.",
  ui_story_5088_50881300_35_dialog_content = "É realmente ok para nós voltarmos ao mundo assim?",
  ui_story_5088_50881300_36_dialog_content = "Você acredita que tal coisa seja simples?",
  ui_story_5088_50881300_37_dialog_content = "Isso não é um jogo onde a vitória leva à ressurreição.",
  ui_story_5088_50881300_38_dialog_content = "Mas mesmo assim, quem não gostaria de se reunir ao seu redor para uma reunião de primavera? Assim, todos reuniram suas forças para o seu herói.",
  ui_story_5088_50881300_39_dialog_content = "E você jurou encontrar uma maneira de se reunir novamente.",
  ui_story_5088_50881300_40_dialog_content = "Você tem razão...",
  ui_story_5088_50881300_41_dialog_content = "Adeus, Ludweiss.",
  ui_story_5088_50881300_42_dialog_content = "Espera.",
  ui_story_5088_50881300_43_dialog_content = "?!",
  ui_story_5088_50881300_44_dialog_content = "Boa viagem.",
  ui_story_5088_50881300_45_dialog_content = "Por favor, cuide de Adras por mim!",
  ui_story_5088_50881300_46_dialog_content = "He...",
  ui_story_5088_50881300_47_dialog_content = "Adeus.",
  ui_story_5088_50881300_48_dialog_content = "... Até a próxima.",
  ui_story_5088_50881300_49_dialog_content = "<color=#e8d9bb>Northland nunca faltou paisagens deslumbrantes e belas flores, mas as pessoas aqui nunca viram uma luz de primavera tão gloriosa quanto esta.</color>",
  ui_story_5088_50881300_50_dialog_content = "<color=#e8d9bb>Neste pequeno canto do mundo, onde o gelo e a neve finalmente derreteram, dentes-de-leão dançam no ar e campos de flores florescem brilhantemente.</color>",
  ui_story_5088_50881300_51_dialog_content = "<color=#e8d9bb>Um arco-íris se inclina contra o Obelisco do Retorno, ouvindo sua canção suave e melodiosa.</color>",
  ui_story_5088_50881300_52_dialog_content = "<color=#e8d9bb>Todos nas proximidades estão profundamente cativados por isso.</color>",
  ui_story_5088_50881300_53_dialog_content = "Depois de dois mil anos, o desejo do nosso clã finalmente se tornou realidade...",
  ui_story_5088_50881300_54_dialog_content = "Obrigado por fazer parte deste mundo.",
  ui_story_5088_50881300_55_dialog_content = "Você me lisonjeia demais...",
  ui_story_5088_50881300_56_dialog_content = "Eu estava completamente perdido uma vez, mas agora entendo a grandeza daqueles que vieram antes de mim.",
  ui_story_5088_50881300_57_dialog_content = "De agora em diante, seguirei o caminho da justiça, assim como meus antepassados - o caminho dos Guerreiros Estelares.",
  ui_story_5088_50881300_58_dialog_content = "Acho que você é bastante impressionante, Mithra... especialmente quando me salvou naquela noite.",
  ui_story_5088_50881300_59_dialog_content = "Apesar da sua confusão, você nunca desistiu.",
  ui_story_5088_50881300_60_dialog_content = "Foi graças a você que consegui despertar Aquiles. Em todas as situações que enfrentamos, você sempre tomou a iniciativa. Você fez tanto.",
  ui_story_5088_50881300_61_dialog_content = "... Hehe.",
  ui_story_5088_50881300_62_dialog_content = "Talvez você tenha razão.",
  ui_story_5088_50881300_63_dialog_content = "Então vamos!",
  ui_story_5088_50881300_64_dialog_content = "Hã?",
  ui_story_5088_50881300_65_dialog_content = "Para me reunir com todos...",
  ui_story_5088_50881300_66_dialog_content = "Uau, é tão bonito! Nunca vi um lugar assim antes.",
  ui_story_5088_50881300_67_dialog_content = "E essas flores...",
  ui_story_5088_50881300_68_dialog_content = "... Crianças?",
  ui_story_5088_50881300_69_dialog_content = "Pare de correr por aí, garotinha, ou você acabará se arranhando com todas as plantas aqui. Venha, vou te mostrar as flores mais bonitas.",
  ui_story_5088_50881300_70_dialog_content = "Ei, senhora! Você é tão alta!",
  ui_story_5088_50881300_71_dialog_content = "Você também gostaria de ser alto?",
  ui_story_5088_50881300_72_dialog_content = "Isso vai fazer?",
  ui_story_5088_50881300_73_dialog_content = "Uau! Você está me levantando! Estou mais alto que todos agora!",
  ui_story_5088_50881300_74_dialog_content = "... Se você sair correndo assim, seus pais vão começar a se preocupar.",
  ui_story_5088_50881300_75_dialog_content = "Está tudo bem, senhor, meu pai está lá com minha mãe olhando as flores!",
  ui_story_5088_50881300_76_dialog_content = "Senhorita, isso... é para você...",
  ui_story_5088_50881300_77_dialog_content = "Obrigado.",
  ui_story_5088_50881300_78_dialog_content = "...",
  ui_story_5088_50881300_79_dialog_content = "Ei, senhor, você não vai vir aqui?",
  ui_story_5088_50881300_80_dialog_content = "Obrigado, mas vou ficar aqui e observar por enquanto.",
  ui_story_5088_50881300_81_dialog_content = "Não! Vamos, senhor!",
  ui_story_5088_50881300_82_dialog_content = "Aquela senhora de rabo de cavalo disse que vai me dar muitos doces deliciosos se eu te levar lá!",
  ui_story_5088_50881300_83_dialog_content = "... Freya?",
  ui_story_5088_50881300_84_dialog_content = "Hehe.",
  ui_story_5088_50881300_85_dialog_content = "Senhor, você está sorrindo!",
  ui_story_5088_50881300_86_dialog_content = "Você tem um sorriso realmente amigável.",
  ui_story_5088_50881300_87_dialog_content = "Vamos, vamos pegar aquele doce delicioso para você.",
  ui_story_5088_50881300_88_dialog_content = "<color=#e8d9bb>E assim, as estrelas encontraram seu lar.</color>",
  ui_story_5088_50881300_89_dialog_content = "<color=#e8d9bb>A história do reino e seus guerreiros pode terminar aqui...</color>",
  ui_story_5088_50881300_90_dialog_content = "<color=#e8d9bb>Mas um novo capítulo vai começar.</color>",
  ui_story_5088_50881300_91_dialog_content = "<color=#e8d9bb>Amid a alegria do reencontro, um novo conto de fadas nascerá...</color>",
  ui_story_5088_50881300_92_dialog_content = "<color=#e8d9bb>E eu posso garantir a você—terá um final feliz.</color>"
}
return config
